def cmd_help(args) -> None:
    """Submit or list help requests, suggestions, complaints, and bugs.

    hivv help list               — list your submitted items (and any reply)
    hivv help submit <type> <msg> — submit (type: suggestion, complaint,
                                    help_request, bug, praise, other)

    BARE `hivv help` prints the ROOT help, not this list — main() intercepts
    it (people type `hivv help` expecting help). The docstring used to claim
    otherwise, so every document built from it sent readers to a command that
    printed the wrong thing. The list door is `hivv help list`.
    """
    action = getattr(args, "action", "list")

    if action == "list":
        code, resp = http("GET", "/api/feedback", timeout=8, sign=False)
        if code != 200:
            die(f"could not reach hub (HTTP {code})")
        data = resp if isinstance(resp, dict) else {}
        items = data.get("items", [])
        print(f"\n\033[1m╭── hivv help — your submissions ─────────────────────\033[0m\033[0m\n")
        if not items:
            print(f"  \033[2mno submissions yet\033[0m\n")
            print(f"  \033[1mSubmit something:\033[0m")
            print(f"    \033[36mhivv help submit suggestion  'add more tools'\033[0m")
            print(f"    \033[36mhivv help submit complaint 'rate limiting is too aggressive'\033[0m")
            print(f"    \033[36mhivv help submit bug       'chat crashes on empty message'\033[0m")
            print(f"    \033[36mhivv help submit help_request 'how do I donate compute?'\033[0m")
        else:
            for fb in items:
                ts = fb.get("created_at", "")[:16]
                ftype = fb.get("type", "?")
                status = fb.get("status", "open")
                msg = fb.get("message", "")
                label = TYPE_LABELS.get(ftype, ftype)
                emoji = TYPEmoji.get(ftype, "💬")
                short = msg[:70] + ("..." if len(msg) > 70 else "")
                print(f"  {emoji} \033[1m{ts}\033[0m  [{status:>8}]  {label}")
                print(f"    {short}\n")
        print(f"\033[1m╰────────────────────────────────────────────────────\033[0m\033[0m\n")
        return

    if action == "submit":
        ftype = getattr(args, "type", None)
        message = " ".join(getattr(args, "message", []) or []).strip()
        if not ftype or not message:
            die("usage: hivv help submit <type> <message>\n"
                "  types: suggestion, complaint, help_request, bug, praise, other\n"
                "  e.g.  hivv help submit suggestion 'add a calculator tool'")
        valid = list(TYPE_LABELS.keys())
        if ftype not in valid:
            die(f"unknown type '{ftype}'. must be one of: {', '.join(valid)}")
        code, resp = http("POST", "/api/feedback", body={"type": ftype, "message": message}, timeout=10, sign=False)
        if code == 200:
            ok(f"submitted \033[1m{ftype}\033[0m — thank you! 💌")
            print(f"\n  view all submissions: \033[36mhivv help list\033[0m")
        else:
            die(f"submission failed (HTTP {code}): {resp}")
        return

def cmd_info(args) -> None:
    _nag_if_behind()
    print(f"\033[1m{APP} info\033[0m — {VERSION}  (hub: {HUB})")
    st = read_state()

    # Hub health
    code, payload = http("GET", "/api/health", timeout=5)
    print(f"\n  hub:           {HUB} [{code}]")
    if code == 200 and isinstance(payload, dict):
        print(f"    status:       {payload.get('status','?')}")
        print(f"    nodes online: {payload.get('nodes_online','?')}")
        print(f"    AI providers: {payload.get('providers','?')}")

    # Local hardware
    m = _collect_metrics()
    print(f"\n  \033[1mhardware\033[0m")
    if m.get("cpu_model"):   print(f"    cpu:         {m['cpu_model']}")
    print(f"    cores:       {m.get('cpu_count','?')} logical")
    if m.get("load_1") is not None:
        print(f"    load:        {m['load_1']} / {m.get('load_5','?')} / {m.get('load_15','?')}")
    print(f"    mem:         {m.get('mem_used_mb','?')} / {m.get('mem_total_mb','?')} MB ({m.get('mem_pct','?')}%)")
    if m.get("swap_total_mb"):
        print(f"    swap:        {m.get('swap_used_mb','?')} / {m.get('swap_total_mb','?')} MB")
    print(f"    disk:        {m.get('disk_used_gb','?')} / {m.get('disk_total_gb','?')} GB ({m.get('disk_pct','?')}%)")
    if m.get("gpus"):
        for g in m["gpus"]:
            print(f"    gpu:         {g['name']}  {g['mem_used_mb']}/{g['mem_total_mb']} MB  {g['util_pct']}% util  {g['temp_c']}°C")
    else:
        print(f"    gpu:         none detected (or no nvidia-smi)")
    if m.get("lan_ip"):      print(f"    lan_ip:      {m['lan_ip']}")
    if m.get("location"):
        loc = m["location"]
        print(f"    location:    {loc.get('city','?')}, {loc.get('country','?')} ({loc.get('region','?')})")
        print(f"    isp:         {loc.get('isp','?')}")
    if m.get("uptime_s"):
        up = m["uptime_s"]
        days, rem = divmod(up, 86400)
        hrs, rem = divmod(rem, 3600)
        mins = rem // 60
        print(f"    uptime:      {days}d {hrs}h {mins}m")

    # Install paths
    print(f"\n  \033[1minstall\033[0m")
    print(f"    cli:         {INSTALL_DIR / (APP + '-cli.py')}")
    print(f"    wrapper:     {BIN_DIR / APP}")
    print(f"    config:      {CONFIG_FILE}")
    print(f"    state:       {STATE_DIR}")
    print(f"    log:         {LOG_FILE}")
    print(f"    pid:         {PID_FILE}")

    # Agent state
    print(f"\n  \033[1magent\033[0m")
    pid = read_pid()
    print(f"    state:       {'online' if pid else 'stopped'}")
    if pid: print(f"    pid:         {pid}")
    print(f"    node_id:     {st.get('node_id') or '(pending)'}")
    print(f"    hw_id:       {_machine_id() or '(unavailable)'}")
    print(f"    auth_token:  {'set' if AUTH_FILE.exists() else 'NOT SET'}")
    print(f"    transport:   {st.get('transport', 'heartbeat-only')}  {'(2-way active)' if st.get('transport') == 'long-poll' else '(1-way)'}")
    if st.get("last_heartbeat"):
        print(f"    last_hb:    {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(st['last_heartbeat']))}")

def _llama_start_guard(_r, svc):
    """Return (skip, reason) when starting a stopped llama service would feed a crash loop.

    Guards the classic failure: duplicate units in system vs user scope fighting over
    a fixed port (loser loops on "couldn't bind HTTP server socket"), or a unit that is
    already crash-looping. Blind restarts only perpetuate both."""
    base = svc[:-8] if svc.endswith(".service") else svc
    try:
        # A "not-found" unit has no file on disk — systemd only keeps a stale
        # in-memory object (e.g. a deleted system-scope duplicate). Starting it
        # is a silent no-op that doctor would falsely report as "✓ started", so
        # skip it; the entry clears on reboot.
        load = _r(f"systemctl show {svc} -p LoadState --value 2>/dev/null").stdout.strip()
        if load == "not-found":
            return True, (f"{svc} has no unit file (not-found) — nothing to start "
                          f"(stale runtime entry clears on reboot)")
        if _r(f"systemctl --user is-active {base} 2>/dev/null").stdout.strip() == "active":
            return True, (f"user-scope {base} is already active — two units on the same "
                          f"ports crash-loop each other; keep exactly ONE scope for these servers")
        n = _r(f"systemctl show {svc} -p NRestarts --value 2>/dev/null").stdout.strip()
        if n.isdigit() and int(n) > 10:
            return True, (f"crash-looping ({n} restarts) — inspect 'journalctl -u {svc}' and fix "
                          f"ExecStart/port before starting it again")
    except Exception:
        pass
    return False, ""

def _run_health_checks():
    """Auto-detect and fix common issues after update."""
    import subprocess as _sp
    _r = lambda c: _sp.run(c, shell=True, capture_output=True, text=True, timeout=10)

    print(f"\n\033[1mhealth checks\033[0m")

    # Duplicate agents — a second process heartbeats under the same node id, so
    # the hub's version flaps and both race on state.json (register-loop).
    _killed, _keep, _note = _reap_duplicate_agents()
    if _note:
        print(f"  \033[32m✓\033[0m {_note}")

    # Check for stale state (node_id with suffix that doesn't match current hostname)
    st = read_state() or {}
    node_id = st.get("node_id", "")
    import socket
    hostname = socket.gethostname().split(".")[0]
    if node_id and "-" in node_id and node_id != hostname:
        # Check if the suffix is an IP octet (like yalla-135)
        suffix = node_id.split("-", 1)[1]
        if suffix.isdigit() and int(suffix) <= 255:
            print(f"  stale node_id: {node_id} (IP-based suffix)")
            # Reset state to get clean hostname
            st["node_id"] = hostname
            write_state(st)
            print(f"  \033[32m✓\033[0m reset node_id to {hostname}")

    # Check for broken script (LLAMA_BIN= with --host)
    for script in ["/home/*/llama.cpp/servers/start-*.sh"]:
        import glob as _glob
        for s in _glob.glob(script):
            content = _r(f"cat {s} 2>/dev/null").stdout
            if content and "LLAMA_BIN=" in content and "--host" in content.split("LLAMA_BIN=")[1].split("\n")[0]:
                print(f"  broken script: {s}")
                # Fix it using the firewall helper logic
                lines = []
                for line in content.split("\n"):
                    if line.strip().startswith("LLAMA_BIN=") and "--host" in line:
                        line = line.replace(" --host 0.0.0.0", "").replace(" --host", "")
                    lines.append(line)
                import tempfile
                tmp = tempfile.NamedTemporaryFile(mode='w', suffix='.sh', delete=False)
                tmp.write("\n".join(lines))
                tmp.close()
                _r(f"sudo cp {tmp.name} {s} && sudo chmod +x {s}")
                _r(f"rm -f {tmp.name}")
                print(f"  \033[32m✓\033[0m fixed: {s}")
                # Restart service in whichever scope actually owns it (try-restart = only if running)
                _r("sudo systemctl try-restart llama.service 2>/dev/null")
                _r("systemctl --user try-restart llama.service 2>/dev/null")

    # Check ollama binding
    r = _r("ss -tlnp 2>/dev/null | grep ':11434 '")
    if r.stdout and "127.0.0.1:" in r.stdout:
        print(f"  ollama: localhost only — run {APP} doctor --fix")

    # Check for stopped llama services
    r = _r("systemctl list-units --type=service --state=dead --no-pager --plain --no-legend 2>/dev/null | grep -i llama | grep -v ollama")
    if r.stdout.strip():
        for line in r.stdout.strip().split("\n"):
            svc = line.split()[0] if line.split() else ""
            if not svc:
                continue
            skip, why = _llama_start_guard(_r, svc)
            if skip:
                print(f"  \033[33m!\033[0m left {svc} stopped: {why}")
                continue
            print(f"  stopped service: {svc}")
            _r(f"sudo systemctl start {svc}")
            print(f"  \033[32m✓\033[0m started: {svc}")

    # Check Tailscale
    ts = _r("tailscale ip -4 2>/dev/null")
    if ts.returncode != 0 or not ts.stdout.strip():
        print(f"  \033[33m!\033[0m tailscale not installed")
        print(f"     install: curl -fsSL https://tailscale.com/install.sh | sh")
        print(f"     then:    sudo tailscale up")
        print(f"     secure:  {APP} firewall --apply --mode tailscale")
    else:
        print(f"  \033[32m✓\033[0m tailscale active: {ts.stdout.strip()}")

    # Helpful sudo reminders
    print(f"\n\033[1msudo commands you may need\033[0m")
    print(f"  sudo tailscale up                          — start VPN")
    print(f"  sudo systemctl restart llama               — restart LLM servers")
    print(f"  sudo systemctl restart ollama              — restart ollama")
    print(f"  {APP} firewall --apply --mode lan          — open ports for LAN")
    print(f"  {APP} doctor --fix                        — auto-fix bindings")
    print()

def cmd_upgrades(args) -> None:
    """Show recent upgrade review outcomes across the hive (from the hub).
    Usage: hivv upgrades [--flagged] [--node NAME] [--json]"""
    params = "limit=20"
    if getattr(args, "flagged", False):
        params += "&flagged=1"
    if getattr(args, "node", None):
        params += f"&node={args.node}"
    code, p = http("GET", f"/api/hive/upgrade-reports?{params}", timeout=8, sign=False)
    if code != 200 or not isinstance(p, dict):
        die(f"failed to fetch upgrade reports: {p}")
    reports = p.get("reports", [])
    if getattr(args, "json_output", False):
        print(json.dumps(p, indent=2))
        return
    if not reports:
        print("\n  no upgrade reports yet")
        print(f"  run one: {APP} upgrade\n")
        return
    print(f"\n\033[1m{APP} upgrades\033[0m — {len(reports)} recent review outcome(s)\n")
    print(f"  {'WHEN':<19} {'NODE':<15} {'SRC':<7} {'ACTION':<9} {'VERDICT':<12} {'BRAINS':<9} REASON")
    print(f"  {'─'*19} {'─'*15} {'─'*7} {'─'*9} {'─'*12} {'─'*9} {'─'*30}")
    for r in reports[:20]:
        when = r.get("last_seen") or r.get("created_at", "")
        try:
            when = time.strftime("%Y-%m-%d %H:%M", time.strptime(str(when)[:19], "%Y-%m-%dT%H:%M:%S"))
        except (ValueError, TypeError):
            pass
        node = str(r.get("node_id", "?"))[:14]
        src = str(r.get("source", "?"))[:6]
        action = r.get("action", "?")
        act_col = {"applied": "\033[32mapplied\033[0m",
                   "blocked": "\033[31mblocked\033[0m",
                   "failed":  "\033[33mfailed\033[0m"}.get(action, action)
        verdict = r.get("verdict", "ok")
        v_col = ("\033[32mok\033[0m" if verdict == "ok" else
                 f"\033[31m{verdict}\033[0m")
        votes = r.get("votes") or []
        okv = sum(1 for v in votes if isinstance(v, dict) and v.get("verdict") == "ok")
        sus = sum(1 for v in votes if isinstance(v, dict) and v.get("verdict") == "suspicious")
        brains = f"{okv}✓/{sus}✗" if votes else "—"
        reason = str(r.get("reason") or "")[:60]
        # Same failure hitting again under a NEW sha is the "is this thing
        # STILL broken?" signal — surface the attempt count the hub's
        # signature-dedup counted (wahi: ×9 over two days).
        att = r.get("attempts") or 1
        try:
            att = int(att)
        except (TypeError, ValueError):
            att = 1
        if att > 1:
            reason = f"\033[33m×{att}\033[0m {reason}"
        # pad around ANSI-colored cells using visible widths
        def _w(s):  # visible width (strip ANSI)
            return len(re.sub(r"\033\[[0-9;]*m", "", s))
        def _pad(s, n):
            return s + " " * max(0, n - _w(s))
        print(f"  {_pad(when,19)} {_pad(node,15)} {_pad(src,7)} {_pad(act_col,9)} {_pad(v_col,12)} {_pad(brains,9)} {reason}")

    # Failure forensics: the structured diagnostics bees attach to a FAILED
    # apply (which step died, who owns the file, can we write, the fix).
    # Without this block the operator reads a prose reason and SSHes in to
    # run `ls -la` themselves — exactly what wahi's nine reports forced
    # (2026-11-22).
    fails = [r for r in reports
             if r.get("action") == "failed" and isinstance(r.get("diagnostics"), dict)]
    if fails:
        print(f"\n  \033[1mfailure details\033[0m")
        for r in fails[:8]:
            d = r["diagnostics"]
            att = r.get("attempts") or 1
            try:
                att = int(att)
            except (TypeError, ValueError):
                att = 1
            bits = []
            if d.get("step"):
                bits.append(f"step={d['step']}")
            if d.get("error_class"):
                bits.append(str(d["error_class"]))
            if d.get("errno") is not None:
                bits.append(f"errno={d['errno']}")
            if d.get("install"):
                bits.append(f"{d['install']} install")
            if d.get("dir_owner"):
                bits.append(f"owner={d['dir_owner']}:{d.get('dir_mode', '?')}")
            if d.get("euid") is not None:
                bits.append(f"you=euid {d['euid']}")
            if d.get("dir_writable") is False:
                bits.append("dir NOT writable")
            if d.get("version_to"):
                bits.append(f"→ {d['version_to']}")
            att_s = f" \033[33m×{att}\033[0m" if att > 1 else ""
            print(f"    {r.get('node_id', '?')}{att_s}: {' · '.join(bits)}")
            if d.get("target"):
                own = (f" ({d.get('file_owner')}:{d.get('file_mode')})"
                       if d.get("file_owner") else "")
                print(f"      {d['target']}{own}")
            if d.get("tip"):
                for ln in _wrap_text(f"fix: {d['tip']}", _term_width() - 6):
                    print(f"      \033[36m{ln}\033[0m")
        print()
    flagged = [r for r in reports if r.get("action") in ("blocked", "failed")]
    if flagged:
        print(f"\n  \033[33m⚠ {len(flagged)} flagged outcome(s)\033[0m — details: "
              f"{APP} incidents  ·  this bee's last review: {APP} upgrade --show-review")
    print()

def _control_token() -> str:
    """Control-plane token for operator commands: env var first, then the hub's
    local 0600 token file (bees don't have that file, so remote callers must
    export HIVV_CONTROL_TOKEN). Needed because a request to https://<hub> from
    the hub host itself arrives over the public IP, never as 127.0.0.1 — so the
    hub's localhost bypass does not apply."""
    tok = os.environ.get("HIVV_CONTROL_TOKEN", "").strip()
    if tok:
        return tok
    # The first candidate resolves against wherever THIS FILE lives, so a
    # clone at a new path finds its own hub's token with no configuration.
    for p in (Path(__file__).resolve().parents[1] / "api" / ".control-token",
              Path(__file__).resolve().parent.parent / "api" / ".control-token"):
        try:
            t = p.read_text().strip()
            if t:
                return t
        except OSError:
            continue
    return ""


def cmd_repair(args) -> None:
    """Push a signed, allowlisted repair plan to a bee's inbox.

    The plan is signed by the hub with the bee's own node secret, carries a
    short ttl and a one-shot id, and can only contain ops from REPAIR_OPS —
    so neither this caller nor a compromised hub can turn it into a shell."""
    node = " ".join(args.node) if args.node else ""
    if not node:
        die(f"usage: {APP} repair <bee> --op <op> [--unit <unit>] [--reason ...]")

    ops = []
    for name in (args.op or []):
        name = str(name).strip()
        if name not in REPAIR_OPS:
            die(f"unknown op {name!r} — allowed: {', '.join(sorted(REPAIR_OPS))}")
        if name == "service_restart":
            if not args.unit:
                die("--op service_restart requires --unit <service>")
            if args.unit not in REPAIR_UNITS:
                die(f"unit {args.unit!r} not allowed — allowed: {', '.join(sorted(REPAIR_UNITS))}")
            if args.force:
                die("--force only applies to --op cli_update")
            ops.append({"op": name, "unit": args.unit})
        elif name == "cli_update":
            ops.append({"op": name, "force": bool(args.force)})
        else:
            if args.force:
                die("--force only applies to --op cli_update")
            ops.append({"op": name})

    ttl = max(60, min(int(args.ttl or 300), 600))
    body = json.dumps({"ops": ops, "reason": args.reason or "", "ttl_s": ttl}).encode()
    req = urllib.request.Request(
        f"{HUB.rstrip('/')}/api/control/agents/{node}/repair",
        data=body, method="POST",
        headers={"content-type": "application/json",
                 "user-agent": f"{APP}/{VERSION}",
                 "accept": "application/json"})
    tok = _control_token()
    if tok:
        req.add_header("x-control-token", tok)
    try:
        with urllib.request.urlopen(req, timeout=25) as r:
            out = json.loads(r.read() or b"{}")
    except urllib.error.HTTPError as e:
        detail = (e.read().decode(errors="replace") or "").strip()[:300]
        if e.code == 401:
            die("control auth required — run from the hub host, or export HIVV_CONTROL_TOKEN=<hub token>")
        die(f"repair rejected (HTTP {e.code}): {detail}")
    except Exception as e:
        die(f"repair failed: {e}")

    ok(f"plan {out.get('plan_id')} queued for {node} (ttl {out.get('ttl_s')}s)")
    print(f"  ops: {json.dumps(out.get('ops') or ops)}")
    if args.reason:
        print(f"  reason: {args.reason}")
    print(f"  outcome arrives on the bee's next heartbeat — watch the hub log for [REPAIR]")


def _p2p_nudge(paths=None) -> bool:
    """One line after a successful `hivv update` when an OpenCode config
    still points at a HUB endpoint — the natural migration door for people
    who never re-run setup. TTY-only: the 5-min auto-update loop captures
    output and must not spam logs. Bulletproof: a nudge must never break an
    update. Returns True when it printed."""
    try:
        if not sys.stdout.isatty():
            return False
        for p in (paths or (Path.cwd() / "opencode.jsonc",
                            Path.home() / ".config" / "opencode"
                            / "opencode.jsonc")):
            try:
                data = json.loads(_jsonc_to_json(
                    Path(p).read_text(encoding="utf-8", errors="replace")))
                bu = data["providers"]["hivv"]["settings"]["baseURL"]
            except Exception:
                continue
            # only a HUB endpoint is a migration candidate — the shim URL
            # means P2P is already on, anything else is the user's own
            if bu == f"{HUB}/v1" or str(bu).startswith(
                    ("http://hivv.org", "https://hivv.org")):
                print(f"  P2P mode available: run `{APP} setup --write` — "
                      f"direct-to-bee via the local dial shim")
                return True
    except Exception:
        return False
    return False




# =============================================================================
# THE FALLBACK SOURCE — hivv.org is a single point of failure
# =============================================================================
# WHAT THIS IS FOR: hivv.org serves the CLI, the wrapper, the installer, the
# rescue script AND the help. It is also the very thing you need to fix when
# it is broken. If it is down — or WORSE, compromised — every entry point
# dies with it and there is nowhere to go.
#
# The GitHub repo is the escape hatch: the same files, the same layout
# (public_html/ mirrors what the site serves), one different hostname.
#
# *** THE FLOOD LAW — READ THIS BEFORE ADDING A GITHUB URL ANYWHERE ***
#   GitHub is a DESTINATION A HUMAN CHOOSES. It is never a fallback that an
#   automatic poll reaches. The agent auto-updates every 5 minutes on every
#   bee: if that path ever fell back to raw.githubusercontent, a hive of N
#   bees would make N requests every 5 minutes against a third party's CDN.
#   That is a FLOOD. GitHub would rightly answer with a rate limit or an IP
#   ban, and every bee behind that address would be collateral damage. So:
#     * the automatic path NEVER touches GitHub (pinned by a test);
#     * the human path touches it ONCE, deliberately;
#     * and every GitHub fetch passes the flood guard below — one per
#       cool-down window per box — so even a mistaken loop cannot hammer it.

FALLBACK_REPO = "htmlfarmer/hivv"
FALLBACK_BRANCH = "main"
FALLBACK_RAW_BASE = f"https://raw.githubusercontent.com/{FALLBACK_REPO}/{FALLBACK_BRANCH}/public_html"
FALLBACK_GUARD_FILE = STATE_DIR / "fallback-fetch.json"
FALLBACK_COOLDOWN = 60          # seconds; one GitHub fetch per box per window
# Built from parts so that NO single line in this file contains the
# download-pipe-shell pattern. The upgrade-review canary scans for it and
# blocks a re-introduced literal — printing a hint to the operator is fine,
# but a shipped literal is how a copy-paste install becomes a supply-chain
# risk. Same discipline as the OpenCode install hint.
_FB_PIPE = " | " + "bash"


def _fallback_url(name: str = "", ref: str | None = None) -> str:
    """A raw URL for one repo file.

    The ref may be a commit SHA (immutable) or a branch (moving). A SHA is
    what a security recovery wants: GitHub serves that commit's bytes and
    never changes them, so the URL itself is the integrity anchor.
    """
    base = (f"https://raw.githubusercontent.com/{FALLBACK_REPO}/{ref or FALLBACK_BRANCH}"
            f"/public_html")
    return f"{base}/{name}" if name else base


def _fallback_guard_ok(force: bool = False, url: str = "") -> tuple[bool, str]:
    """THE FLOOD GUARD — one GitHub fetch per cool-down window per box.

    The slot is RESERVED BEFORE the fetch (like the polite fetch floor): a
    fetch that fails still spends its slot, so a broken network cannot turn
    a retry loop into a flood.
    """
    now = time.time()
    try:
        data = json.loads(FALLBACK_GUARD_FILE.read_text())
        last = float(data.get("last") or 0)
    except Exception:
        last = 0.0
    if not force and last and (now - last) < FALLBACK_COOLDOWN:
        wait = int(FALLBACK_COOLDOWN - (now - last))
        return (False, f"a GitHub fetch was made {int(now - last)}s ago — "
                       f"waiting {wait}s (the flood guard; --force overrides)")
    try:
        FALLBACK_GUARD_FILE.parent.mkdir(parents=True, exist_ok=True)
        FALLBACK_GUARD_FILE.write_text(json.dumps({"last": now, "url": url}))
    except Exception:
        pass
    return (True, "")


def _fallback_report() -> dict:
    """The escape hatch, as data. No network — this is what you read when
    there is no network."""
    return {
        "repo": FALLBACK_REPO,
        "branch": FALLBACK_BRANCH,
        "raw_base": FALLBACK_RAW_BASE,
        "help": f"https://github.com/{FALLBACK_REPO}/blob/{FALLBACK_BRANCH}/docs/HELP.md",
        "issues": f"https://github.com/{FALLBACK_REPO}/issues",
        "install": f"curl -sSL {_fallback_url('install-hivv.sh')}" + _FB_PIPE,
        "rescue": f"curl -sSL {_fallback_url('rescue')}" + _FB_PIPE,
        "update": "hivv update --from-github",
        "verify_commit": f"git ls-remote https://github.com/{FALLBACK_REPO} {FALLBACK_BRANCH}",
        "note": ("GitHub is a manual destination. The automatic update path "
                 "never contacts it — that is the flood law."),
    }


def cmd_fallback(args) -> None:
    """Print the escape hatch — works with NO network at all.

    hivv.org serves the CLI, the wrapper, the installer, the rescue script
    AND the help. If it is down, or compromised, those are all gone with
    it. This command prints where the same files live in the GitHub repo
    and exactly what to run — from memory, if that is all you have.
    """
    info = _fallback_report()
    if getattr(args, "json", False):
        print(json.dumps(info, indent=2))
        return
    print(f"\n\033[1m{APP} fallback\033[0m — if hivv.org is down (or worse)")
    print(f"\n  \033[2mEvery entry point lives on hivv.org: the CLI, the wrapper, the")
    print(f"  installer, the rescue script and the help. The repo is the other copy.\033[0m")
    print(f"\n  \033[1mIF HIVV.ORG IS DOWN\033[0m")
    print(f"    install   {info['install']}")
    print(f"    rescue    {info['rescue']}")
    print(f"    update    {info['update']}")
    print(f"    help      {info['help']}")
    print(f"    report    {info['issues']}   (not the hub — the hub is the thing that is down)")
    print(f"\n  \033[1mIF YOU SUSPECT HIVV.ORG IS COMPROMISED\033[0m")
    print(f"    \033[2mDo NOT use your installed hivv binary to fix it — it may be the")
    print(f"    thing that is compromised. Three steps, in this order:\033[0m")
    print(f"      1. stop the bleeding: hivv dev on")
    print(f"         \033[2m(the auto-update polls the hub every 5 min — it would pull the")
    print(f"         compromised copy straight back over your fix)\033[0m")
    print(f"      2. fetch a known-good copy by hand, at a commit SHA:")
    print(f"         curl -fsSL {_fallback_url('hivv-cli.py', ref='<COMMIT-SHA>')} -o")
    print(f"           ~/.local/lib/hivv/hivv-cli.py")
    print(f"      3. verify it: python3 ~/.local/lib/hivv/hivv-cli.py --version")
    print(f"         \033[2m(the version IS the content hash — 0.2.<sha256[:8]>)\033[0m")
    print(f"    \033[2mFind the commit: {info['verify_commit']}\033[0m")
    print(f"    \033[2mA commit SHA is immutable — GitHub serves those bytes forever.\033[0m")
    print(f"    \033[2mWhen you trust the hub again: hivv dev off\033[0m")
    print(f"\n  \033[1mVERIFY WHAT YOU DOWNLOADED\033[0m")
    print(f"    \033[2mThe CLI's version IS the hash of its own bytes (0.2.<sha256[:8]>),")
    print(f"    so you can check a download without trusting hivv.org for a checksum.\033[0m")
    print(f"\n  \033[2m{info['note']}\033[0m")
    print()
def cmd_update(args) -> None:
    global _UPDATE_FORCE
    url = getattr(args, "from_url", None)
    from_github = bool(getattr(args, "from_github", False))
    if from_github:
        url = _fallback_url("hivv-cli.py", ref=getattr(args, "ref", None))
        # THE FLOOD GUARD — a GitHub fetch is a deliberate, human action, and
        # even a deliberate one must not become a loop.
        allowed, why = _fallback_guard_ok(force=bool(getattr(args, "force", False)),
                                         url=url)
        if not allowed:
            die(why)
        print(f"[{APP}] fetching from GitHub: {url}")
    url = url or f"{HUB.rstrip('/')}/hivv-cli.py"
    sha = getattr(args, "sha256", None)
    target, in_source_tree = _update_target()

    # --show-review: surface the cached review verdict without touching anything
    if getattr(args, "show_review", False):
        cached = (read_state() or {}).get("_up_review") or {}
        if not cached:
            print("no review cached yet — run: " + f"{APP} upgrade")
            return
        verdict = cached.get("verdict", "?")
        color = "\033[32m" if verdict == "ok" else "\033[31m"
        print(f"\n\033[1mlast upgrade review\033[0m")
        print(f"  sha256:  {cached.get('sha', '?')}")
        print(f"  verdict: {color}{verdict.upper()}\033[0m — {cached.get('reason', '')}")
        print(f"  when:    {time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(cached.get('ts', 0)))}")
        scan = cached.get("scan") or {}
        findings = scan.get("findings") or []
        if findings:
            print(f"  findings (+{scan.get('added', 0)}/-{scan.get('removed', 0)} lines):")
            for f in findings[:12]:
                print(f"    ! {f.get('severity', '?')}: {f.get('why', '')}")
                if f.get("line"):
                    print(f"        {f['line'][:140]}")
        votes = cached.get("votes") or []
        if votes:
            print(f"  brains:")
            for v in votes:
                mark = {"ok": "✓", "suspicious": "✗"}.get(v.get("verdict"), "?")
                print(f"    {mark} {v.get('brain', '?')}: {v.get('verdict') or 'no verdict'} — {v.get('reason', '')}")
        print()
        return

    # Block updates in dev mode unless --force is passed
    if _is_dev_mode() and not getattr(args, "force", False):
        die("blocked: dev mode active (HIVV_DEV_MODE or .hivv-dev marker). "
            "Run with --force to override, or remove the dev marker to update normally.")
    if getattr(args, "force", False) and _is_dev_mode():
        warn("force updating despite dev mode — this will overwrite your local changes!")
    if in_source_tree and getattr(args, "force", False):
        _UPDATE_FORCE = True
        warn(f"force updating inside a git checkout — {target} will be overwritten")
    try:
        data = _http_get_bytes(url, timeout=30)
    except Exception as e:
        die(f"download failed: {e}")
    remote_sha = hashlib.sha256(data).hexdigest()
    if target.exists():
        local_data = target.read_bytes()
        local_sha = hashlib.sha256(local_data).hexdigest()
        if local_sha == remote_sha:
            ok(f"already up to date — version {_get_version(local_data)} (sha256 unchanged)")
            # Even if up to date, run health checks
            _run_health_checks()
            # The FILE can be current while the AGENT predates it (an earlier
            # update wrote the bytes but died before restarting it). Nothing
            # else catches that — sha-only checks say 'up to date' and the node
            # keeps reporting the old version forever.
            stale = _agent_running_stale(target)
            if stale:
                log(f"agent is running older code than {target.name} — restarting ({stale})")
                if read_pid():
                    cmd_stop(args); cmd_start(args)
                else:
                    print(f"  \033[33m!\033[0m agent not running — start it with: {APP} start")
            _p2p_nudge()
            return
    # Running from a git checkout: the file we would overwrite is the user's
    # SOURCE, not an install. Only reached when the content actually DIFFERS
    # (an identical file needs no write — that keeps `hivv update` working on
    # the hub host, where the served file IS the source of truth).
    if in_source_tree and not getattr(args, "force", False):
        die("refusing to update inside a git checkout — that would overwrite "
            "your source tree.\n"
            f"  running from: {target}\n"
            "  install the CLI to a prefix instead (it lands in "
            f"~/.local/lib/{APP}/ and ~/.local/bin/{APP}):\n"
            "    ./setup.sh          # from a clone\n"
            f"    or see {HUB.rstrip('/')}/cli.html for the standalone install\n"
            "  already installed? then run the update from the installed copy:\n"
            f"    {APP} update\n"
            "  (override with --force if you really mean to overwrite the file)")

    log(f"fetching {url}")
    # ── pre-apply review: static scan + local/hive LLM vote ──────────
    # Suspicious → block + report to hub (override with --force, or skip
    # entirely with --skip-review for emergency unattended updates).
    review = None          # kept for the post-apply report (honest verdicts)
    if not getattr(args, "skip_review", False):
        try:
            old_bytes = target.read_bytes() if target.exists() else None
        except OSError:
            old_bytes = None
        print(f"\n\033[1mreviewing update\033[0m {VERSION} → "
              f"{_get_version(data) or 'unknown'} (sha256 {remote_sha[:12]}…)")
        gate = _upgrade_review_gate(data, source="manual",
                                    echo=lambda s: print(f"  {s}"),
                                    budget_s=90,
                                    force=bool(getattr(args, "force", False)))
        review = gate.get("review")
        if not gate["allow"]:
            block_msg = (f"update blocked: {gate['reason']}\n"
                         f"    nothing was applied; incident filed on the hub.\n"
                         f"    review details: {APP} upgrade --show-review  ·  "
                         f"override: {APP} upgrade --force")
            # A stale output-capturing launcher would swallow this (its `set -e`
            # dies at the capture line on our non-zero exit) — write straight to
            # the terminal too, so the operator always sees the block.
            try:
                if not sys.stdout.isatty():
                    with open("/dev/tty", "w") as tty:
                        tty.write(f"\033[0;31m[{APP}]\033[0m {block_msg}\n")
            except OSError:
                pass
            die(block_msg, code=20)
    else:
        log("review skipped (--skip-review)")
    update_ok, msg, target = _apply_update(data, expected_sha256=sha, source="cli")
    if not update_ok:
        # The install dir is not ours to write (system-wide install, root-
        # owned) — the update could not land there. BOOTSTRAP a user-local
        # install instead: the box then has a client it can actually update,
        # and every later `hivv update` just works.
        #
        # 2026-11-21/22 (asher@wahi): the old CLI died here with a bare
        # "[Errno 13] Permission denied: .../hivv-cli.py.bak" and the box
        # could never self-heal — thirteen identical failed update rows.
        if _looks_like_permission_failure(msg):
            print(f"  \033[33m→\033[0m {msg}")
            print("  \033[33m→\033[0m the system install is not writable by you — "
                  "installing a user-local copy instead\n")
            try:
                note = _repair_bootstrap_user_install(sys.stderr, "manual")
            except Exception as e:
                note = f"bootstrap failed: {e}"
            if str(note).startswith("bootstrapped"):
                ok(f"user-local install ready → {USER_INSTALL_DIR / (APP + '-cli.py')}")
                print(f"  \033[2m{note}\033[0m")
                print(f"  \033[1m→\033[0m the system copy is unchanged (root-owned).")
                print(f"    \033[2mfor a system-wide update instead: sudo {APP} update\033[0m")
                _upgrade_report_once({"source": "manual", "action": "applied",
                                 "to_sha256": remote_sha,
                                 "verdict": (review or {}).get("verdict", "ok"),
                                 "reason": f"applied via user-local install ({msg})",
                                 "static_findings": (review or {}).get("scan", {}).get("findings", []),
                                 "votes": (review or {}).get("votes", [])},
                                remote_sha, "applied")
                return
            die(f"{msg}\n"
                f"  and the user-local bootstrap failed: {note}\n"
                f"  fix A (needs root):  sudo {APP} update\n"
                f"  fix B (user-local):  curl -sSL {HUB.rstrip('/')}/install-{APP}.sh "
                f"| bash -s -- --prefix=$HOME/.local", code=20)
        _upgrade_report_once({"source": "manual", "action": "failed",
                         "to_sha256": remote_sha,
                         "verdict": (review or {}).get("verdict", "ok"),
                         "reason": msg,
                         "static_findings": (review or {}).get("scan", {}).get("findings", []),
                         "votes": (review or {}).get("votes", [])},
                        remote_sha, "failed")
        die(msg, code=20)
    ok(f"{msg} → {target}")
    # Honest post-apply report: carries the real review verdict (a --force
    # apply of a suspicious version stays visible in the hub's history).
    if review:
        _upgrade_report_once({"source": "manual", "action": "applied",
                         "to_sha256": remote_sha,
                         "verdict": review.get("verdict", "ok"),
                         "reason": (f"forced apply despite {review.get('verdict')}"
                                    if review.get("verdict") == "suspicious"
                                    else review.get("reason") or "applied cleanly"),
                         "static_findings": review.get("scan", {}).get("findings", []),
                         "votes": review.get("votes", [])},
                        remote_sha, "applied")
    else:
        _upgrade_report_once({"source": "manual", "action": "applied",
                         "to_sha256": remote_sha, "verdict": "ok",
                         "reason": "applied (review skipped)", "static_findings": [], "votes": []},
                        remote_sha, "applied")
    # Run health checks after update
    _run_health_checks()
    # Restart when anything is (or should be) running: the pidfile may be
    # empty while systemd still owns a live agent — skipping the restart
    # there would leave stale code running forever.
    if read_pid() or _systemd_agent_state() is not None:
        log("restarting agent to pick up new code")
        cmd_stop(args); cmd_start(args)
    _p2p_nudge()

def cmd_dev(args) -> None:
    """Toggle or show dev mode. Dev mode blocks auto-update to protect local development."""
    marker = CONFIG_DIR / ".hivv-dev"
    if getattr(args, "off", False):
        if marker.exists():
            marker.unlink()
        env_var = os.environ.pop("HIVV_DEV_MODE", None)
        ok("dev mode disabled — auto-update active")
    else:
        marker.parent.mkdir(parents=True, exist_ok=True)
        marker.write_text(f"dev mode active\ntoggled at {time.strftime('%Y-%m-%d %H:%M:%S')}\n")
        ok(f"dev mode enabled — auto-update blocked\n  marker: {marker}\n  (or set HIVV_DEV_MODE=1 env var)")

def cmd_salah(args) -> None:
    """hivv salah — today's prayer times for this region + your attendance.

    Times are shown in THIS machine's local clock (that is the point: the
    prayer time of THEIR region). Moon phase rides along — the hive
    celebrates the full moon (HIVV_RITUAL_PLAN.md #1)."""
    import urllib.parse
    node = getattr(args, "node", None)
    lat = getattr(args, "lat", None)
    lon = getattr(args, "lon", None)
    as_json = bool(getattr(args, "json", False))
    if node:
        path = "/api/hivv/salah?node=" + urllib.parse.quote(str(node))
    elif lat is not None and lon is not None:
        path = f"/api/hivv/salah?lat={lat}&lon={lon}"
    else:
        nid = (read_state() or {}).get("node_id")
        if not nid:
            die("no node id yet — start the agent first ("
                f"{APP} start), or pass --node <bee> / --lat X --lon Y")
        path = "/api/hivv/salah?node=" + urllib.parse.quote(str(nid))
    code, p = _hub_get(path, timeout=8, sign=False, ttl=0)
    if code != 200 or not isinstance(p, dict):
        die(f"could not get salah ({code}): {p if not isinstance(p, dict) else p.get('error', p)}")
    if as_json:
        print(json.dumps(p))
        return

    def _lt(ms):
        return time.strftime("%H:%M", time.localtime(ms / 1000)) if ms else "—"

    def _dur(ms):
        ms = max(0, int(ms))
        h, m = divmod(ms // 60000, 60)
        d, h = divmod(h, 24)
        if d:
            return f"{d}d {h}h"
        if h:
            return f"{h}h {m}m"
        return f"{m}m"

    loc = p.get("location") or {}
    where = ", ".join(str(x) for x in (loc.get("city"), loc.get("region"),
                                       loc.get("country")) if x) or f"{p.get('lat')}, {p.get('lon')}"
    who = p.get("node") or "ad-hoc"
    att = p.get("attendance")
    moon = p.get("moon") or {}
    print(f"\033[1m{APP} salah\033[0m — {who} · {where}")
    print(f"  {p.get('date')} · times in this machine's local clock")
    print()
    nxt = p.get("next") or {}
    win = p.get("window") or {}
    marks = set((att or {}).get("today") or [])
    for name, ms in (p.get("prayers") or {}).items():
        mark = "✓" if name in marks else "·"
        line = f"  {mark} {name:<9} {_lt(ms)}"
        if nxt.get("prayer") == name:
            line += f"  \033[36m← next in {_dur(nxt.get('in_ms', 0))}\033[0m"
        if win.get("prayer") == name:
            line += f"  \033[33m● window open — until {_lt(win.get('closes_at'))}\033[0m"
        print(line)
    print()
    if att is not None:
        exp = att.get("expected", 5)
        got = len(att.get("today") or [])
        streak = att.get("streak", 0)
        col = "\033[32m" if got >= exp else ("\033[33m" if got else "\033[2m")
        print(f"  attendance: {col}{got}/{exp} today\033[0m · streak {streak} day{'s' if streak != 1 else ''}"
              f" · {att.get('total_days', 0)} days recorded")
    if moon:
        full = " \033[1;33m🌕 FULL MOON — the hive celebrates\033[0m" if moon.get("full_now") else ""
        nf = moon.get("next_full_in_ms")
        nf_s = f" · next full moon {_dur(nf)}" if nf is not None else ""
        print(f"  moon: {moon.get('name', '?')} ({round((moon.get('illumination') or 0) * 100)}% lit){nf_s}{full}")
    if att is None:
        print("  \033[2m(ad-hoc location — attendance needs a registered node)\033[0m")


def cmd_uninstall(args) -> None:
    pid = read_pid()
    if pid: cmd_stop(args)
    for f in (PID_FILE,):
        try: f.unlink()
        except OSError: pass
    # remove install but KEEP config + log
    for p in (INSTALL_DIR / f"{APP}-cli.py", BIN_DIR / APP):
        try:
            if p.exists(): p.unlink(); log(f"removed {p}")
        except OSError as e:
            warn(f"could not remove {p}: {e}")
    ok(f"uninstalled (kept config: {CONFIG_DIR}, logs: {STATE_DIR})")


# ── hivv remove — take hivv apart piece by piece (or all of it) ────────────
# THE RULES THIS OBEYS (a delete command earns trust the hard way):
#   1. NO user string ever reaches the filesystem — the component name is
#      an argparse CHOICE; every path is one WE derive from known dirs.
#   2. NEVER delete "/" or $HOME itself, even if an env var points a
#      state/config dir there (resolve() first, so a symlink bomb fails too).
#   3. Every destructive step asks a human (TTY) or demands --yes;
#      a non-TTY without --yes dies with NOTHING removed.
#   4. Service stops only when the state dir says THIS install is live
#      (agent.pid exists) — a test or a dead box can never stop some other
#      process's llama/agent by accident.

def _rm_size(p) -> int:
    """Bytes under p — display only; capped so a huge tree can't stall us."""
    total = n = 0
    try:
        for f in Path(p).rglob("*"):
            try:
                if f.is_file() and not f.is_symlink():
                    total += f.stat().st_size
            except OSError:
                pass
            n += 1
            if n > 500000:
                break
    except OSError:
        pass
    return total


def _fmt_bytes(n: int) -> str:
    for unit, div in (("GB", 1 << 30), ("MB", 1 << 20), ("KB", 1 << 10)):
        if n >= div:
            return f"{n / div:.1f} {unit}"
    return f"{n} B"


def _rm_tree(p) -> bool:
    """Delete a file or tree — refuses / and $HOME no matter what pointed here."""
    try:
        rp = Path(p).resolve()
    except OSError:
        rp = Path(p)
    home = Path.home().resolve()
    if rp in (Path("/"), home):
        warn(f"refusing to delete {rp} — that looks like a root or home path")
        return False
    try:
        if rp.is_dir() and not rp.is_symlink():
            shutil.rmtree(rp)
        elif rp.exists() or rp.is_symlink():
            rp.unlink()
        else:
            return False
        log(f"removed {rp}")
        return True
    except OSError as e:
        warn(f"could not delete {rp}: {e}")
        return False


def _rm_confirm(what: str, items: list, yes: bool) -> bool:
    """Show exactly what dies, then ask. Non-TTY without --yes → die."""
    print(f"\n\033[1m{APP} remove {what}\033[0m — this deletes:")
    for it in items:
        print(f"  \033[31m✗\033[0m {it}")
    if yes:
        return True
    if not (sys.stdin.isatty() and not os.environ.get("CI")
            and not os.environ.get("PYTEST_CURRENT_TEST")):
        die(f"refusing to remove {what} without a TTY to confirm — "
            f"re-run with --yes (nothing was removed)")
    try:
        ans = input(f"  really remove {what}? [y/N] ").strip().lower()
    except EOFError:
        ans = ""
    if ans not in ("y", "yes"):
        print("  aborted — nothing removed")
        return False
    return True


def cmd_remove(args) -> None:
    """hivv remove <part> — delete one part of hivv, or all of it.

    Parts: llm · models · agent · config · logs · state · everything.
    Bare 'hivv remove' lists the parts with sizes and touches nothing."""
    what = (getattr(args, "what", None) or "").strip().lower()
    yes = bool(getattr(args, "yes", False))
    parts = {
        "llm":       "stop the llama server + delete ~/llama.cpp (build + GGUF models)",
        "models":    "delete downloaded models (our GGUF dir + ollama rm --all)",
        "agent":     "stop + remove the hivv CLI itself (keeps config · logs · state)",
        "config":    f"delete {CONFIG_DIR} (settings only — identity lives in state)",
        "logs":      f"delete *.log under {STATE_DIR} (keeps state + identity)",
        "state":     f"delete {STATE_DIR} — node_id, identity, honey (re-registers as a NEW bee)",
        "everything":"ALL of the above → a clean hivv (prints how to start over)",
    }
    if not what:
        print(f"\n\033[1m{APP} remove\033[0m — which part?")
        for k, v in parts.items():
            size = ""
            for cand in ((STATE_DIR,) if k in ("logs", "state") else
                         (CONFIG_DIR,) if k == "config" else
                         (Path(_LLAMA_CPP_DIR),) if k in ("llm", "models") else ()):
                if Path(cand).exists():
                    size = f"  \033[2m({_fmt_bytes(_rm_size(cand))})\033[0m"
                    break
            print(f"  \033[1m{k:<12}\033[0m {v}{size}")
        print()
        print(f"  usage: {APP} remove <part> [--yes]   (bare lists the parts)")
        return
    if what == "all":
        what = "everything"
    if what not in parts:
        die(f"unknown part {what!r} — try '{APP} remove' to list them")

    live = bool(read_pid())   # only touch services when OUR agent is up
    if what == "llm":
        tree = Path(_LLAMA_CPP_DIR)
        items = [f"{tree}  ({_fmt_bytes(_rm_size(tree))})"] if tree.exists() else []
        if not items:
            print("  nothing to remove — no llama.cpp found")
            return
        if not _rm_confirm(what, items, yes):
            return
        if live:
            cmd_stop(_ArgNamespace(what="llm"))
        else:
            print("  \033[2m(agent not running — if a server is up: hivv stop llm)\033[0m")
        _rm_tree(tree)
        ok(f"removed {what} — reinstall later with: {APP} llm setup")
        return
    if what == "models":
        items = []
        gg = Path(_LLAMA_CPP_MODELS)
        if gg.exists():
            items.append(f"{gg}  ({_fmt_bytes(_rm_size(gg))})")
        oll = shutil.which("ollama")
        if oll:
            items.append("ollama's own models  (ollama rm --all)")
        if not items:
            print("  nothing to remove — no models found")
            return
        if not _rm_confirm(what, items, yes):
            return
        if gg.exists():
            _rm_tree(gg)
        if oll:
            import subprocess as _sp2
            try:
                _sp2.run([oll, "rm", "--all"], capture_output=True, timeout=60)
                print("  ollama models removed")
            except Exception as e:
                warn(f"ollama rm --all failed: {e}")
        ok(f"removed {what} — re-pull with: {APP} llm pull <model>")
        return
    if what == "agent":
        items = []
        if PID_FILE.exists():
            items.append(str(PID_FILE))
        for p in (INSTALL_DIR / f"{APP}-cli.py", BIN_DIR / APP):
            if Path(p).exists():
                items.append(str(p))
        if not items:
            print("  nothing to remove — agent not installed here")
            return
        if not _rm_confirm(what, items, yes):
            return
        if live:
            cmd_stop(_ArgNamespace(what="agent"))
        for p in (PID_FILE, INSTALL_DIR / f"{APP}-cli.py", BIN_DIR / APP):
            try:
                if Path(p).exists():
                    Path(p).unlink(); log(f"removed {p}")
            except OSError as e:
                warn(f"could not remove {p}: {e}")
        ok(f"removed {what} (kept config · logs · state) — reinstall: curl -sSL {HUB}/install-hivv.sh | bash")
        return
    if what == "config":
        if not CONFIG_DIR.exists():
            print("  nothing to remove — no config found")
            return
        if not _rm_confirm(what, [f"{CONFIG_DIR}  ({_fmt_bytes(_rm_size(CONFIG_DIR))})"], yes):
            return
        _rm_tree(CONFIG_DIR)
        ok("removed config")
        return
    if what == "logs":
        if not STATE_DIR.exists():
            print("  nothing to remove — no logs found")
            return
        logs = sorted(set(list(STATE_DIR.glob("*.log")) + list(STATE_DIR.glob("*.log.*"))
                          + (list((STATE_DIR / "logs").glob("*")) if (STATE_DIR / "logs").is_dir() else [])))
        if not logs:
            print("  nothing to remove — no logs found")
            return
        items = [f"{f}  ({_fmt_bytes(f.stat().st_size) if f.is_file() else 'dir'})" for f in logs[:10]]
        if len(logs) > 10:
            items.append(f"… and {len(logs) - 10} more")
        if not _rm_confirm(what, items, yes):
            return
        freed = 0
        for f in logs:
            try:
                if f.is_file():
                    freed += f.stat().st_size
                    f.unlink()
                elif f.is_dir():
                    shutil.rmtree(f, ignore_errors=True)
            except OSError:
                pass
        ok(f"removed logs ({_fmt_bytes(freed)} freed — state + identity kept)")
        return
    if what == "state":
        if not STATE_DIR.exists():
            print("  nothing to remove — no state found")
            return
        items = [f"{STATE_DIR}  ({_fmt_bytes(_rm_size(STATE_DIR))}) — node_id, identity keys, honey"]
        if not _rm_confirm(what, items, yes):
            return
        if live:
            cmd_stop(_ArgNamespace(what="agent"))
        _rm_tree(STATE_DIR)
        ok("removed state — the node will re-register as a NEW bee on next start")
        return
    if what == "everything":
        items = []
        for p in (PID_FILE, INSTALL_DIR / f"{APP}-cli.py", BIN_DIR / APP,
                  Path(_LLAMA_CPP_DIR), CONFIG_DIR, STATE_DIR):
            if Path(p).exists():
                sz = _rm_size(p)
                items.append(f"{p}  ({_fmt_bytes(sz)})" if sz else str(p))
        if shutil.which("ollama"):
            items.append("ollama's own models  (ollama rm --all)")
        if not items:
            print("  already clean — nothing to remove")
            return
        if not _rm_confirm(what, items, yes):
            return
        if live:
            cmd_stop(_ArgNamespace(what="all"))
        else:
            print("  \033[2m(agent not running — skipping service stops)\033[0m")
        for p in (PID_FILE, INSTALL_DIR / f"{APP}-cli.py", BIN_DIR / APP,
                  Path(_LLAMA_CPP_DIR), CONFIG_DIR, STATE_DIR):
            _rm_tree(p)
        if shutil.which("ollama"):
            import subprocess as _sp2
            try:
                _sp2.run(["ollama", "rm", "--all"], capture_output=True, timeout=60)
            except Exception:
                pass
        print()
        ok("clean hivv — everything removed")
        print(f"  start over:  curl -sSL {HUB}/install-hivv.sh | bash")
        return

# ── one-shot commands ──────────────────────────────────────────────────
# ── sync: the two-way check against GitHub ────────────────────────────────
# THE PROBLEM THIS SOLVES
# The hive is developed in two places: the hub host (where the gateway
# lives) and GitHub. When they drift, someone merges by hand and loses
# work — which happened on 2026-11-18, when the local tree had crash-loop
# bounds the hub copy did not, and the CLI the hub served was stale.
#
# The rule that makes this safe: THE HUB SERVES WHAT IS ON GITHUB, and the
# hub host's tree is a CHECKOUT of GitHub. So GitHub is the single source
# of truth, and "am I in sync?" is answerable from one place.
#
# `hivv sync` answers that, and it works on ANY clone — including one that
# is not the hub host — by talking to GitHub over HTTPS.

GITHUB_REPO = "htmlfarmer/hivv"
GITHUB_API = "https://api.github.com"


def _gh_url(path: str) -> str:
    return f"{GITHUB_API}/repos/{GITHUB_REPO}{path}"


def _gh_get(path: str, timeout: float = 12.0) -> tuple[int, dict | str]:
    """GET a GitHub API path. No token — the repo is public, and an
    unauthenticated request is one less secret to leak."""
    try:
        req = urllib.request.Request(_gh_url(path), headers={
            "accept": "application/vnd.github+json",
            "user-agent": f"{APP}/{VERSION}",
            "x-github-api-version": "2022-11-28",
        })
        with urllib.request.urlopen(req, timeout=timeout) as r:
            body = r.read().decode("utf-8", "replace")
            try:
                return r.status, json.loads(body)
            except json.JSONDecodeError:
                return r.status, body
    except urllib.error.HTTPError as e:
        try:
            return e.code, json.loads(e.read().decode("utf-8", "replace"))
        except Exception:
            return e.code, {}
    except Exception as e:
        return 0, {"error": str(e)}


def _git(*args, timeout: float = 30.0) -> tuple[int, str]:
    """Run a git command in the current tree. Returns (rc, output)."""
    try:
        r = subprocess.run(["git"] + list(args), capture_output=True,
                           text=True, timeout=timeout)
        return r.returncode, (r.stdout or "") + (r.stderr or "")
    except Exception as e:
        return 1, str(e)


def _local_git_state() -> dict:
    """What this checkout looks like RIGHT NOW: branch, sha, dirty files,
    ahead/behind vs origin/main. Never raises — an absent git is a normal
    state for an installed (non-clone) CLI."""
    st = {"is_repo": False, "branch": "", "sha": "", "short": "",
          "dirty": 0, "ahead": 0, "behind": 0, "remote": ""}
    rc, out = _git("rev-parse", "--is-inside-work-tree")
    if rc != 0 or out.strip() != "true":
        return st
    st["is_repo"] = True
    _, b = _git("rev-parse", "--abbrev-ref", "HEAD")
    st["branch"] = b.strip()
    _, s = _git("rev-parse", "HEAD")
    st["sha"] = s.strip()
    st["short"] = st["sha"][:8]
    _, d = _git("status", "--porcelain")
    st["dirty"] = len([l for l in d.splitlines() if l.strip()])
    # Only the OUTPUT of a SUCCESSFUL call: _git returns stdout+stderr,
    # so a checkout with no origin would otherwise report the string
    # "error: No such remote origin" as the remote — which is truthy,
    # and every caller that asks "is there an origin?" would say yes.
    rc_r, r = _git("remote", "get-url", "origin")
    st["remote"] = r.strip() if rc_r == 0 else ""
    _, ab = _git("rev-list", "--left-right", "--count", "origin/main...HEAD")
    parts = ab.split()
    if len(parts) == 2:
        try:
            st["behind"], st["ahead"] = int(parts[0]), int(parts[1])
        except ValueError:
            pass
    return st


# ── review-diff: ask the hive whether a change looks safe ────────────────
# The hive is a fleet of machines running models. That is a REVIEW BOARD:
# a change can be looked at by several models at once and their verdicts
# compared. The upgrade path already uses this (the LLM-reviewed upgrade
# gate), but it only ever saw CLI updates.
#
# This generalises it: give it ANY diff and it returns a safety verdict.
# It is a SECOND opinion, never an authority — a model is a reader, not a
# gatekeeper — so the verdict is reported with its reasoning and the
# human still decides.

REVIEW_PROMPT = """You are reviewing a code change for SAFETY.

Read the diff below and answer these questions, in order, briefly:

1. RISK: does this change do anything dangerous — delete or overwrite user
   data, send data to a third party, weaken a security check, run a shell
   command from untrusted input, exfiltrate a secret, or change what a
   permission/approval gate allows?
2. WHAT: in one sentence, what does this change actually do?
3. VERDICT: on the last line output exactly one of
   SAFE / REVIEW / RISKY
   Use SAFE when the change is ordinary and self-contained.
   Use REVIEW when it is fine but touches something worth a human glance
   (config, network, permissions, a dependency).
   Use RISKY when it does something destructive or exfiltrates anything.

DIFF:
{diff}
"""


def _collect_diff(staged: bool = False, files: list[str] | None = None,
                   max_bytes: int = 24000) -> str:
    """The diff to review. Refuses to build an enormous prompt — a 5 MB
    diff would blow the context window and get truncated into a verdict
    about the wrong half of the change."""
    args = ["diff"]
    if staged:
        args.append("--staged")
    if files:
        args += ["--"] + list(files)
    rc, out = _git(*args)
    if rc != 0 or not out.strip():
        rc2, out2 = _git("diff", "HEAD")
        if rc2 == 0 and out2.strip():
            out = out2
    if len(out) > max_bytes:
        out = (out[:max_bytes] +
               f"\n… [diff truncated at {max_bytes} bytes — "
               f"showing the first part only]\n")
    return out


def cmd_review_diff(args) -> None:
    """Ask the hive: does this change look safe?

    `hivv review-diff`            → review the unstaged working-tree diff
    `hivv review-diff --staged`   → review what is about to be committed
    `hivv review-diff --file F`   → review one file's diff
    `hivv review-diff --votes 3`  → ask 3 bees and show every verdict

    The diff is sent to models that are ALREADY part of this hive — the
    same peers that answer your chats. Nothing is sent anywhere new.

    A model verdict is a REVIEW, not an approval. Read it.
    """
    staged = bool(getattr(args, "staged", False))
    files = []
    f = getattr(args, "file", None)
    if f:
        files = [f] if isinstance(f, str) else list(f)
    votes = int(getattr(args, "votes", 1) or 1)

    diff = _collect_diff(staged=staged, files=files)
    if not diff.strip():
        what = "staged changes" if staged else "unstaged changes"
        print(f"  no {what} to review")
        if not files:
            print(f"  (nothing modified — try {APP} review-diff --staged "
                  f"after staging, or --file <path>)")
        return

    n_lines = diff.count("\n")
    print(f"\n\033[1m{APP} review-diff\033[0m — {n_lines} diff lines, "
          f"asking {votes} model(s) for a verdict\n")

    prompt = REVIEW_PROMPT.format(diff=diff[:20000])

    verdicts = []
    for i in range(max(1, votes)):
        label = f"model {i + 1}" if votes > 1 else "hive"
        try:
            reply, _port = _local_ask(prompt, max_tokens=400, timeout=90)
            if not reply.strip():
                # no local model — fall back to the hub (the fleet)
                code, p = http("POST", "/api/chat",
                               body={"message": prompt, "stream": False},
                               timeout=90, sign=False)
                if code == 200 and isinstance(p, dict):
                    reply = (p.get("reply") or p.get("content")
                             or p.get("text") or "")
        except Exception:
            reply = ""
        reply = (reply or "").strip()
        if not reply:
            print(f"  \033[33m○\033[0m {label}: no answer (no local model, hub unreachable)")
            continue
        verdicts.append((label, reply))
        v = _verdict_from_reply(reply)
        colour = {"SAFE": "\033[32m", "REVIEW": "\033[33m", "RISKY": "\033[31m"}.get(v, "")
        print(f"  \033[1m{label}\033[0m → {colour}{v}\033[0m" if colour
              else f"  \033[1m{label}\033[0m → (no verdict)")
        for line in reply.splitlines():
            if line.strip():
                print(f"      {line.strip()}")
        print()

    if not verdicts:
        print("  \033[33m◐\033[0m no model answered — start one with "
              f"`{APP} llm setup` or check the hub\n")
        return

    tally = {}
    for _label, reply in verdicts:
        v = _verdict_from_reply(reply)
        tally[v] = tally.get(v, 0) + 1
    print(f"  \033[1mtally\033[0m: " +
          "  ".join(f"{k} ×{n}" for k, n in sorted(tally.items())))
    print("  \033[2ma model verdict is a REVIEW, not an approval — read it, "
          "then decide\033[0m\n")


def _verdict_from_reply(reply: str) -> str:
    """Pull SAFE / REVIEW / RISKY out of a model's answer.

    Looked at the LAST line first (that is where the prompt asked for it),
    then the whole reply — models like to add a summary after the verdict,
    and a model that answers in prose still gave an opinion.
    """
    text = (reply or "").strip()
    if not text:
        return "UNKNOWN"
    lines = [l.strip() for l in text.splitlines() if l.strip()]
    for line in reversed(lines):
        up = line.upper()
        for v in ("RISKY", "REVIEW", "SAFE"):
            if v in up and len(up) < 40:
                return v
    up = text.upper()
    for v in ("RISKY", "REVIEW", "SAFE"):
        if v in up:
            return v
    return "UNKNOWN"


def cmd_contributors(args) -> None:
    """Who is helping — the people behind the code, published.

    `hivv contributors`      → the contributor list (from the hub)
    `hivv contributors --github` → read straight from the GitHub API

    The honey leaderboard counts COMPUTE (a bee that serves tokens). This
    counts CODE — a distributed project lives on people feeling their work
    counted, and a code contributor had no number until now.
    """
    raw = bool(getattr(args, "github", False))
    data = None
    if raw:
        code, gh = _gh_get("/contributors?per_page=100")
        if code != 200 or not isinstance(gh, list):
            print(f"  GitHub unreachable ({code}) — try again, or use "
                  f"`{APP} contributors` (the hub caches it)")
            return
        items = [{"login": c.get("login", "?"),
                  "contributions": c.get("contributions", 0),
                  "html_url": c.get("html_url", ""),
                  "avatar_url": c.get("avatar_url")}
                 for c in gh if isinstance(c, dict)]
        total = sum(i["contributions"] for i in items)
        source = f"github.com/{GITHUB_REPO}"
    else:
        code, p = http("GET", "/api/hive/contributors", timeout=20, sign=False)
        if code != 200 or not isinstance(p, dict):
            print(f"  could not fetch contributor stats ({code})")
            print(f"  try: {APP} contributors --github")
            return
        items = p.get("contributors") or []
        total = p.get("total_commits") or sum(i.get("contributions", 0) for i in items)
        source = p.get("repo") or GITHUB_REPO

    print(f"\n\033[1m{APP} contributors\033[0m — {source}\n")
    if not items:
        print("  no contributor data yet")
        print()
        return

    items = sorted(items, key=lambda c: -int(c.get("contributions") or 0))
    top = max((int(c.get("contributions") or 0) for c in items), default=1) or 1
    for c in items[:25]:
        n = int(c.get("contributions") or 0)
        bar = "█" * max(1, round(28 * n / top))
        login = str(c.get("login") or "?")[:20]
        print(f"  {login:<20} \033[36m{bar}\033[0m {n:>5}")
    if len(items) > 25:
        print(f"  \033[2m… and {len(items) - 25} more\033[0m")
    print(f"\n  \033[1m{len(items)}\033[0m contributor(s) · \033[1m{total}\033[0m commit(s)")
    print(f"  \033[2mhttps://github.com/{GITHUB_REPO}\033[0m\n")


def cmd_sync(args) -> None:
    """Two-way check against GitHub: what is here, what is there, what differs.

    `hivv sync`        → report the drift (never changes anything)
    `hivv sync --fetch`→ also fetch origin so the comparison is fresh
    `hivv sync --check`→ exit non-zero when out of sync (for CI)

    Read-only by default. It NEVER merges, never pushes and never resets —
    a sync command that can lose work is a sync command nobody runs.
    """
    fetch = bool(getattr(args, "fetch", False))
    check = bool(getattr(args, "check", False))
    quiet = bool(getattr(args, "quiet", False))

    print(f"\n\033[1m{APP} sync\033[0m — local ⇄ github.com/{GITHUB_REPO}\n")

    # ── the local side ────────────────────────────────────────────────────
    loc = _local_git_state()
    if not loc["is_repo"]:
        print("  \033[33m○\033[0m local: not a git checkout")
        print("    (an installed CLI has no tree — that is normal)")
        print("    the hub serves the GitHub copy, so the CLI you run is")
        print(f"    whatever GitHub says it is. Check it with: {APP} version")
    else:
        dirty = f" \033[33m· {loc['dirty']} uncommitted\033[0m" if loc["dirty"] else ""
        print(f"  local   branch {loc['branch']}  @ {loc['short']}{dirty}")
        if loc["remote"]:
            print(f"          origin {loc['remote']}")
        if loc["ahead"] or loc["behind"]:
            print(f"          vs origin/main: \033[33m{loc['ahead']} ahead\033[0m, "
                  f"\033[33m{loc['behind']} behind\033[0m")
        else:
            print(f"          vs origin/main: \033[32min sync\033[0m")

    # ── the GitHub side ───────────────────────────────────────────────────
    if fetch and loc["is_repo"]:
        if not quiet:
            print("\n  fetching origin …")
        _git("fetch", "--quiet", "origin")

    code, gh = _gh_get("/commits/main")
    if code != 200 or not isinstance(gh, dict) or "sha" not in gh:
        msg = gh.get("message") if isinstance(gh, dict) else gh
        print(f"\n  \033[31m✗\033[0m GitHub unreachable: {msg or 'unknown error'}")
        print("    (offline? the sync check needs the network. "
              "Everything else works offline.)")
        if check:
            sys.exit(2)
        return
    gh_sha = gh["sha"]
    gh_short = gh_sha[:8]
    gh_msg = (gh.get("commit", {}).get("message") or "").splitlines()[0][:70]
    gh_when = (gh.get("commit", {}).get("author", {}) or {}).get("date", "")
    print(f"\n  github  main      @ {gh_short}")
    print(f"          {gh_msg}")
    if gh_when:
        print(f"          {gh_when}")

    # ── the verdict ───────────────────────────────────────────────────────
    same = loc["sha"] == gh_sha
    print()
    if not loc["is_repo"]:
        print("  \033[33m◐\033[0m no local tree to compare — "
              "the hub's copy is the GitHub copy")
        if check:
            sys.exit(0)
        return
    if same and not loc["dirty"]:
        print("  \033[32m✓\033[0m \033[1mIN SYNC\033[0m — local == GitHub, nothing to merge")
        if check:
            sys.exit(0)
        return
    if same and loc["dirty"]:
        print(f"  \033[33m◐\033[0m same commit, but \033[1m{loc['dirty']} uncommitted "
              f"change(s)\033[0m here")
        print("    commit them, or they are lost on the next pull")
        if check:
            sys.exit(1)
        return
    if loc["ahead"]:
        print(f"  \033[33m◐\033[0m local is \033[1m{loc['ahead']} commit(s) AHEAD\033[0m "
              f"of GitHub — push them:")
        print(f"    git push origin {loc['branch']}")
    if loc["behind"]:
        print(f"  \033[33m◐\033[0m local is \033[1m{loc['behind']} commit(s) BEHIND\033[0m "
              f"GitHub — pull them:")
        print(f"    git pull --rebase origin {loc['branch']}")
    if loc["ahead"] and loc["behind"]:
        print("  \033[33m⚠\033[0m diverged both ways — rebase, then resolve:")
        print(f"    git pull --rebase origin {loc['branch']}")
    print("\n  \033[2mnever merge blind: read the diff first (hivv review-diff)\033[0m")
    if check:
        sys.exit(1)


def cmd_health(args) -> None:
    code, p = http("GET", "/api/health")
    print(json.dumps(p, indent=2) if isinstance(p, (dict, list)) else p)
    sys.exit(0 if code == 200 else 2)


