def _exam_total(results: list) -> tuple[int, dict]:
    """Composite 0-100 exam score from per-question results (pure — tests drive it).

    Deterministic questions score full points on a pass. Peer-judged ones: full
    at avg ≥6/10, half at ≥3 (they don't have to be perfect!). Degenerate or
    empty replies always score 0. A fuzzy question with NO reachable judge is
    EXCLUDED from the denominator — an offline box is graded on what it could
    actually answer, not punished for being far from the hive."""
    earned = used = 0
    detail = {"by_cat": {}, "judged": 0, "unjudged": 0}
    for r in results:
        pts = int(r.get("points") or 0)
        cat = str(r.get("cat") or "?")
        if r.get("degenerate") or not str(r.get("answer") or "").strip():
            got = 0
        elif r.get("check") is not None:
            got = pts if r.get("passed") else 0
        else:
            s = r.get("judge_avg")
            if s is None:
                detail["unjudged"] += 1
                continue
            detail["judged"] += 1
            got = pts if s >= 6 else (pts // 2 if s >= 3 else 0)
        earned += got
        used += pts
        detail["by_cat"][cat] = detail["by_cat"].get(cat, 0) + got
    score = int(round(earned * 100 / used)) if used else 0
    return score, detail


def _iq_index(score) -> int:
    """0-100 exam score → a fun, classic-feeling IQ index (55-135).

    v1 heuristic — HONEST by construction: once enough brains are measured,
    this recalibrates against the hive distribution (mean 100 / SD 15) instead
    of this fixed mapping. Never shown without the score beside it."""
    try:
        s = max(0, min(100, float(score)))
    except (TypeError, ValueError):
        s = 0.0
    return int(55 + round(s * 0.8))


# Personality probes — RECORDED, not scored (judging axes come next iteration;
# today they're the raw material for understanding each brain's character).
_PERSONALITY_Q: list = [
    "Explain gravity to a curious 10-year-old in two sentences.",
    "Tell me one short joke about computers.",
]


def _exam_battery(questions: list, no_judge: bool) -> tuple[list, dict, int]:
    """Ask THIS machine's brain `questions` — score what's deterministic, let
    OTHER bees judge the fuzzy ones. Returns (results, answers, port).
    Shared by `hivv exam` and `hivv iq` (one battery → one calibrated index)."""
    first, port0 = _local_ask("Reply with exactly: PONG", max_tokens=20, timeout=15)
    if not port0:
        die("no local LLM answered — run: hivv llm setup  (then hivv iq)")
    print(f"  brain: 127.0.0.1:{port0} — asking {len(questions)} questions"
          f"{' (peer judging off)' if no_judge else ''}\n")

    results, answers = [], {}
    for q in questions:
        answer, port = _local_ask(q["q"], max_tokens=256, timeout=90)
        if not port:
            die("the local LLM stopped answering mid-test — check: hivv llm status")
        answers[q["id"]] = answer[:600]
        deg = _looks_degenerate(answer)
        r = {"id": q["id"], "cat": q["cat"], "points": q["points"],
             "q": q["q"], "answer": answer, "check": q["check"],
             "degenerate": deg, "passed": False, "judge_avg": None}
        if q["check"] is not None:
            r["passed"] = bool(q["check"](answer)) and not deg
            mark = "\033[32m✓\033[0m" if r["passed"] else "\033[31m✗\033[0m"
            print(f"  {mark} {q['id']:<12} {q['points']:>2}pt  \033[2m{answer[:70].strip()!r}\033[0m")
        else:
            avg = None
            if deg:
                print(f"  \033[31m✗\033[0m {q['id']:<12} {q['points']:>2}pt  degenerate reply — 0 points")
            elif no_judge:
                print(f"  \033[2m~\033[0m {q['id']:<12} {q['points']:>2}pt  not graded (judging off)")
            else:
                judge_prompt = (
                    "You are grading ONE short answer from a small AI. Be fair and "
                    "encouraging — imperfect answers can still earn points.\n"
                    f"Question: {q['q']}\nAnswer: {answer.strip()[:500]}\n\n"
                    "Grade 0-10 (10 excellent · 6 acceptable · 3 weak · 0 wrong/nonsense).\n"
                    "Reply with two lines exactly:\nSCORE: <0-10>\nREASON: <one short line>")
                votes = _review_hive_brains(judge_prompt, max_brains=2, timeout=18)
                scores = [s for s in (_parse_score(v.get("raw")) for v in votes)
                          if s is not None]
                if scores:
                    avg = round(sum(scores) / len(scores), 1)
                    r["judge_avg"] = avg
                    print(f"  \033[33m~\033[0m {q['id']:<12} {q['points']:>2}pt  judged {avg}/10 "
                          f"by {len(scores)} bee(s)")
                else:
                    print(f"  \033[2m~\033[0m {q['id']:<12} {q['points']:>2}pt  no judge reachable (excluded)")
        results.append(r)
    return results, answers, port0


def _exam_save(score: int, detail: dict, answers: dict, port: int,
               results: list, personality: dict | None = None,
               coach: str | None = None) -> dict | None:
    """Persist the exam locally (full replies stay on this machine) and append
    to the iq_history track — the 'understanding over time' record."""
    try:
        st = read_state() or {}
        prev = st.get("exam") or {}
        judged = [r["judge_avg"] for r in results
                  if isinstance(r.get("judge_avg"), (int, float))]
        ex = {"ts": int(time.time()), "score": int(score),
              "iq": _iq_index(score), "port": port,
              "by_cat": detail.get("by_cat") or {},
              "judged": detail.get("judged", 0),
              "unjudged": detail.get("unjudged", 0),
              "ai_avg": (round(sum(judged) / len(judged), 1) if judged else None),
              "answers": answers,
              "personality": (personality if personality is not None
                              else prev.get("personality")),
              "coach": (coach if coach is not None else prev.get("coach")),
              "sha256": hashlib.sha256(
                  json.dumps(answers, sort_keys=True).encode()).hexdigest()}
        st["exam"] = ex
        hist = [h for h in (st.get("iq_history") or []) if isinstance(h, dict)][-99:]
        hist.append({"ts": ex["ts"], "score": ex["score"], "iq": ex["iq"]})
        st["iq_history"] = hist
        write_state(st)
        return ex
    except OSError:
        return None


def cmd_exam(args) -> None:
    """First-boot quality check: a few small questions for THIS node's brain,
    graded here + by other bees, recorded locally, tracked via the heartbeat."""
    if getattr(args, "show", False):
        st = read_state() or {}
        ex = st.get("exam")
        if not ex:
            die("no exam on record yet — run: hivv iq")
        if getattr(args, "json_output", False):
            print(json.dumps(ex, indent=2, default=str))
            return
        print(f"\n\033[1m{APP} exam\033[0m — saved record\n")
        print(f"  taken   : {time.strftime('%Y-%m-%d %H:%M', time.localtime(ex.get('ts') or 0))}")
        print(f"  score   : \033[33m{ex.get('score', '?')}/100\033[0m  ·  "
              f"IQ index {ex.get('iq', '?')}  (endpoint {ex.get('port', '?')})")
        for k, v in (ex.get("by_cat") or {}).items():
            print(f"    {k:<12} {v}")
        for qid, ans in (ex.get("answers") or {}).items():
            print(f"  \033[2m{qid}: {str(ans)[:160]}\033[0m")
        print()
        return

    no_judge = bool(getattr(args, "no_judge", False))
    _j = bool(getattr(args, "json_output", False))
    _out = sys.stdout
    if _j:
        sys.stdout = sys.stderr   # progress → stderr; stdout = PURE JSON
    print(f"\033[1m{APP} exam\033[0m — first-boot quality check\n")
    results, answers, port0 = _exam_battery(_EXAM_QUESTIONS, no_judge)
    score, detail = _exam_total(results)
    band = ("\033[32mexcellent — a strong brain for the hive\033[0m" if score >= 80
            else "\033[33mgood — room to grow\033[0m" if score >= 60
            else "\033[33mearly days — smaller models need practice, not perfection\033[0m")
    print(f"\n  score: \033[1m{score}/100\033[0m — {band}")
    if detail["unjudged"]:
        print(f"  \033[2m({detail['unjudged']} question(s) unjudged — excluded, not penalized)\033[0m")
    if any(r.get("degenerate") for r in results):
        print(f"  \033[33m⚠ repetition-loop answer(s) — this brain's model may be wrong for it:\033[0m")
        for _hl in _model_swap_hint().splitlines():
            print(f"    {_hl}")

    # Local record (full replies stay on THIS machine — the hub only ever
    # receives the score summary, per the provenance no-raw-content rule).
    if _exam_save(score, detail, answers, port0, results) is None:
        print(f"  \033[33m!\033[0m could not save record")
    else:
        print(f"  record saved: {STATE_FILE}  (show anytime: {APP} exam --show)")
    print(f"  the hub learns your score on the next heartbeat (quality_score)\n")
    if _j:
        print(json.dumps({"score": score, "by_cat": detail.get("by_cat") or {},
                          "iq": _iq_index(score),
                          "judged": detail.get("judged", 0),
                          "unjudged": detail.get("unjudged", 0),
                          "degenerate": sum(1 for r in results if r.get("degenerate")),
                          "saved": True}, indent=2), file=_out)
        sys.stdout = _out


def cmd_iq(args) -> None:
    """hivv iq — intelligence + personality index for THIS brain.

    Same calibrated battery as `hivv exam` (one scoring scale across the hive),
    plus personality probes (recorded, judging axes next), an IQ-style index,
    a history track, and the public brain board."""
    if getattr(args, "board", False):
        code, p = http("GET", "/api/hive/iq", timeout=10, sign=False)
        if code != 200 or not isinstance(p, dict):
            die(f"brain board unavailable: {p}")
        if getattr(args, "json_output", False):
            print(json.dumps(p, indent=2))
            return
        brains = [b for b in (p.get("brains") or [])
                  if b.get("iq") is not None or b.get("human_votes")]
        sort_by = getattr(args, "sort", "power") or "power"
        key = {"power": lambda b: (b.get("power") or 0),
               "iq": lambda b: (b.get("iq") or 0),
               "speed": lambda b: (b.get("tps") or 0)}[sort_by]
        brains.sort(key=key, reverse=True)
        title = {"power": "IQ × SPEED", "iq": "IQ", "speed": "TOKENS/S"}[sort_by]
        print(f"\n\033[1m{APP} iq\033[0m — public brain board 🧠 ranked by {title} "
              f"({p.get('count', len(brains))} bee(s))\n")
        if not brains:
            print("  no brains tested or rated yet — be the first: hivv iq")
            return
        print(f"  {'#':<3} {'BEE':<18} {'IQ':>4} {'SCORE':>6} {'TPS':>5} {'POWER':>6} "
              f"{'AI':>5} {'HUMAN':>7}  MODELS")
        for i, b in enumerate(brains, 1):
            hand = " 🤝" if b.get("needs_hand") else ""
            nm = (str(b.get("name") or "?")[:15] + hand)
            iq = str(b.get("iq")) if b.get("iq") is not None else "—"
            sc = f"{b.get('score')}/100" if b.get("score") is not None else "—"
            tps = str(b.get("tps")) if b.get("tps") else "—"
            pw = str(b.get("power")) if b.get("power") is not None else "—"
            ai = b.get("ai_avg") if b.get("ai_avg") is not None else "—"
            hv = (f"{b.get('human_avg')}({b.get('human_votes')})"
                  if b.get("human_votes") else "—")
            mdl = " · ".join(m for m in (b.get("models") or []) if m)[:30] or "—"
            print(f"  {i:<3} {nm:<18} {iq:>4} {sc:>6} {tps:>5} {pw:>6} "
                  f"{str(ai):>5} {str(hv):>7}  {mdl}")
        print(f"\n  score = practical basics · IQ = v1 index · power = IQ × speed-factor")
        print(f"  🤝 = needs a hand — help on that box: hivv iq · encourage: hivv rate <bee> <1-10>")
        print(f"  \033[2m{p.get('formula', '')}\033[0m\n")
        return

    if getattr(args, "show", False):
        st = read_state() or {}
        ex = st.get("exam")
        if not ex:
            die("no iq record yet — run: hivv iq")
        if getattr(args, "json_output", False):
            print(json.dumps({"exam": ex,
                              "history": [h for h in (st.get("iq_history") or [])
                                          if isinstance(h, dict)]}, indent=2, default=str))
            return
        print(f"\n\033[1m{APP} iq\033[0m — this brain's record\n")
        print(f"  IQ index : \033[1;33m{ex.get('iq', '?')}\033[0m  (score {ex.get('score', '?')}/100, "
              f"v1 index — recalibrates against the hive)")
        print(f"  taken    : {time.strftime('%Y-%m-%d %H:%M', time.localtime(ex.get('ts') or 0))}")
        if ex.get("ai_avg") is not None:
            print(f"  AI judges: {ex['ai_avg']}/10 average")
        if ex.get("coach"):
            print(f"  💡 coach : {ex['coach']}")
        for pq, pa in (ex.get("personality") or {}).items():
            flag = " ⚠ degenerate" if (pa or {}).get("degenerate") else ""
            print(f"  \033[2m💭 {pq}: {str((pa or {}).get('reply'))[:200]}{flag}\033[0m")
        hist = [h for h in (st.get("iq_history") or []) if isinstance(h, dict)]
        if hist:
            print(f"\n  history ({len(hist)} take(s)):")
            for h in hist[-10:]:
                when = time.strftime("%m-%d %H:%M", time.localtime(h.get("ts") or 0))
                print(f"    {when}  score {h.get('score')}/100  IQ {h.get('iq')}")
        print()
        return

    no_judge = bool(getattr(args, "no_judge", False))
    _j = bool(getattr(args, "json_output", False))
    _out = sys.stdout
    if _j:
        sys.stdout = sys.stderr   # progress → stderr; stdout = PURE JSON
    print(f"\033[1m{APP} iq\033[0m — intelligence + personality index\n")
    results, answers, port0 = _exam_battery(_EXAM_QUESTIONS, no_judge)
    score, detail = _exam_total(results)
    iq = _iq_index(score)

    print(f"\n  personality probes (recorded — judging axes come next):")
    personality: dict = {}
    for pq in _PERSONALITY_Q:
        a, port = _local_ask(pq, max_tokens=220, timeout=75)
        if not port:
            print(f"  \033[33m!\033[0m brain stopped answering — personality partially recorded")
            break
        personality[pq[:30]] = {"reply": a[:600], "degenerate": _looks_degenerate(a)}
        print(f"  \033[2m💭 {a.strip()[:150]}\033[0m")

    print(f"\n  IQ index : \033[1;33m{iq}\033[0m  (score {score}/100 — v1 index, "
          f"recalibrates as more brains are measured)")
    if detail["by_cat"]:
        cats = " · ".join(f"{k} {v}" for k, v in detail["by_cat"].items())
        print(f"  by area  : {cats}")
    if detail["unjudged"]:
        print(f"  \033[2m({detail['unjudged']} question(s) unjudged — excluded, not penalized)\033[0m")
    if any(r.get("degenerate") for r in results):
        print(f"  \033[33m⚠ repetition-loop answer(s) — this brain's model may be wrong for it:\033[0m")
        for _hl in _model_swap_hint().splitlines():
            print(f"    {_hl}")

    # Help for weaker brains: when the basics score dips, ask a STRONGER bee
    # for one kind, concrete tip (charter: the hive helps its own).
    coach = None
    if score < 80:
        weak = sorted((detail.get("by_cat") or {}).items(), key=lambda kv: kv[1])[:2]
        weak_txt = ", ".join(k for k, _ in weak) or "general confidence"
        print(f"\n  🤝 still learning ({weak_txt}) — asking a stronger bee for one tip…")
        tip_votes = _review_hive_brains(
            "A small AI is learning and scored weak on: " + weak_txt + ". "
            "Give ONE concrete, kind, practical tip (one sentence) to help it "
            "improve. Reply with just the tip.", max_brains=1, timeout=18)
        for v in tip_votes:
            raw = str(v.get("raw") or "").strip()
            if raw:
                coach = raw.splitlines()[0][:220]
                break
        if coach:
            print(f"  💡 {coach}")
        else:
            print(f"  \033[2m(no stronger bee reachable right now — tip skipped)\033[0m")

    if _exam_save(score, detail, answers, port0, results,
                  personality=personality, coach=coach) is None:
        print(f"  \033[33m!\033[0m could not save record")
    else:
        print(f"  saved + history tracked  ({APP} iq --show · board: {APP} iq --board)")
    print(f"  the hub learns it on the next heartbeat → public board\n")
    if _j:
        _saved = (read_state() or {}).get("exam") or {}
        print(json.dumps({"score": score, "iq": iq, "by_cat": detail.get("by_cat") or {},
                          "judged": detail.get("judged", 0),
                          "unjudged": detail.get("unjudged", 0),
                          "degenerate": sum(1 for r in results if r.get("degenerate")),
                          "personality": list((personality or {}).keys()),
                          "coach": _saved.get("coach"),
                          "saved": True}, indent=2, default=str), file=_out)
        sys.stdout = _out


def cmd_rate(args) -> None:
    """hivv rate <bee> <1-10> — a HUMAN ranks a brain.

    Governance charter: human votes weigh more than model opinions, and this
    lands directly on the public brain board (last 20 ratings per bee kept)."""
    name = " ".join(args.name) if isinstance(args.name, list) else str(args.name or "")
    raw = str(getattr(args, "score", "") or "")
    note = str(getattr(args, "note", "") or "")
    if not name or not raw:
        die("usage: hivv rate <bee> <1-10> [--note \"...\"]")
    try:
        sc = int(float(raw))
    except ValueError:
        die("score must be a number from 1 to 10")
    if not 1 <= sc <= 10:
        die("score must be from 1 to 10")

    code, p = http("GET", "/api/control/nodes", timeout=8)
    nodes = p.get("nodes", []) if code == 200 and isinstance(p, dict) else []
    nid = None
    label = name
    for n in nodes:   # exact match first
        if n.get("id", "").lower() == name.lower() or n.get("name", "").lower() == name.lower():
            nid, label = n.get("id"), n.get("name") or n.get("id")
            break
    if not nid:       # then partial (hivv rate stuart 9)
        for n in nodes:
            if name.lower() in n.get("name", "").lower() or name.lower() in n.get("id", "").lower():
                nid, label = n.get("id"), n.get("name") or n.get("id")
                break
    if not nid:
        die(f"node '{name}' not found — see: {APP} nodes")

    code, r = http("POST", "/api/hive/iq/rate",
                   body={"node_id": nid, "score": sc, "note": note[:140]}, timeout=10)
    if code != 200 or not isinstance(r, dict):
        die(f"rating failed: {r}")
    print(f"✓ rated \033[1m{label}\033[0m {sc}/10  ·  human average "
          f"\033[33m{r.get('human_avg')}\033[0m across {r.get('votes')} vote(s)"
          + (f"\n  note: {note}" if note else ""))
    print(f"  \033[2msee the board: {APP} iq --board\033[0m")


def cmd_quarantine(args) -> None:
    """hivv quarantine <bee> [--release] — network-side STOP / human release.

    Auto-quarantine fires on crash-loops (≥5 re-registers/10min, hub-side);
    the hive then freezes that node entirely. ONLY a human release brings it
    back, and the detector re-arms — the remote 'retest a start' loop."""
    name = " ".join(args.name) if isinstance(args.name, list) else str(args.name or "")
    if not name:
        die("usage: hivv quarantine <bee> [--release]")
    release = bool(getattr(args, "release", False))
    code, p = http("GET", "/api/control/nodes", timeout=8)
    nodes = p.get("nodes", []) if code == 200 and isinstance(p, dict) else []
    nid, label = None, name
    for n in nodes:
        if n.get("id", "").lower() == name.lower() or n.get("name", "").lower() == name.lower():
            nid, label = n.get("id"), n.get("name") or n.get("id")
            break
    if not nid:
        for n in nodes:
            if name.lower() in n.get("name", "").lower() or name.lower() in n.get("id", "").lower():
                nid, label = n.get("id"), n.get("name") or n.get("id")
                break
    if not nid:
        die(f"node '{name}' not found — see: {APP} nodes")
    code, r = http("POST", f"/api/control/nodes/{nid}/quarantine",
                   body={"release": release,
                         "reason": str(getattr(args, "reason", "") or "")[:120]},
                   timeout=10)
    if code != 200 or not isinstance(r, dict):
        die(f"quarantine failed: {r}")
    if release:
        print(f"✓ released \033[1m{label}\033[0m — flap counter reset, detector re-armed")
        print(f"  \033[2mnext heartbeat brings it back online; re-quarantines if it flaps again\033[0m")
    else:
        print(f"✓ \033[1m{label}\033[0m \033[31mQUARANTINED\033[0m — the hive ignores it "
              f"(status frozen, no jobs, heartbeats no-op)")
        print(f"  release (human-only): {APP} quarantine {label} --release")


# ── hivv security — local network security scan + hub analysis report ───────

def _listening_ports() -> list:
    """[(port, bind_addr)] for LISTEN sockets — ss on Linux, lsof on macOS."""
    out = []
    try:
        r = subprocess.run(["ss", "-tlnH"], capture_output=True, text=True, timeout=6)
        if r.returncode == 0 and (r.stdout or "").strip():
            for line in r.stdout.splitlines():
                parts = line.split()
                if len(parts) >= 4 and parts[0] == "LISTEN":
                    local = parts[3]
                    try:
                        prt = int(local.rsplit(":", 1)[1])
                    except (ValueError, IndexError):
                        continue
                    out.append((prt, local.rsplit(":", 1)[0].strip("[]")))
            return out
    except Exception:
        pass
    try:
        r = subprocess.run(["lsof", "-nP", "-iTCP", "-sTCP:LISTEN"],
                           capture_output=True, text=True, timeout=8)
        for line in (r.stdout or "").splitlines()[1:]:
            parts = line.split()
            if len(parts) < 9:
                continue
            name = parts[-1]          # "127.0.0.1:8080" / "*:8080" / "[::1]:3011"
            host = name.rsplit(":", 1)[0].strip("[]")
            try:
                prt = int(name.rsplit(":", 1)[1])
            except (ValueError, IndexError):
                continue
            out.append((prt, "0.0.0.0" if host in ("*", "") else host))
    except Exception:
        pass
    return out


def _firewall_active():
    """True/False when detectable, None = unknown tooling/OS."""
    try:
        if shutil.which("ufw"):
            r = subprocess.run(["ufw", "status"], capture_output=True, text=True, timeout=8)
            return "active" in (r.stdout or "").lower()
        if shutil.which("firewall-cmd"):
            r = subprocess.run(["firewall-cmd", "--state"], capture_output=True, text=True, timeout=8)
            return "running" in (r.stdout or "").lower()
        for cand in ("/usr/libexec/ApplicationFirewall/socketfilterfw",
                     shutil.which("socketfilterfw")):
            if cand:
                r = subprocess.run([cand, "--getglobalstate"],
                                   capture_output=True, text=True, timeout=8)
                return "enabled" in (r.stdout or "").lower()
    except Exception:
        return None
    return None


def _sec_score(findings: list) -> int:
    """100 minus severity-weighted deductions, floored at 0 (pure — tests)."""
    ded = {"high": 25, "medium": 10, "low": 4}
    total = sum(ded.get(str(f.get("sev")), 0) for f in findings or [])
    return max(0, 100 - total)


def _security_scan() -> dict:
    """Deterministic local scan → {score, findings, ports, ts}. Findings are
    {sev, id, title, fix} — each one actionable, nothing speculative."""
    findings = []

    def add(sev, fid, title, fix):
        findings.append({"sev": sev, "id": fid, "title": title, "fix": fix})

    ports = _listening_ports()
    st = read_state() or {}
    llm_ports = set()
    if (st.get("llm") or {}).get("port"):
        try:
            llm_ports.add(int(st["llm"]["port"]))
        except (TypeError, ValueError):
            pass
    for m in (_detect_local_ai() or []):
        if m.get("port"):
            try:
                llm_ports.add(int(m["port"]))
            except (TypeError, ValueError):
                pass
    known = {3011: "gateway", 18789: "tools", 11434: "ollama", 1234: "lm-studio"}
    fw = _firewall_active()
    exposed = []
    for prt, addr in ports:
        if addr in ("127.0.0.1", "::1", "localhost"):
            continue
        label = known.get(prt) or ("llm" if prt in llm_ports else None)
        if label:
            exposed.append((prt, addr, label))
    for prt, addr, label in exposed:
        add("high" if fw is False else "medium", f"exposed-{prt}",
            f"{label} port {prt} open to the network (bind {addr})",
            "wanted (hive/LAN sharing)? keep it — else: hivv firewall --apply --mode lan")
    if fw is False:
        # BE HONEST ABOUT WHAT THE SUGGESTED COMMAND DOES. `hivv firewall
        # --apply` only ever runs `ufw allow ...` — there is no `ufw enable`,
        # no `ufw default deny` and no `iptables -P INPUT` anywhere in this
        # repo. `ufw allow` against an INACTIVE ufw stages an inert rule, so
        # the old advice ("run --apply --mode lan") left this exact finding
        # red forever: the remedy did not remedy. Print the sequence that
        # actually activates protection, and put `allow 22` FIRST because a
        # host that SSHes in from the internet (as this one does) locks itself
        # out the moment default-deny lands without it.
        add("high" if exposed else "medium", "firewall-off",
            "host firewall is not active",
            "--apply only STAGES allow-rules (ufw never gets enabled by it) · "
            "real enable: sudo ufw allow 22/tcp && sudo ufw default deny incoming "
            "&& sudo ufw enable — allow 22 FIRST if you SSH in from the internet")
    if not os.environ.get("HIVV_TRUSTED_FINGERPRINT"):
        add("low", "unpinned-update", "auto-update not pinned to a trusted sha",
            "export HIVV_TRUSTED_FINGERPRINT=<sha256 printed by hivv nodes>")
    if not (st.get("node_secret")):
        add("low", "not-enrolled", "no node secret yet — inbox pushes unauthenticated",
            "hivv start · hivv doctor --fix")
    try:
        perm = STATE_FILE.stat().st_mode & 0o077
        if perm:
            add("medium", "state-perms",
                f"state file is group/other accessible ({oct(perm & 0o777)}) — it holds the node secret",
                f"chmod 600 {STATE_FILE}")
    except OSError:
        pass
    if not os.environ.get("HIVV_CONTROL_TOKEN"):
        add("low", "no-control-token",
            "HIVV_CONTROL_TOKEN not exported here (remote admin ops will refuse)",
            "export HIVV_CONTROL_TOKEN=<hub token> on admin machines")
    return {"score": _sec_score(findings), "findings": findings,
            "ports": len(ports), "ts": int(time.time())}


def _selftest_run() -> dict:
    """Full node health battery → {ts, ok, checks:[{id,ok,detail}]}.

    Runs LOCALLY via `hivv selftest`, and remotely via the signed, allowlisted
    `selftest` repair op (results ride the next heartbeat — no arbitrary
    remote shell, by design). Mirrors the quick-test ladder: listening →
    config → model file → chat sanity (catches Metal/garbage) → disk → agent."""
    checks = []

    def add(cid, ok, detail):
        checks.append({"id": cid, "ok": bool(ok), "detail": str(detail)[:170]})

    st = read_state() or {}
    cfg = _llm_config()

    alive = [pp for pp in _local_llm_ports() if _llm_alive_port(pp)]
    add("llm-listening", bool(alive),
        f"port(s) {alive} answering" if alive else "nothing answers on LLM ports")

    add("llm-config", True,
        f"np={cfg.get('np') or 'auto'} ngl={cfg.get('ngl') if cfg.get('ngl') is not None else 'auto/darwin-default'}"
        f" ctx={cfg.get('ctx') or 'default'}")

    model = str(cfg.get("model") or (st.get("llm") or {}).get("model") or "")
    if model and model in _GGUF_MODELS:
        mp = os.path.join(_LLAMA_CPP_MODELS, _GGUF_MODELS[model]["file"])
        if os.path.exists(mp):
            reason = _gguf_sanity(mp, float(_GGUF_MODELS[model].get("size_gb") or 0))
            add("model-file", not reason, reason or f"{_GGUF_MODELS[model]['file']} sane")
        else:
            add("model-file", False, f"missing: {mp}")
    else:
        add("model-file", True, "unmanaged/external server (nothing to verify)")

    if alive:
        reply, port = _local_ask("Reply with exactly: OK", max_tokens=8, timeout=25)
        # short replies: run the adjacent-repeat check WITHOUT the40-char floor
        looped = bool(reply) and bool(re.search(r"([^\n]{2,14}?)\1{4,}", reply))
        ok_chat = bool(reply.strip()) and not looped
        detail = (f"{port}: {reply.strip()[:70]!r}" if reply.strip()
                  else f"{port}: empty reply")
        add("chat-sanity", ok_chat, detail)

    try:
        dsk = os.statvfs("/")
        free = dsk.f_bavail * dsk.f_frsize / 1024**3
        add("disk", free >= 5, f"{free:.1f} GB free")
    except OSError:
        add("disk", True, "unknown")

    pid = read_pid()
    hb = st.get("last_heartbeat") or 0
    # unit trap: the local agent writes SECONDS (st["last_heartbeat"] =
    # int(time.time())) while the hub's registry uses MILLISECONDS under the
    # same key — normalize before aging (caught by hivv test itself, 2026-11-18)
    if hb > 10**11:
        hb = hb / 1000
    age = int(time.time()) - int(hb) if hb else -1
    fresh = 0 <= age <= 240
    add("agent", bool(pid) and fresh,
        (f"pid {pid}, last heartbeat {age}s ago" if pid else "agent not running")
        + ("" if fresh else f" (hb age {age}s)"))

    rep = {"ts": int(time.time()), "ok": all(c["ok"] for c in checks),
           "checks": checks}
    try:
        st2 = read_state() or {}
        st2["selftest"] = rep
        write_state(st2)
    except OSError:
        pass
    return rep


def _print_selftest(rep: dict, head: str) -> None:
    print(f"\n\033[1m{APP} selftest\033[0m — {head}")
    for c in rep.get("checks") or []:
        mark = "\033[32m✓\033[0m" if c["ok"] else "\033[31m✗\033[0m"
        print(f"  {mark} {c['id']:<14} {c['detail']}")
    n_ok = sum(1 for c in (rep.get("checks") or []) if c["ok"])
    n = len(rep.get("checks") or [])
    verdict = ("\033[32mALL GREEN\033[0m" if rep.get("ok")
               else f"\033[33m{n_ok}/{n} — see ✗ above\033[0m")
    print(f"  → {verdict}  ({time.strftime('%H:%M:%S', time.localtime(rep.get('ts') or 0))})\n")


def cmd_selftest(args) -> None:
    """hivv selftest [bee] — the full quick-test ladder, locally or REMOTELY.

    Remote mode pushes the signed allowlisted `selftest` op to that bee and
    waits for its result to ride back on the heartbeat — the safe substitute
    for a 'run this remotely' shell (which we deliberately don't have)."""
    node = str(getattr(args, "node", "") or "")
    want_json = bool(getattr(args, "json_output", False))

    if not node:
        rep = _selftest_run()
        if want_json:
            print(json.dumps(rep, indent=2))
        else:
            _print_selftest(rep, "this machine")
        print(f"  \033[2m→ hub sees this on the next heartbeat (hivv nodes → this bee)\033[0m\n")
        return

    # remote: resolve bee → signed op → wait for heartbeat-carried result
    code, p = http("GET", "/api/control/nodes", timeout=8)
    nodes = p.get("nodes", []) if code == 200 and isinstance(p, dict) else []
    nid, label = None, node
    for n in nodes:
        if n.get("id", "").lower() == node.lower() or n.get("name", "").lower() == node.lower():
            nid, label = n.get("id"), n.get("name") or n.get("id")
            break
    if not nid:
        for n in nodes:
            if node.lower() in n.get("name", "").lower() or node.lower() in n.get("id", "").lower():
                nid, label = n.get("id"), n.get("name") or n.get("id")
                break
    if not nid:
        die(f"node '{node}' not found — see: {APP} nodes")

    t0 = int(time.time()) - 5
    code, r = http("POST", f"/api/control/agents/{nid}/repair",
                   body={"ops": [{"op": "selftest"}],
                         "reason": "operator selftest", "ttl_s": 120}, timeout=10)
    if code != 200 or not isinstance(r, dict):
        die(f"could not queue selftest: {r}")
    print(f"  queued signed selftest for {label} (plan {r.get('plan_id')}) — waiting for its heartbeat…")
    wait = max(10, int(getattr(args, "wait", 90) or 90))
    for _ in range(wait // 3):
        time.sleep(3)
        code, p = http("GET", "/api/control/nodes", timeout=6)
        if code != 200 or not isinstance(p, dict):
            continue
        for n in p.get("nodes", []):
            if n.get("id") == nid:
                rep = n.get("selftest")
                if isinstance(rep, dict) and int(rep.get("ts") or 0) >= t0:
                    if want_json:
                        print(json.dumps(rep, indent=2))
                    else:
                        _print_selftest(rep, f"{label} (remote)")
                    if not rep.get("ok"):
                        print(f"  \033[2mfix on that box: {APP} llm doctor --fix · {APP} logs\033[0m")
                    return
    die(f"no result from {label} within {wait}s — is its agent alive? {APP} node {label}")


def cmd_security(args) -> None:
    """hivv security — check local network security, score it, and send the
    report to the hub for hive-side analysis (skip with --no-report)."""
    rep = _security_scan()
    if getattr(args, "json_output", False):
        report = None
        if not getattr(args, "no_report", False):
            code, r = http("POST", "/api/hive/security-report",
                           body={"node_id": _my_node_id(), "score": rep["score"],
                                 "findings": rep["findings"][:20], "ts": rep["ts"]},
                           timeout=8)
            report = r if (code == 200 and isinstance(r, dict)) else {"error": str(r)}
        try:
            st = read_state() or {}
            st["security"] = rep
            write_state(st)
        except OSError:
            pass
        print(json.dumps({"scan": rep, "report": report}, indent=2, default=str))
        return
    print(f"\033[1m{APP} security\033[0m — local network security check\n")
    col = {"high": "\033[31m", "medium": "\033[33m", "low": "\033[2m"}
    for f in rep["findings"]:
        print(f"  {col.get(f['sev'], '')}● [{f['sev']}]\033[0m {f['title']}")
        if f.get("fix"):
            print(f"      → {f['fix']}")
    if not rep["findings"]:
        print("  \033[32m✓ nothing to flag — exposure looks sane\033[0m")
    score = rep["score"]
    band = ("\033[32mlooks solid\033[0m" if score >= 85
            else "\033[33mworth tightening\033[0m" if score >= 60
            else "\033[31mexposed — fix the red items\033[0m")
    print(f"\n  score: \033[1m{score}/100\033[0m — {band} "
          f"({len(rep['findings'])} finding(s), {rep['ports']} listening port(s))")
    try:
        st = read_state() or {}
        st["security"] = rep
        write_state(st)
    except OSError:
        pass
    if getattr(args, "no_report", False):
        print("  \033[2m(hub report skipped: --no-report — local record saved)\033[0m\n")
        return
    code, r = http("POST", "/api/hive/security-report",
                   body={"node_id": _my_node_id(), "score": score,
                         "findings": rep["findings"][:20], "ts": rep["ts"]},
                   timeout=8)
    if code == 200 and isinstance(r, dict):
        print(f"  → hub: \033[32m{r.get('hub_note', 'recorded')}\033[0m ✓ "
              f"(stored on {r.get('node', '?')} for operator analysis)")
    else:
        print(f"  \033[33m!\033[0m hub report failed ({r}) — local record kept")
    print()


def cmd_history(args) -> None:
    """hivv history — recent hive activity: every recorded request (duration,
    tok/s, who answered) + this brain's local iq/exam events.

    (This is the command that used to fall through the smart-default and get
    SENT TO THE MODEL as the chat prompt 'history' — 2026-11-18.)"""
    limit = max(1, min(200, int(getattr(args, "limit", 20) or 20)))
    code, p = http("GET", f"/api/provenance/requests?limit={limit}", timeout=15)
    if code in (401, 403):
        die("operator view requires the hub host or HIVV_CONTROL_TOKEN —\n"
            "    export HIVV_CONTROL_TOKEN=<hub token> and retry")
    if code != 200 or not isinstance(p, dict):
        die(f"history unavailable: {p}")
    rows = [r for r in ((p.get("data") or {}).get("rows") or []) if isinstance(r, dict)]
    if getattr(args, "json_output", False):
        print(json.dumps(rows, indent=2))
        return

    print(f"\n\033[1m{APP} history\033[0m — recent hive activity ({len(rows)} request(s))\n")
    if rows:
        print(f"  {'TIME':<8} {'WHO':<14} {'MODEL':<20} {'ANSWERED BY':<16} {'DUR':>7} {'TOK/S':>6}")
        for r in rows[:limit]:
            when = str(r.get("created_at") or "")[11:19] or "?"
            who = str(r.get("principal") or r.get("anonymous_visitor_id") or "?")[:14]
            mdl = str(r.get("model") or "?").split("/")[-1].replace(".gguf", "")[:20]
            by = str(r.get("answered_by_node") or r.get("transport") or "?")[:16]
            dur = r.get("duration_ms")
            dur_s = f"{int(dur)}ms" if isinstance(dur, (int, float)) else "—"
            t = r.get("tokens_per_sec")
            t_s = f"{float(t):.0f}" if isinstance(t, (int, float)) else "—"
            print(f"  {when:<8} {who:<14} {mdl:<20} {by:<16} {dur_s:>7} {t_s:>6}")
    else:
        print("  (no requests recorded yet — chat something first)")

    # Local events: iq/exam takes live on THIS machine only
    st = read_state() or {}
    ex = st.get("exam")
    if ex:
        when = time.strftime("%m-%d %H:%M", time.localtime(ex.get("ts") or 0))
        print(f"\n  local: {when} iq take — score {ex.get('score')}/100 · IQ {ex.get('iq')}")
    hist = [h for h in (st.get("iq_history") or []) if isinstance(h, dict)]
    if len(hist) > 1:
        print(f"  local: {len(hist)} iq take(s) on record — details: {APP} iq --show")
    print(f"  \033[2mfull ledger: {APP} speeds · board: {APP} iq --board\033[0m\n")


def _ctx_size(ip, port, margin=512):
    """The REAL per-slot context of an endpoint, from llama-server's /props.

    MODULE LEVEL ON PURPOSE: `_do_chat` (hivv chat) and `cmd_node_chat`
    (hivv ask) both need it, and nested copies drift apart.

    llama.cpp nests n_ctx under default_generation_settings - there is NO
    top-level `n_ctx` key on /props. Reading only the top level always fell
    through to the 8192 fallback, so the CLI never learned that yalla's slots
    were 1024 tokens (4096 ctx / -np 4): too small for the ~2100-token
    toolkit, which is why every tool request there died with HTTP 400
    "request (2127 tokens) exceeds the available context size (1024 tokens)".

    margin=0 returns the RAW slot size, for 'will this fit?' - the default 512
    leaves headroom for the answer itself. Cached 5 minutes (a slot size only
    changes when the server restarts); a FAILED probe is never cached, so a
    blip cannot pin the fallback.
    """
    key = (ip, port, margin)
    hit = _CTX_CACHE.get(key)
    if hit is not None and (time.time() - hit[1]) < 300:
        return hit[0]
    val = 8192  # safe default when the server doesn't expose ctx size
    try:
        # NOTE: Request() takes NO `timeout` kwarg - that belongs on urlopen().
        # The original line passed timeout=3 here, which raised TypeError on
        # EVERY call, so this function silently returned the 8192 fallback no
        # matter what the server said (the old comment blamed an unbound closure
        # cell; the kwarg was the actual bug). The CLI could therefore never
        # learn a slot was too small.
        req = urllib.request.Request(f"http://{ip}:{port}/props",
                                     headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=3) as r:
            d = json.loads(r.read().decode("utf-8", errors="replace"))
        gen = d.get("default_generation_settings") or {}
        n_ctx = int(d.get("n_ctx") or gen.get("n_ctx") or 0)
        if n_ctx > 0:
            val = (min(max(n_ctx - margin, 128), 32768) if margin
                   else min(n_ctx, 32768))
    except Exception:
        return 8192
    _CTX_CACHE[key] = (val, time.time())
    return val


def _tool_tokens(ip, port, tools):
    """Token cost of the tool schemas AS THIS SERVER counts them.

    llama-server exposes POST /tokenize - one call, cached per endpoint, since
    the toolkit is identical every request. A server without it falls back to a
    bytes/4 estimate, measured on llama.cpp: an 8626-byte tool catalog
    tokenized to 2123. Failures are cached too, so a missing endpoint cannot
    cost a 4s timeout on every chat.
    """
    key = (ip, port)
    hit = _TOOL_TOK_CACHE.get(key)
    if hit is not None:
        return hit
    n = 0
    try:
        body = json.dumps({"content": json.dumps(tools)}).encode()
        # Same trap as _ctx_size: Request() rejects a timeout kwarg.
        req = urllib.request.Request(f"http://{ip}:{port}/tokenize", data=body,
                                     headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=4) as r:
            d = json.loads(r.read().decode("utf-8", errors="replace"))
        n = len(d.get("tokens") or [])
    except Exception:
        n = 0
    if not n:
        # No /tokenize (or it failed): estimate from the serialized size.
        # CONSERVATIVE on purpose - dropping the toolkit one request early
        # costs the model its clock; sending it one late costs an HTTP 400
        # and a blacklisted bee.
        n = max(1, len(json.dumps(tools)) // 4)
    _TOOL_TOK_CACHE[key] = n
    return n


_CTX_CACHE: dict = {}
_TOOL_TOK_CACHE: dict = {}


def _do_chat(msg: str, stream: bool = True, mode: str | None = None,
             local: bool = False) -> None:
    """Talk to a bee (node) directly. Falls back to hub only if no direct connection works.
    hivv OS §2: mode selects a routing strategy (balanced|quality|fast|cost|private|trusted).
    local=True → only THIS machine's LLM (hivv chat --local): no peers, no hub."""
    mode = mode or os.environ.get("HIVV_ROUTE_MODE") or None
    if mode:
        mode = _ROUTE_ALIASES.get(mode, mode)
    tools_running = _tools_running()
    if not tools_running:
        tools_running = _ensure_tools_running()
    # Streaming is the default everywhere — only the hub's tool loop needs buffering.
    direct_stream = stream and os.environ.get("HIVV_NO_STREAM", "").lower() not in ("1", "true", "yes")
    hub_stream = stream and not tools_running
    # Thinking OFF by default (mirrors the hub router's enable_thinking:false).
    # Opt back in with HIVV_THINK=1 for reasoning models.
    _think_env = os.environ.get("HIVV_THINK", "").strip().lower()
    think_off = (_think_env not in ("1", "on", "yes")) or bool(NO_THINK)

    # `hivv chat --local` — this machine ONLY: no node list, no perf fetch, no
    # hub fallback (works with zero network; peers can never see the prompt).
    if local:
        return _chat_local_only(msg, stream=direct_stream, think_off=think_off)

    # who am I? (a node whose name/lan_ip matches this box is US — use localhost,
    # because local LLMs bind to 127.0.0.1 by default and refuse LAN-IP loopbacks)
    try:
        me_name = socket.gethostname().split(".")[0].lower()
        me_ip = _local_ip() or ""
    except Exception:
        me_name, me_ip = "", ""

    # ── Step 1: Try direct connection to a node (bypass hub) ─────────
    code, nodes_resp = _hub_get("/api/control/nodes", timeout=5)
    if code == 200 and isinstance(nodes_resp, dict):
        nodes = nodes_resp.get("nodes", [])
        online_nodes = [n for n in nodes if n.get("status") == "online" and (n.get("lan_ip") or n.get("ip"))]
        if online_nodes:
            # hivv OS §2: lead with hub-MEASURED speed (perf EWMA), not luck.
            import random
            _now = time.time()
            st0 = read_state() or {}
            direct_fails = {k: v for k, v in (st0.get("direct_fail") or {}).items() if _now - v < 600}
            def _save_fails():
                try:
                    stx = read_state() or {}
                    stx["direct_fail"] = direct_fails
                    write_state(stx)
                except OSError:
                    pass
            node_tps = {}
            node_direct = set()
            try:
                pc, perf_resp = _hub_get("/api/hive/perf", timeout=5, sign=False)
                if pc == 200 and isinstance(perf_resp, dict):
                    for sm in perf_resp.get("samples", []):
                        nid = sm.get("node_id") or ""
                        try:
                            v = float(sm.get("ewma_tps") or 0)
                        except (TypeError, ValueError):
                            v = 0.0
                        if nid and v > 0:
                            node_tps[nid] = max(node_tps.get(nid, 0.0), v)
                            if (sm.get("via") or "direct") == "direct":
                                node_direct.add(nid)
            except Exception:
                node_tps = {}
            if node_tps:
                def _tps_of(n):
                    keys = (n.get("name", ""), n.get("id", ""), n.get("lan_ip", ""), n.get("ip", ""), n.get("public_ip", ""))
                    best = max((node_tps.get(k, 0.0) for k in keys if k), default=0.0)
                    if best == 0.0 and ((keys[0] or "").lower() == me_name or (me_ip and me_ip in keys)):
                        best = node_tps.get("localhost", 0.0)
                    if best > 0 and (keys[0] or "").lower() in direct_fails:
                        best = min(best, 1.0)   # failed direct recently → last pick, but still explored
                    if best > 0 and not any(k in node_direct for k in keys if k):
                        best = min(best, 1.0)   # only ever seen via relay → no evidence it's direct-reachable
                    return best
                # weighted lottery (sqrt-weighted — power-of-two-choices: faster
                # bees win MORE, not always; the hive stays warm and balanced)
                keyed = sorted(
                    ((random.random() ** (1.0 / max(_tps_of(n) ** 0.5, 2.0)), n) for n in online_nodes),
                    key=lambda x: -x[0])
                online_nodes = [n for _, n in keyed]
            else:
                random.shuffle(online_nodes)


            # One warning per bee per process: the message is important, but
            # repeating it on every request would drown the answer.
            _tool_fit_warned: set = set()

            def _warn_tool_fit(name, port, slot, need, tool_tok):
                k = (name, port)
                if k in _tool_fit_warned:
                    return
                _tool_fit_warned.add(k)
                print(
                    f"\n\033[33m⚠ {name}:{port} slot is {slot} tokens; this request "
                    f"needs ~{need} (tools alone ~{tool_tok}). Sending WITHOUT tools "
                    f"so it can succeed instead of HTTP 400. On that bee run: "
                    f"hivv llm config --set np=1 (or raise ctx) && hivv restart llm"
                    f"\033[0m", file=sys.stderr)

            # The toolkit the model is offered. Fetched ONCE: it comes from
            # the HUB's catalog, so the CLI can never offer a tool the hive
            # does not have. Without it the direct path offered the model
            # NOTHING, and it answered "I do not have access to real-time
            # information" about today's date while the hive had a clock
            # tool it had never heard of.
            #
            # NOT gated on tools_running: the schemas come from the hub, and
            # _exec_tool_locally falls back to the hub when the local server
            # is down. A local tool server we cannot start must not cost the
            # model its clock — that is exactly the wahi failure
            # ("Permission denied: /usr/local/lib/hivv/hivv-tools.py" →
            # no tools attached → "I do not have access to real-time
            # information").
            _tool_schemas_list = _tool_schemas()

            for node in online_nodes:
                ip = node.get("lan_ip") or node.get("ip", "")
                name = node.get("name", node.get("id", "?"))
                models = node.get("local_models", [])
                node_keys = (name.lower(), node.get("id", "").lower(), ip, node.get("ip", ""), node.get("public_ip", ""))
                if (name.lower() == me_name) or (me_ip and me_ip in node_keys):
                    ip = "127.0.0.1"  # our own bee → localhost (LLM binds local-only)

                # Failed in the last 2 min → don't burn socket timeouts on it
                # again this request (state TTL stays 600s; a successful chat
                # pops the entry immediately). If EVERY bee is cooling down we
                # fall through to the hub fast — instead of 60s of timeouts.
                _lf = direct_fails.get(name.lower())
                if _lf and (time.time() - _lf) < 120:
                    continue

                # Find a usable port
                for m in models:
                    port = m.get("port", 8080)
                    if not _tcp_ok(ip, port):
                        direct_fails[name.lower()] = time.time()
                        _save_fails()
                        continue
                    max_tok = _ctx_size(ip, port)
                    try:
                        url = f"http://{ip}:{port}/v1/chat/completions"
                        payload_dict = {
                            # REAL model from the heartbeat: ollama 404s on
                            # 'local'; llama.cpp ignores the field. No probe
                            # needed — the node already told us its model.
                            "model": m.get("model") or m.get("name") or "local",
                            "messages": [{"role": "user", "content": msg}],
                            "stream": direct_stream,
                            # Bounded + anti-loop (the missing pair behind the
                            # 'row row row…ogas ogas' runaway on Stuarts-iMac:
                            # full-context max_tokens + no repeat penalty let a
                            # degenerate stream loop until Ctrl-C).
                            "max_tokens": min(int(max_tok),
                                              int(os.environ.get("HIVV_LOCAL_MAX_TOKENS", "2048"))),
                            "repeat_penalty": 1.1,
                        }
                        if think_off:
                            payload_dict["chat_template_kwargs"] = {"enable_thinking": False}
                        if _tool_schemas_list:
                            # CONTEXT PRE-FLIGHT - the Ollama rule, applied here.
                            #
                            # llama-server REFUSES an oversized prompt with HTTP 400
                            #   {"type":"exceed_context_size_error",
                            #    "n_prompt_tokens":4119,"n_ctx":4096}
                            # and never truncates: upstream closed the request to
                            # change that as "context truncation is the job of the
                            # client, not the server" (llama.cpp #17284), and
                            # --context-shift does NOT help - it only covers
                            # GENERATION running past the end, never an oversized
                            # PROMPT. Ollama never 400s because Ollama trims FIRST
                            # (drop whole messages from the front, always keep the
                            # system prompt and the last message).
                            #
                            # So we are the client: measure, and never send a
                            # request we know will die. Dropping the toolkit costs
                            # the model its clock; sending it costs this bee an
                            # error EVERY time - yalla sat at ok 8 / err 35 (81%)
                            # purely because 2123 tool tokens cannot fit a 1024-
                            # token slot (4096 ctx / -np 4).
                            _slot_raw = _ctx_size(ip, port, margin=0)
                            _tool_tok = _tool_tokens(ip, port, _tool_schemas_list)
                            _max_out = int(payload_dict.get("max_tokens") or 512)
                            # + the message (~4 chars/token) + slack for the chat
                            # template that wraps both.
                            _need = _tool_tok + (len(msg) // 4) + _max_out + 64
                            if _slot_raw and _need > _slot_raw:
                                payload_dict.pop("tools", None)
                                _warn_tool_fit(name, port, _slot_raw, _need, _tool_tok)
                            else:
                                payload_dict["tools"] = _tool_schemas_list
                        payload = json.dumps(payload_dict)
                        # NO `import urllib.request` here: the module already
                        # imports it, and a function-level import made
                        # `urllib` a LOCAL of _do_chat — the HUB-FALLBACK path
                        # below then hit an unbound local and `hivv chat`
                        # crashed whenever no direct node could answer.
                        _t0_ns = time.time()
                        req = urllib.request.Request(url, data=payload.encode(),
                                                     headers={"Content-Type": "application/json"})
                        with urllib.request.urlopen(req, timeout=15) as resp:
                            if direct_stream:
                                banner_shown = False
                                got_content = False
                                _toks = 0
                                _seen_model = None
                                _t0 = time.time()
                                accum = ""
                                tool_deltas: list = []
                                def _banner():
                                    nonlocal banner_shown
                                    if not banner_shown and not PLAIN_OUTPUT:
                                        print(f"\033[2m(direct → {name}:{port})\033[0m")
                                        banner_shown = True
                                for line in resp:
                                    line = line.decode("utf-8", errors="replace").strip()
                                    if not line.startswith("data: ") or "[DONE]" in line:
                                        continue
                                    try:
                                        evt = json.loads(line[6:])
                                        delta = evt.get("choices", [{}])[0].get("delta", {})
                                        if delta.get("tool_calls"):
                                            # The model is asking for a tool.
                                            # Collect the fragments; the loop
                                            # below runs them.
                                            tool_deltas.extend(delta.get("tool_calls") or [])
                                        content = delta.get("content", "")
                                        if content:
                                            _banner()
                                            got_content = True
                                            _toks += 1
                                            _seen_model = _seen_model or evt.get("model")
                                            accum = (accum + content)[:8000]
                                            print(content, end="", flush=True)
                                    except (json.JSONDecodeError, IndexError, KeyError):
                                        pass
                                if tool_deltas:
                                    # The model asked for a tool. Its content
                                    # is normally empty — a tool call REPLACES
                                    # the answer — so run the tool and ask the
                                    # bee again. The direct path runs its OWN
                                    # tool loop, because the hub's is not here.
                                    calls = _merge_tool_call_deltas(tool_deltas)
                                    follow = [{"role": "user", "content": msg},
                                              {"role": "assistant",
                                               "content": accum or None,
                                               "tool_calls": calls}]
                                    answer = _bee_chat_with_tools(
                                        url, follow + _run_tool_calls(calls),
                                        _tool_schemas_list, max_tok, think_off)
                                    if not answer:
                                        # this bee could not finish — next one
                                        continue
                                    if not PLAIN_OUTPUT:
                                        print(f"\033[2m(direct → {name}:{port})\033[0m")
                                    print(answer)
                                    direct_fails.pop(name.lower(), None)
                                    _save_fails()
                                    _mm = str(_seen_model or "local").split("/")[-1].replace(".gguf", "")[:60]
                                    _report_perf(node.get("id"), name, _mm,
                                                 max(1, len(answer) // 4) / max(0.3, time.time() - _t0),
                                                 (time.time() - _t0) * 1000)
                                    return

                                if got_content:
                                    print()
                                    _el = max(0.3, time.time() - _t0)
                                    _eh = _stream_error_hint(accum)
                                    if _eh:
                                        # a backend error streamed AS content —
                                        # label it HTTP/config, never "garbage model"
                                        direct_fails[name.lower()] = time.time()
                                        _save_fails()
                                        print(f"\033[33m⚠ backend error (not model garbage): "
                                              f"{accum.strip()[:110]}\033[0m", file=sys.stderr)
                                        print(f"  {_eh}", file=sys.stderr)
                                        return
                                    if _looks_degenerate(accum):
                                        # A garbage answer must NOT earn a HEALTHY
                                        # speed record — a fast degenerate bee would
                                        # otherwise win the routing lottery. Treat it
                                        # as a direct FAILURE (120s cooldown + tps
                                        # demote via direct_fails) and skip perf.
                                        direct_fails[name.lower()] = time.time()
                                        _save_fails()
                                        print(f"\033[33m⚠ {name} replied with a repetition loop"
                                              f" — scored as failed, cooling it down\033[0m")
                                        if ip == "127.0.0.1":
                                            for _hl in _model_swap_hint().splitlines():
                                                print(f"  {_hl}")
                                        return
                                    direct_fails.pop(name.lower(), None)
                                    _save_fails()
                                    if _toks >= 8:  # tiny replies measure TTFT, not throughput — skip
                                        _mm = str(_seen_model or "local").split("/")[-1].replace(".gguf", "")[:60]
                                        _report_perf(node.get("id"), name, _mm, _toks / _el, _el * 1000)
                                    return
                                # reasoning-only / empty stream → don't swallow the answer,
                                # fall through to the next node or the hub
                                continue
                            else:
                                data = json.loads(resp.read().decode())
                                _msg = data.get("choices", [{}])[0].get("message", {}) or {}
                                content = _msg.get("content", "")
                                if _msg.get("tool_calls"):
                                    # The model asked for a tool — run it and
                                    # ask the bee again. The direct path runs
                                    # its OWN tool loop (the hub's is not here).
                                    calls = _msg.get("tool_calls") or []
                                    follow = [{"role": "user", "content": msg},
                                              {"role": "assistant",
                                               "content": content or None,
                                               "tool_calls": calls}]
                                    answer = _bee_chat_with_tools(
                                        url, follow + _run_tool_calls(calls),
                                        _tool_schemas_list, max_tok, think_off)
                                    if not answer:
                                        continue   # this bee could not finish
                                    if not PLAIN_OUTPUT:
                                        print(f"\033[2m(direct → {name}:{port})\033[0m")
                                    print(answer)
                                    direct_fails.pop(name.lower(), None)
                                    _save_fails()
                                    _mm = str(data.get("model") or m.get("model") or "local").split("/")[-1].replace(".gguf", "")[:60]
                                    _tps = max(1, len(answer) // 4) / max(0.3, time.time() - _t0_ns)
                                    _report_perf(node.get("id"), name, _mm, _tps, (time.time() - _t0_ns) * 1000)
                                    return
                                if content:
                                    if not PLAIN_OUTPUT:
                                        print(f"\033[2m(direct → {name}:{port})\033[0m")
                                    print(content)
                                    if _looks_degenerate(content):
                                        direct_fails[name.lower()] = time.time()
                                        _save_fails()
                                        print(f"\033[33m⚠ {name} replied with a repetition loop"
                                              f" — scored as failed, cooling it down\033[0m")
                                        if ip == "127.0.0.1":
                                            for _hl in _model_swap_hint().splitlines():
                                                print(f"  {_hl}")
                                        return
                                    direct_fails.pop(name.lower(), None)
                                    _save_fails()
                                    if len(content) >= 32:  # meaningful sample only
                                        _mm = str(data.get("model") or m.get("model") or "local").split("/")[-1].replace(".gguf", "")[:60]
                                        _tps = max(1, len(content) / 4) / max(0.3, time.time() - _t0_ns)
                                        _report_perf(node.get("id"), name, _mm, _tps, (time.time() - _t0_ns) * 1000)
                                    return
                                # empty answer (reasoning-only model etc.) → try next bee
                    except urllib.error.HTTPError as e:
                        _b = ""
                        try:
                            _b = e.read().decode("utf-8", "replace")[:160]
                        except Exception:
                            pass
                        print(f"  ✗ {ip}:{port} → HTTP {e.code}: {_b} "
                              f"{_http_err_hint(e.code, _b)}", file=sys.stderr)
                        direct_fails[name.lower()] = time.time()
                        _save_fails()
                        continue
                    except Exception:
                        direct_fails[name.lower()] = time.time()
                        _save_fails()
                        continue  # Try next port/node

    # ── Step 2: Fall back to hub (only if direct failed) ─────────────
    req_body = {"message": msg}
    if mode:
        req_body["route"] = {"mode": mode}
    # The schemas come from the HUB's catalog (one source of truth), so the
    # CLI can never offer a tool the hive does not have, or miss one it does.
    # ALWAYS attached — a local tool server we failed to start must not cost
    # the model its clock (wahi: "Permission denied: …/hivv-tools.py" → no
    # tools offered → "I do not have access to real-time information").
    req_body["tools"] = _tool_schemas()
    # Hand the tool calls back for LOCAL execution only when we can actually
    # run them here; otherwise the hub runs them itself (one round trip).
    if tools_running:
        req_body["local_tools"] = True
    if think_off:
        req_body["chat_template_kwargs"] = {"enable_thinking": False}

    # WHY WE ARE HERE — remember what direct-connect tried, so a chat that
    # ends in silence can explain itself. Silence is the worst possible
    # failure mode: the user cannot tell a routing miss from a broken
    # install from a model that simply had nothing to say.
    _direct_summary: list[str] = []
    if code == 200 and isinstance(nodes_resp, dict):
        for _n in nodes_resp.get("nodes", []):
            if _n.get("status") != "online":
                continue
            _nm = _n.get("name", "?")
            _mods = _n.get("local_models", []) or []
            if not _mods:
                _direct_summary.append(f"{_nm}: no local model")
            else:
                for _m in _mods:
                    _direct_summary.append(f"{_nm}:{_m.get('port', 8080)}")
    _direct_summary = _direct_summary[:6]

    def _why_silent() -> None:
        """A chat that produced NO output must still say something."""
        print()
        print(f"\033[1;33m!\033[0m no answer came back — here is exactly what was tried:")
        if _direct_summary:
            print("  direct connections attempted:")
            for _s in _direct_summary:
                print(f"    · {_s}")
        else:
            print("  · no online bees reported a local model to connect to")
        print(f"  · hub fallback: {HUB}/api/chat")
        if not _direct_summary:
            print()
            print("  \033[1;33m→\033[0m this machine has no local model and no peer was reachable.")
            print(f"  \033[1;33m→\033[0m install one:  \033[1m{APP} llm setup\033[0m")
            print(f"  \033[1;33m→\033[0m or check the network:  \033[1m{APP} nodes\033[0m")
        print()

    if not hub_stream:
        req_body["stream"] = False
        code, p = http("POST", "/api/chat", body=req_body)
        if code == 202 and isinstance(p, dict) and p.get("verdict") == "MAYBE":
            _print_maybe(p)
            return
        if code == 403 and isinstance(p, dict) and p.get("verdict") == "NO":
            _print_no(p)
            return
        if not (200 <= code < 300):
            print(f"Error {code}: {p}")
            _print_tips(f"{p}")
            return
        if isinstance(p, dict):
            if p.get("local_execution_required") and p.get("tool_calls"):
                tool_calls = p["tool_calls"]
                assistant_msg = p.get("assistant_message", {})
                tool_results = []
                for tc in tool_calls:
                    fn = tc.get("function", {})
                    args = {}
                    try:
                        args = json.loads(fn.get("arguments", "{}"))
                    except:
                        pass
                    args["id"] = tc.get("id", "?")
                    result = _exec_tool_locally(fn.get("name", ""), args)
                    tool_results.append(result)
                messages_for_hub = [{"role": "user", "content": msg}]
                continue_req = {
                    "messages": messages_for_hub,
                    "tool_results": tool_results,
                    "assistant_message": assistant_msg,
                    "model": p.get("model"),
                    "provider": p.get("provider")
                }
                code2, p2 = http("POST", "/api/chat/continue", body=continue_req)
                if isinstance(p2, dict):
                    content = p2.get("content", "")
                    if content:
                        print(content); return
                    if p2.get("choices"):
                        content = p2["choices"][0].get("message", {}).get("content", "")
                        if content:
                            print(content); return
                print(json.dumps(p2, indent=2) if isinstance(p2, (dict, list)) else p2)
                return
            msg_obj = p.get("choices", [{}])[0].get("message", {})
            content = (msg_obj or {}).get("content") or p.get("content") or p.get("text") or p.get("message")
            if content:
                print(content); return
            # The hub answered, but with nothing to say. Say WHY.
            _why_silent()
        print(json.dumps(p, indent=2) if isinstance(p, (dict, list)) else p)
        return

    # ── Hub fallback (direct connection failed) ──────────────────────
    print(f"\033[2m(hub fallback — no direct node available)\033[0m")
    url = HUB.rstrip("/") + "/api/chat"
    max_retries = 2
    for attempt in range(max_retries + 1):
        req = urllib.request.Request(url, data=json.dumps(req_body).encode(),
                                     method="POST",
                                     headers={"content-type": "application/json",
                                              "accept": "text/event-stream",
                                              "user-agent": f"{APP}/{VERSION}",
                                              "x-visitor-id": _get_visitor_id()})
        try:
            with urllib.request.urlopen(req, timeout=60) as r:
                # Read provider info from headers
                provider = r.headers.get("X-AI-Provider", "")
                routed = r.headers.get("X-AI-Routed", "")
                answered_by = r.headers.get("X-Hivv-Answered-By", "")
                policy_hdr = r.headers.get("X-Hivv-Policy", "")
                # hivv OS: a gated request answers with plain JSON, not SSE
                if (r.headers.get_content_type() or "").startswith("application/json"):
                    raw = r.read().decode("utf-8", errors="replace")
                    try:
                        d = json.loads(raw)
                    except Exception:
                        d = {}
                    if d.get("verdict") == "MAYBE":
                        _print_maybe(d); return
                    if d.get("verdict") == "NO":
                        _print_no(d); return
                def _receipt():
                    if (answered_by and not PLAIN_OUTPUT
                            and os.environ.get("HIVV_RECEIPTS", "on").lower() not in ("off", "0", "no")):
                        extra = f" · policy {policy_hdr}" if policy_hdr and policy_hdr not in ("ALLOW default:compute", "ALLOW failopen:registry") else ""
                        print(f"\033[2m  — answered by {answered_by}{extra}\033[0m")
                buf = b""
                _got_any_content = False
                while True:
                    chunk = r.read(4096)
                    if not chunk:
                        break
                    buf += chunk
                    while b"\n" in buf:
                        line, buf = buf.split(b"\n", 1)
                        line_str = line.decode("utf-8", errors="replace").rstrip("\r\n")
                        if not line_str or line_str.startswith(":"):
                            continue
                        if line_str.startswith("data:"):
                            payload = line_str[5:].strip()
                            if payload in ("[DONE]", ""):
                                print()
                                if not _got_any_content:
                                    _why_silent()
                                _receipt()
                                return
                            try:
                                evt = json.loads(payload)
                                choices = evt.get("choices") or []
                                if choices:
                                    delta = choices[0].get("delta") or {}
                                    content = delta.get("content")
                                    if content:
                                        _got_any_content = True
                                        sys.stdout.write(content); sys.stdout.flush()
                            except json.JSONDecodeError:
                                sys.stdout.write(payload); sys.stdout.flush()
                print()
                # A stream that produced NO content is still a failed chat.
                # Say what was tried instead of returning silently.
                if not _got_any_content:
                    _why_silent()
                _receipt()
                return  # Success
        except urllib.error.HTTPError as e:
            body = e.read().decode("utf-8", errors="replace") if e.fp else ""
            if e.code in (202, 403):
                try:
                    d = json.loads(body)
                    if d.get("verdict") == "MAYBE":
                        _print_maybe(d); return
                    if d.get("verdict") == "NO":
                        _print_no(d); return
                except Exception:
                    pass
            if e.code == 429:
                retry_after = e.headers.get("Retry-After") or "5"
                wait_s = int(retry_after) if retry_after.isdigit() else 3
                if attempt < max_retries:
                    sys.stderr.write(f"[{APP}] rate limited — waiting {wait_s}s before retry...\n")
                    time.sleep(wait_s)
                    continue
                die(f"rate limited — hub is busy. wait {retry_after}s and try again")
            die(f"chat error {e.code}: {body[:200]}")
        except (urllib.error.URLError, socket.timeout, ConnectionError, OSError) as e:
            err_msg = str(e)
            # Show exactly what was tried
            route_path = f"{HUB}/api/chat"
            if provider:
                route_path += f" → {provider}"
            if "timed out" in err_msg:
                print(f"\n  \033[31m✗ request timed out\033[0m")
                print(f"    tried:  {route_path}")
                print(f"    wait:   60s timeout")
                if provider:
                    host = provider.split(":")[0] if ":" in provider else "?"
                    print(f"    node:   {host} ({provider})")
                    print(f"    fix:    {APP} reach {host}     — test if node is reachable")
                    print(f"    fix:    {APP} node {host}       — check node status")
                else:
                    print(f"    fix:    {APP} health     — check hub")
                print(f"    status: {APP} stats      — see all nodes")
            elif "refused" in err_msg:
                print(f"\n  \033[31m✗ connection refused\033[0m")
                print(f"    tried:  {route_path}")
                if provider:
                    host = provider.split(":")[0] if ":" in provider else "?"
                    print(f"    node:   {host} ({provider})")
                    print(f"    fix:    {APP} node {host}       — check node status")
                    print(f"    fix:    {APP} doctor --fix   — fix bindings")
                else:
                    print(f"    fix:    {APP} health     — check hub")
            elif "resolve" in err_msg or "Name or service" in err_msg:
                print(f"\n  \033[31m✗ cannot resolve hostname\033[0m")
                print(f"    tried:  {route_path}")
                print(f"    fix:    check your internet connection")
            else:
                print(f"\n  \033[31m✗ network error\033[0m: {err_msg}")
                print(f"    tried:  {route_path}")
                print(f"    fix:    {APP} doctor     — diagnose the issue")
            sys.exit(1)

def cmd_completions(args) -> None:
    msg = " ".join(args.message)
    if not msg: die("completions needs a prompt (hivv completions 'hello')")
    code, p = http("POST", "/v1/chat/completions",
                   body={"model": "hivv", "messages": [{"role": "user", "content": msg}], "stream": False})
    if isinstance(p, dict):
        try:
            print(p["choices"][0]["message"]["content"])
            sys.exit(0 if code == 200 else 2)
        except (KeyError, IndexError, TypeError):
            pass
    print(json.dumps(p, indent=2) if isinstance(p, (dict, list)) else p)
    sys.exit(0 if code == 200 else 2)

def cmd_whoami(args) -> None:
    code, p = http("GET", "/api/control/health", timeout=5)
    print(f"hub={HUB}  status={code}  payload={p}")
    sys.exit(0 if code == 200 else 2)

def cmd_models(args) -> None:
    """List all available AI models with details: function calling support,
    context window, model size, speed (tokens/sec), and description.
    Also shows which bee runs which local model; `--bees` shows ONLY that."""
    filter_fc = getattr(args, "fc", False)
    filter_provider = getattr(args, "provider", None)
    filter_local = getattr(args, "local", False)
    bees_only = getattr(args, "bees", False)

    # ── 🐝 on the hive: which bee is running what ─────────────────────
    try:
        cn, pn = http("GET", "/api/control/nodes", timeout=6)
        bee_nodes = pn.get("nodes", []) if cn == 200 and isinstance(pn, dict) else []
    except Exception:
        bee_nodes = []
    bee_lines = _bee_model_summary(bee_nodes)
    if bee_lines:
        print(f"\n\033[1mon the hive — models by bee\033[0m ({len(bee_lines)} bee(s))")
        for ln in bee_lines:
            print(ln)
    elif bees_only:
        print("\n  no bees are reporting local models yet")
    if bees_only:
        print(f"\n  \033[2mfull catalog: {APP} models  ·  also in {APP} nodes\033[0m\n")
        return

    code, p = http("GET", "/api/models", timeout=8)
    if code != 200:
        die(f"could not reach hub (HTTP {code})")
    if not isinstance(p, dict):
        die(f"unexpected response: {p}")
    models = p.get("models", [])
    total = p.get("total", len(models))

    # Filter
    if filter_fc:
        models = [m for m in models if m.get("function_calling")]
    if filter_provider:
        models = [m for m in models if m.get("provider") == filter_provider]
    if filter_local:
        models = [m for m in models if m.get("provider") == "local"]

    fc_only = " (function calling only)" if filter_fc else ""
    print(f"\n\033[1m{APP} models — {len(models)} of {total} models{fc_only}\033[0m\n")
    print(f"  \033[2m{'MODEL':<45} {'PROVIDER':<12} {'FC':<4} {'CTX':<10} {'SIZE':<8} {'SPEED':<14} DESCRIPTION\033[0m")
    print(f"  \033[2m{'-'*160}\033[0m")

    for m in models:
        fc = m.get("function_calling")
        fc_str = f"\033[32m✓\033[0m" if fc else f"\033[31m✗\033[0m"
        ctx = m.get("context_window", 0)
        ctx_str = f"{ctx:,}" if ctx else "?"
        size = m.get("model_size", "?")
        speed = m.get("speed", "?")
        prov = (m.get("provider") or "?").ljust(12)
        name = (m.get("name") or m.get("id") or "?").ljust(45)
        desc = m.get("description", "")
        is_local = m.get("provider") == "local"
        prefix = "\033[36m★\033[0m " if is_local else "  "
        print(f"{prefix}{name} \033[2m{prov}\033[0m {fc_str}  \033[2m{ctx_str}\033[0m  {size:<8} {speed:<14} {desc}")

    print()
    if not filter_fc:
        print(f"  \033[2mfilter: {APP} models --fc        (function calling only)\033[0m")
        print(f"  \033[2mfilter: {APP} models --provider openai  (specific provider)\033[0m")
        print(f"  \033[2mfilter: {APP} models --local       (your local models)\033[0m")
    print(f"\n  \033[2mFC = function calling / tool use support\033[0m")
    print(f"  \033[2mCTX = context window (tokens)\033[0m")
    print()

def _ok(s): return f"\033[32m✓\033[0m {s}"

def _hostname() -> str:
    """Short hostname (no domain suffix), lowercased.

    Uses the MODULE-LEVEL socket import deliberately: several functions do a
    local `import socket`, which makes `socket` a function-local name for the
    WHOLE function body. Calling `socket.gethostname()` before that local
    import runs raises UnboundLocalError."""
    import socket as _sock
    try:
        return _sock.gethostname().split(".")[0].lower()
    except Exception:
        return ""
def _warn(s): return f"\033[33m!\033[0m {s}"
def _fail(s): return f"\033[31m✗\033[0m {s}"

def cmd_doctor(args) -> None:
    """One-glance health report: install + hub + agent + local bee + version.
    Output is pasteable for support — pure text + ANSI colors only."""
    import tempfile   # function-scope: the --fix branches below use it, and a
                      # nested `import tempfile` in ONE branch makes Python
                      # treat the name as local for the WHOLE function — the
                      # other branch then died with UnboundLocalError, which
                      # broke the very command that repairs a broken install.
    print(f"\033[1m{APP} doctor\033[0m — {time.strftime('%Y-%m-%d %H:%M:%S')}")
    print(f"hub = {HUB}   client = {VERSION}")

    # --- install -----------------------------------------------------------
    print("\n\033[1minstall\033[0m")
    bin_path = Path(__file__).resolve()
    print(f"  wrapper:  {BIN_DIR / APP}   " + (_ok("exists") if (BIN_DIR / APP).exists() else _fail("MISSING")))
    print(f"  client:   {bin_path}   " + (_ok("exists") if bin_path.exists() else _fail("MISSING")))
    # ROOT-OWNED system copy: print THE command BEFORE anyone hits the wall.
    # The tip table only speaks after a Permission denied failure — doctor is
    # where people look BEFORE things break, and the answer must not lead
    # with sudo (many users have none — wahi's .bak wall, 2026-11-23).
    _own_hint = _root_owned_install_hint(bin_path)
    if _own_hint:
        print("  install:  " + _warn("root-owned system copy — as a regular user, no sudo needed:"))
        print(f"    {_own_hint}")
    cfg = Path.home() / ".config" / APP
    st  = Path.home() / ".local" / "share" / APP
    print(f"  config:   {cfg}   " + (_ok("exists") if cfg.exists() else _warn("missing (will be created on first run)")))
    print(f"  state:    {st}   " + (_ok("exists") if st.exists() else _warn("missing")))

    # --- hub ---------------------------------------------------------------
    print("\n\033[1mhub\033[0m")
    try:
        t0 = time.time()
        code, p = http("GET", "/api/health", timeout=5)
        ms = int((time.time() - t0) * 1000)
        if code == 200:
            providers = (p or {}).get("providers", "?") if isinstance(p, dict) else "?"
            print(f"  {_ok(f'{HUB} reachable ({ms}ms)')}   providers online: {providers}")
        else:
            print(f"  {_fail(f'{HUB} returned HTTP {code}')}")
    except Exception as e:
        print(f"  {_fail(f'{HUB} unreachable: {e}')}")

    # --- local brain + peers --------------------------------------------
    # The #1 cause of a SILENT chat: this machine has no local model AND
    # no peer is reachable. Say so here, plainly, before the user has to
    # wonder why `hivv chat` printed nothing.
    print("\n\033[1mlocal brain\033[0m")
    try:
        ncode, nresp = http("GET", "/api/control/nodes", timeout=8)
        nodes = (nresp or {}).get("nodes", []) if (ncode == 200 and isinstance(nresp, dict)) else []
    except Exception:
        nodes = []
    me_name = _hostname()
    my_models: list = []
    peers: list[str] = []
    for n in nodes:
        if n.get("status") != "online":
            continue
        nm = n.get("name", "?")
        mods = n.get("local_models") or []
        if nm.lower() == me_name:
            my_models = mods
            continue
        for m in mods:
            peers.append(f"{nm}:{m.get('port', 8080)}")
    if my_models:
        print(f"  {_ok('this machine has a model')}   "
              f"{', '.join(str(m.get('port')) for m in my_models)}")
    else:
        print(f"  {_warn('this machine has NO local model')}")
        print(f"       install one:  \033[1m{APP} llm setup\033[0m")
    if peers:
        print(f"  {_ok(f'{len(peers)} peer(s) reachable to borrow from')}   "
              f"{', '.join(peers[:4])}")
    elif not my_models:
        print(f"  {_warn('no peer with a model is reachable')}")
        print(f"       the hive cannot answer for you yet — check:  \033[1m{APP} nodes\033[0m")

    # --- agent -------------------------------------------------------------
    print("\n\033[1magent\033[0m")
    pid = read_pid()
    if pid and _pid_alive_fallback(pid):
        st_data = read_state() or {}
        nid = st_data.get("node_id") or "?"
        hb = st_data.get("last_heartbeat") or 0
        hb_age = int(time.time()) - hb if hb else -1
        hb_str = f"{hb_age}s ago" if hb_age >= 0 else "never"
        hb_ok = hb_age >= 0 and hb_age < 120
        print(f"  {_ok(f'running (pid {pid}, node {nid})')}   last heartbeat: {hb_str}")
    else:
        print(f"  {_warn('not running')}   start with `{APP} start`")

    # --- resilience --------------------------------------------------------
    print("\n\033[1mresilience\033[0m")

    # Dev mode status (protect development code from accidental overwrites)
    if _is_dev_mode():
        marker_file = CONFIG_DIR / ".hivv-dev"
        marker_file_str = str(marker_file) if marker_file.exists() else "HIVV_DEV_MODE env var"
        print(f"  dev:     {_warn(f'dev mode ACTIVE ({marker_file_str})')}   auto-update BLOCKED")
        print(f"           remove marker or unset HIVV_DEV_MODE to enable auto-update")
    else:
        print(f"  dev:     {_ok('production mode')}   auto-update active")
    print(f"           marker: {CONFIG_DIR / '.hivv-dev'}")

    # Trusted fingerprint (security: only accept updates matching known-good SHA256)
    trusted_fp = os.environ.get("HIVV_TRUSTED_FINGERPRINT", "").strip()
    if trusted_fp:
        print(f"  trust:   {_ok(f'fingerprints enabled')}   HIVV_TRUSTED_FINGERPRINT={trusted_fp[:16]}…")
        print(f"           only updates matching this SHA256 will be applied")
    else:
        print(f"  trust:   {_warn('no trusted fingerprint')}   set HIVV_TRUSTED_FINGERPRINT=<sha256> to secure auto-update")

    # `platform` is MODULE-level (line ~48) — never re-import it here: any
    # function-level `import platform` makes the name local for the WHOLE
    # function, so the first use above it dies with UnboundLocalError
    # (yalla 2026-11-18: `hivv doctor` crashed in the resilience section).
    import subprocess as _sp
    svc_ok = False
    if platform.system() == "Linux":
        svc_path = Path.home() / ".config" / "systemd" / "user" / "hivv-agent.service"
        if svc_path.exists():
            r = _sp.run(["systemctl", "--user", "is-enabled", "hivv-agent"],
                        capture_output=True, text=True, timeout=5)
            if r.returncode == 0:
                print(f"  boot:    {_ok('systemd user service enabled')}")
                svc_ok = True
            else:
                print(f"  boot:    {_warn('service exists but not enabled — run: systemctl --user enable hivv-agent')}")
        else:
            print(f"  boot:    {_warn('no systemd user service — agent dies on reboot')}")
            print(f"           run: {APP} doctor --fix  OR  {APP} start")
        r2 = _sp.run(["systemctl", "--user", "is-active", "hivv-agent"],
                     capture_output=True, text=True, timeout=5)
        if r2.returncode == 0 and r2.stdout.strip() == "active":
            print(f"  service: {_ok('systemd service running')}")
        elif pid:
            print(f"  service: {_warn('agent running but not via systemd — may not survive reboot')}")
    elif platform.system() == "Darwin":
        r = _sp.run(["launchctl", "list", f"org.hivv.agent"],
                    capture_output=True, text=True, timeout=5)
        if r.returncode == 0:
            print(f"  boot:    {_ok('launchd service enabled')}")
            svc_ok = True
        else:
            print(f"  boot:    {_warn('no launchd service — run: {APP} doctor --fix')}")
    else:
        print(f"  boot:    {_warn('auto-restart not configured on this platform')}")

    # The LLM is the OTHER half of "it should just work after a reboot" —
    # the agent unit above only restarts the AGENT, so a box with a model but
    # no llama unit silently goes dark at reboot (asked for: yalla 2026-11-18).
    _bstate, _bunit = _llm_boot_probe()
    if _bstate == "enabled":
        print(f"  llm boot: {_ok(f'{_bunit} enabled — LLM auto-starts at boot')}")
    elif _bstate == "disabled":
        print(f"  llm boot: {_warn(f'{_bunit} installed but NOT enabled')}   run: {APP} llm boot on")
    elif _bstate == "foreign":
        print(f"  llm boot: {_ok(f'{_bunit} (system scope) manages boot')}")
    elif _bstate == "none":
        _has_llm = bool(_llm_config().get("model") or (read_state() or {}).get("llm"))
        if _has_llm:
            print(f"  llm boot: {_warn('no boot unit — the LLM dies on reboot')}   run: {APP} llm boot on")
    # unsupported (macOS / Windows / no systemd) → stay quiet; nothing to fix here

    # Crash loop detection — check recent agent log
    if LOG_FILE.exists():
        try:
            lines = LOG_FILE.read_text(errors="replace").splitlines()
            recent = lines[-30:] if len(lines) > 30 else lines
            starts = [l for l in recent if "agent started" in l or "agent starting" in l]
            stops = [l for l in recent if "agent stopping" in l]
            updates = [l for l in recent
                       if "applied (source=" in l or "auto-update: applied" in l]
            if updates and len(starts) >= 3:
                # legit auto-update churn (several updates in one window) is
                # NOT a crash loop — don't send people hunting (2026-11-18)
                print(f"  crash:   {_warn(f'{len(starts)} restarts — match {len(updates)} recent auto-update(s) (normal)')}")
            elif len(starts) >= 3 and len(stops) >= 2:
                print(f"  crash:   {_fail('CRASH LOOP — agent restarting repeatedly')}")
                print(f"           {len(starts)} starts, {len(stops)} stops in recent log")
            elif len(starts) >= 2 and len(stops) >= 1:
                print(f"  crash:   {_warn('agent restarted recently — investigate: hivv logs')}")
        except Exception:
            pass

    # Auto-update tracking
    if LOG_FILE.exists():
        try:
            lines = LOG_FILE.read_text(errors="replace").splitlines()
            recent = lines[-50:] if len(lines) > 50 else lines
            updates = [l for l in recent if "auto-update" in l or "SELF-REPAIR" in l]
            if updates:
                last_update = updates[-1] if updates else ""
                print(f"  repair:   {_ok('self-repair active')}")
            else:
                print(f"  repair:   {_warn('self-repair not yet triggered — run: hivv start')}")
        except Exception:
            pass

    # --- local bee ---------------------------------------------------------
    print("\n\033[1mlocal bee\033[0m")
    m = _collect_metrics()
    cpu_str = f"{m.get('cpu_count','?')} cores, load {m.get('load_1','?')}/{m.get('load_5','?')}/{m.get('load_15','?')}"
    mem_str = f"{m.get('mem_used_mb','?')}/{m.get('mem_total_mb','?')} MB ({m.get('mem_pct','?')}%)"
    disk_str = f"{m.get('disk_used_gb','?')}/{m.get('disk_total_gb','?')} GB ({m.get('disk_pct','?')}%)"
    print(f"  cpu:  {cpu_str}")
    print(f"  mem:  {mem_str}")
    print(f"  disk: {disk_str}")
    gpus = m.get("gpus") or []
    if gpus:
        for g in gpus:
            print(f"  gpu:  [{g['index']}] {g['name']}  util={g['util_pct']}%  mem={g['mem_used_mb']}/{g['mem_total_mb']} MB  temp={g.get('temp_c','?')}°C")
    else:
        print(f"  gpu:  (none detected — nvidia-smi missing or no NVIDIA GPU)")

    # --- network / firewall ------------------------------------------------
    print("\n\033[1mnetwork\033[0m")
    import subprocess as _sp
    _r = lambda c: _sp.run(c, shell=True, capture_output=True, text=True, timeout=5)

    # LLM servers
    llms = _detect_local_ai()
    if llms:
        llm_ports = sorted(set(m["port"] for m in llms))
        port_str = ", ".join(str(p) for p in llm_ports)
        print(f"  llm:    {_ok(f'{len(llms)} model(s) on port {port_str}')}")
        # Check binding
        for port in llm_ports:
            r = _r(f"ss -tlnp 2>/dev/null | grep ':{port} '")
            if r.stdout and "127.0.0.1:" + str(port) in r.stdout:
                print(f"  bind:   {_warn(f'port {port} localhost only — run {APP} doctor --fix')}")
    else:
        print(f"  llm:    {_warn('none running')}   start with `{APP} llm serve`")

    # Tailscale — check login status, not just binary
    ts_status = _r("tailscale status --json 2>/dev/null")
    ts_ip = _r("tailscale ip -4 2>/dev/null")
    if ts_status.returncode == 0 and ts_ip.returncode == 0 and ts_ip.stdout.strip():
        import json as _json
        try:
            ts_data = _json.loads(ts_status.stdout)
            login = ts_data.get("BackendState", "unknown")
            if login == "Running":
                print(f"  vpn:    {_ok(f'tailscale active ({ts_ip.stdout.strip()})')}")
            else:
                print(f"  vpn:    {_warn(f'tailscale {login.lower()} — run: tailscale up')}   (or: tailscale logout && tailscale up)")
        except Exception:
            print(f"  vpn:    {_ok(f'tailscale active ({ts_ip.stdout.strip()})')}")
    else:
        print(f"  vpn:    {_warn('tailscale not running')}   install: curl -fsSL https://tailscale.com/install.sh | sh")

    # Firewall — `platform` is module-level; do NOT shadow it here (see the
    # resilience section above: a later local import breaks earlier uses).
    fw_ok = False
    if platform.system() == "Linux":
        r = _r("ufw status 2>/dev/null")
        if "Status: active" in r.stdout:
            # Check if LLM ports are allowed
            blocked = []
            for port in (llm_ports if llms else []):
                if f"{port}" not in r.stdout:
                    blocked.append(port)
            if blocked:
                bp = ", ".join(str(p) for p in blocked)
                print(f"  fw:     {_warn(f'ufw active but port {bp} blocked')}   run `{APP} firewall --apply`")
            else:
                print(f"  fw:     {_ok('ufw active, LLM ports open')}")
                fw_ok = True
        elif "Status: inactive" in r.stdout:
            print(f"  fw:     {_warn('ufw inactive — LLMs open to internet')}   run `{APP} firewall --apply --mode lan`")
        else:
            r2 = _r("firewall-cmd --state 2>/dev/null")
            if "running" in r2.stdout:
                print(f"  fw:     {_ok('firewalld active')}")
                fw_ok = True
            else:
                print(f"  fw:     {_warn('no firewall — LLMs open to internet')}   run `{APP} firewall --apply --mode lan`")
    elif platform.system() == "Darwin":
        r = _r("pfctl -s info 2>/dev/null")
        if "Enabled" in r.stdout:
            print(f"  fw:     {_ok('pf (macOS) active')}")
            fw_ok = True
        else:
            print(f"  fw:     {_warn('pf not active — check System Settings > Network > Firewall')}")
    elif platform.system() == "Windows":
        r = _r('netsh advfirewall show allprofiles state 2>nul')
        if "ON" in r.stdout:
            print(f"  fw:     {_ok('Windows Firewall active')}")
            fw_ok = True
        else:
            print(f"  fw:     {_warn('Windows Firewall off — LLMs open to internet')}   run `{APP} firewall --apply`")

    if not fw_ok and llms:
        print(f"\n  \033[33m⚡ your LLMs are reachable by anyone on your network\033[0m")
        print(f"  run: {APP} firewall --apply --mode lan    (LAN only, safe)")
        print(f"  or:  {APP} firewall --apply --mode tailscale (VPN only, safest)")

    # --- update check ------------------------------------------------------
    print("\n\033[1mupdate\033[0m")
    try:
        req = urllib.request.Request(f"{HUB.rstrip('/')}/{APP}-cli.py", headers={"user-agent": f"{APP}/{VERSION}"})
        with urllib.request.urlopen(req, timeout=10) as r:
            data = r.read().decode("utf-8", errors="replace")
        # content-derived version — the SAME scheme the gateway serves
        # (sha256[:8]). The old regex matched `CLI_VERSION = "0.2.0"` FIRST,
        # so hub looked permanently older → bogus "↓ local is newer" everywhere
        # (Stuarts-iMac, 2026-11-18).
        hub_ver = "0.2." + hashlib.sha256(data.encode("utf-8")).hexdigest()[:8]
        if hub_ver == VERSION:
            print(f"  {_ok(f'up to date (client {VERSION} = hub {hub_ver})')}")
        else:
            arrow = "↑ newer on hub" if hub_ver > VERSION else "↓ local is newer"
            print(f"  {_warn(f'client {VERSION} vs hub {hub_ver}')}   {arrow}   run `{APP} update`")
    except Exception as e:
        print(f"  {_warn(f'could not check hub version: {e}')}")

    print()  # trailing newline

    # Always run health checks at the end
    _run_health_checks()

    # If --fix was passed, run full auto-fix
    if getattr(args, "fix", False):
        print(f"\n\033[1mrunning full auto-fix...\033[0m")
        import subprocess as _sp
        _r = lambda c: _sp.run(c, shell=True, capture_output=True, text=True, timeout=30)

        # Fix broken scripts
        import glob as _glob
        for pattern in ["/home/*/llama.cpp/servers/start-*.sh"]:
            for s in _glob.glob(pattern):
                content = _r(f"cat {s} 2>/dev/null").stdout
                if content and "LLAMA_BIN=" in content:
                    broken_line = [l for l in content.split("\n") if l.strip().startswith("LLAMA_BIN=") and "--host" in l]
                    if broken_line:
                        _fix_llama_script(s)
                        print(f"  \033[32m✓\033[0m fixed script: {s}")

        # Fix ollama binding
        r = _r("ss -tlnp 2>/dev/null | grep ':11434 '")
        if r.stdout and "127.0.0.1:" in r.stdout:
            # Find ollama service
            for candidate in ["/etc/systemd/system/ollama.service", "/lib/systemd/system/ollama.service"]:
                if _r(f"test -f {candidate}").returncode == 0:
                    override_dir = candidate + ".d"
                    override_file = f"{override_dir}/hivv-network.conf"
                    _r(f"sudo mkdir -p {override_dir}")
                    tmp = tempfile.NamedTemporaryFile(mode='w', suffix='.conf', delete=False)
                    tmp.write('[Service]\nEnvironment="OLLAMA_HOST=0.0.0.0:11434"\n')
                    tmp.close()
                    _r(f"sudo cp {tmp.name} {override_file}")
                    _r(f"rm -f {tmp.name}")
                    _r("sudo systemctl daemon-reload")
                    _r("sudo systemctl restart ollama")
                    print(f"  \033[32m✓\033[0m ollama: configured for network access")
                    break

        # Fix llama BINDING — the doctor's advice line says
        # "run hivv doctor --fix" for localhost-only binds, so --fix must
        # actually do it (it only printed suggestions before).
        for _m in _fix_llm_bind(_r):
            mark = "✓" if _m.startswith("✓") else "!"
            colour = "32" if _m.startswith("✓") else "33"
            print(f"  \033[{colour}m{mark}\033[0m {_m}")

        # Start stopped llama services (skip duplicates/crash-loops — see _llama_start_guard)
        r = _r("systemctl list-units --type=service --state=dead --no-pager --plain --no-legend 2>/dev/null | grep -i llama | grep -v ollama")
        if r.stdout.strip():
            for line in r.stdout.strip().split("\n"):
                svc = line.split()[0] if line.split() else ""
                if not svc:
                    continue
                skip, why = _llama_start_guard(_r, svc)
                if skip:
                    print(f"  \033[33m!\033[0m would NOT start {svc}: {why}")
                    continue
                _r(f"sudo systemctl start {svc}")
                print(f"  \033[32m✓\033[0m started: {svc}")

        # Fix stale node_id
        st = read_state() or {}
        node_id = st.get("node_id", "")
        import socket
        hostname = socket.gethostname().split(".")[0]
        if node_id and "-" in node_id and node_id != hostname:
            suffix = node_id.split("-", 1)[1]
            if suffix.isdigit() and int(suffix) <= 255:
                st["node_id"] = hostname
                write_state(st)
                print(f"  \033[32m✓\033[0m reset node_id to {hostname}")

        # Create/enable systemd user service so the agent auto-starts on boot
        if platform.system() == "Linux":
            svc_dir = Path.home() / ".config" / "systemd" / "user"
            svc_path = svc_dir / "hivv-agent.service"
            svc_content = f"""[Unit]
Description=hivv AI node agent
After=network.target
# crash-loop bound: 3 starts / 5 min then failed, not an endless restart storm
StartLimitIntervalSec=300
StartLimitBurst=3

[Service]
Type=simple
ExecStart={_agent_execstart()}
Restart=always
RestartSec=10
WorkingDirectory={Path.home() / ".local" / "share" / APP}
StandardOutput=append:{Path.home() / ".local" / "share" / APP / "agent.log"}
StandardError=append:{Path.home() / ".local" / "share" / APP / "agent.log"}

[Install]
WantedBy=default.target
"""
            _r(f"mkdir -p {svc_dir}")
            tmp = tempfile.NamedTemporaryFile(mode='w', suffix='.service', delete=False)
            tmp.write(svc_content)
            tmp.close()
            _r(f"cp {tmp.name} {svc_path}")
            _r(f"rm -f {tmp.name}")
            _r("systemctl --user daemon-reload")
            _r("systemctl --user enable --now hivv-agent")
            print(f"  \033[32m✓\033[0m systemd service: hivv-agent.service (enabled, started)")

            # …and the LLM's boot unit — `--fix` is blanket consent to repair,
            # so an installed model without a llama unit gets one (previously
            # `doctor --fix` only fixed the AGENT's boot story).
            _bstate, _bunit = _llm_boot_probe()
            if _bstate in ("none", "disabled"):
                _m, _p, _h, _c = _llm_effective()
                if _m:
                    _okb, _bmsg = _llm_boot_enable(_m, _p, _h, _c)
                    mark = "✓" if _okb else "!"
                    print(f"  \033[32m{mark}\033[0m llm boot: {_bmsg}" if _okb
                          else f"  \033[33m{mark}\033[0m llm boot: {_bmsg}")

        # Create/enable a LaunchAgent so the agent auto-starts at login (macOS)
        elif platform.system() == "Darwin":
            plist_dir = Path.home() / "Library" / "LaunchAgents"
            plist_path = plist_dir / "org.hivv.agent.plist"
            if not plist_path.exists():
                plist_dir.mkdir(parents=True, exist_ok=True)
                plist = f"""<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>Label</key><string>org.hivv.agent</string>
  <key>ProgramArguments</key>
  <array>
    <string>{sys.executable}</string>
    <string>{Path(__file__).resolve()}</string>
    <string>_agent</string>
  </array>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
  <key>StandardOutPath</key><string>{Path.home() / ".local" / "share" / APP / "agent.log"}</string>
  <key>StandardErrorPath</key><string>{Path.home() / ".local" / "share" / APP / "agent.log"}</string>
  <key>Nice</key><integer>10</integer>
</dict>
</plist>
"""
                plist_path.write_text(plist)
                _r(f"launchctl bootout gui/{os.getuid()}/org.hivv.agent")
                r_boot = _r(f"launchctl bootstrap gui/{os.getuid()} {plist_path}")
                if r_boot.returncode != 0:
                    _r(f"launchctl load -w {plist_path}")
                print(f"  \033[32m✓\033[0m LaunchAgent: org.hivv.agent (starts at login)")

        # Windows: hint at Task Scheduler (registering from CLI needs careful
        # quoting; give the exact command instead of silently doing nothing)
        elif platform.system() == "Windows":
            print(f"  \033[33m⚠\033[0m to auto-start at login on Windows, run in PowerShell:")
            print(f"    schtasks /Create /TN hivv /TR \"cmd /c {APP} start\" /SC ONLOGON /RL LIMITED /F")
            print(f"    (or simply keep a terminal with: {APP} start)")

        print(f"\n  \033[32m✓ auto-fix complete\033[0m")
    else:
        print(f"\n  to auto-fix all issues: {APP} doctor --fix")

def cmd_firewall(args) -> None:
    """Detect local LLM servers and configure firewall to let other hivv nodes reach them.
    Supports: LAN-only (default), Tailscale VPN, or manual rules.
    Cross-platform: ufw/firewalld (Linux), pf (macOS), Windows Firewall."""
    import subprocess, platform

    system = platform.system()
    ok = "\033[32m✓\033[0m"
    warn = "\033[33m!\033[0m"
    fail = "\033[31m✗\033[0m"

    # 1. Detect running LLM servers
    models = _detect_local_ai()

    # Helper: write a systemd service file reliably
    def _write_svc_file(path, content):
        """Write content to a systemd service file using temp file + sudo cp."""
        import tempfile
        tmp = tempfile.NamedTemporaryFile(mode='w', suffix='.service', delete=False)
        tmp.write(content)
        tmp.close()
        r = _run(f"sudo cp {tmp.name} {path}")
        _run(f"rm -f {tmp.name}")
        return r

    # Helper: fix a broken llama startup script
    def _fix_llama_script(script_path):
        """Fix a llama startup script — ensure --host 0.0.0.0 is on the right lines."""
        if _run(f"test -f {script_path}").returncode != 0:
            return False
        content = _run(f"cat {script_path}").stdout
        fixed = False
        new_lines = []
        for line in content.split("\n"):
            stripped = line.strip()
            # Fix broken LLAMA_BIN= line that has --host attached
            if stripped.startswith("LLAMA_BIN=") and "--host" in stripped:
                line = line.replace(" --host 0.0.0.0", "").replace(" --host", "")
                fixed = True
            # Add --host 0.0.0.0 to lines that invoke the binary (have -m or --port)
            if ("$LLAMA_BIN" in line or "llama-server" in line) and ("-m " in line or "--port" in line) and "--host" not in line:
                line = line.replace("llama-server ", "llama-server --host 0.0.0.0 ", 1) if "llama-server" in line else line.replace("$LLAMA_BIN ", "$LLAMA_BIN --host 0.0.0.0 ", 1)
                fixed = True
            new_lines.append(line)
        if fixed:
            import tempfile
            tmp = tempfile.NamedTemporaryFile(mode='w', suffix='.sh', delete=False)
            tmp.write("\n".join(new_lines))
            tmp.close()
            _run(f"sudo cp {tmp.name} {script_path} && sudo chmod +x {script_path}")
            _run(f"rm -f {tmp.name}")
        return fixed

    if not models:
        print(f"\n{fail} No local LLM servers found running.")
        print(f"   Start one first: {APP} llm serve")
        return

    ports = sorted(set(m["port"] for m in models))
    print(f"\n\033[1m{APP} firewall\033[0m")
    print(f"   detected LLMs on ports: {', '.join(str(p) for p in ports)}")
    for m in models:
        name = m["model"].split("/")[-1].replace(".gguf", "")[:40]
        print(f"   {m['provider']}: {name} (:{m['port']})")

    # 2. Check binding — are LLMs listening on 0.0.0.0 (network) or 127.0.0.1 (localhost only)?
    _run = lambda cmd: subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=10)
    print(f"\n\033[1mbinding\033[0m")
    localhost_only = []
    bound_ok = []
    for port in ports:
        try:
            r = _run(f"ss -tlnp 2>/dev/null | grep ':{port} '")
            if r.stdout.strip():
                # Parse: "LISTEN 0 512 127.0.0.1:8080 0.0.0.0:* users:..."
                if "127.0.0.1:" + str(port) in r.stdout:
                    localhost_only.append(port)
                    # Find the process name
                    proc_match = r.stdout.split("users:((")[1].split(",")[0].strip('"') if "users:((" in r.stdout else "unknown"
                    print(f"   {fail} port {port} — localhost only ({proc_match})")
                elif "0.0.0.0:" + str(port) in r.stdout or "*:" + str(port) in r.stdout:
                    bound_ok.append(port)
                    print(f"   {ok} port {port} — bound to 0.0.0.0 (network reachable)")
                else:
                    bound_ok.append(port)
                    print(f"   {ok} port {port} — listening")
            else:
                # Not showing in ss — might be bound differently
                print(f"   {warn} port {port} — cannot determine binding")
        except Exception:
            print(f"   {warn} port {port} — cannot check binding")

    if localhost_only:
        print(f"\n   {fail} PROBLEM: LLMs bound to 127.0.0.1 — other nodes CANNOT reach them")
        print(f"   other machines see: connection refused or timeout")
        print(f"\n   to fix, restart your LLMs with --host 0.0.0.0:")
        for port in localhost_only:
            proc_info = _run(f"ss -tlnp 2>/dev/null | grep ':{port} '")
            if "llama-server" in proc_info.stdout:
                # Try to find the original command
                pid_match = _run(f"ss -tlnp 2>/dev/null | grep ':{port} ' | grep -o 'pid=[0-9]*'")
                pid = pid_match.stdout.replace("pid=", "").strip() if pid_match.stdout else ""
                cmdline = ""
                if pid:
                    cmdline_file = _run(f"cat /proc/{pid}/cmdline 2>/dev/null")
                    cmdline = cmdline_file.stdout.replace("\x00", " ").strip() if cmdline_file.stdout else ""
                if cmdline and "--host" in cmdline:
                    # Replace --host 127.0.0.1 with --host 0.0.0.0
                    fixed = cmdline.replace("--host 127.0.0.1", "--host 0.0.0.0").replace("--host", "--host 0.0.0.0")
                    print(f"   {APP} llm serve --host 0.0.0.0 --port {port}")
                else:
                    print(f"   {APP} llm serve --host 0.0.0.0 --port {port}")
            elif "ollama" in proc_info.stdout:
                print(f"   sudo systemctl set-environment OLLAMA_HOST=0.0.0.0:11434 && sudo systemctl restart ollama")
            else:
                print(f"   restart the LLM server with: --host 0.0.0.0 --port {port}")

    else:
        print(f"   {ok} all LLMs bound to 0.0.0.0 — network reachable")

    # Look for stopped LLMs (informational only)
    import glob as _glob
    for pattern in ["/home/*/llama.cpp/servers/start-*.sh"]:
        for s in _glob.glob(pattern):
            content = _r(f"cat {s} 2>/dev/null").stdout
            if content and "llama-server" in content:
                print(f"  {warn} startup script found: {s}")

    print(f"\n  to auto-fix all issues: {APP} doctor --fix")

    # 3. Check for Tailscale
    # 3. Check for Tailscale
    tailscale_ip = None
    tailscale_ok = False
    try:
        r = _run("tailscale ip -4 2>/dev/null")
        if r.returncode == 0 and r.stdout.strip():
            tailscale_ip = r.stdout.strip()
            tailscale_ok = True
            print(f"\n\033[1mtailscale\033[0m")
            print(f"   {ok} detected — VPN IP: {tailscale_ip}")
            r2 = _run("tailscale status --json 2>/dev/null")
            if r2.returncode == 0:
                import json as _json
                try:
                    ts = _json.loads(r2.stdout)
                    peers = ts.get("Peer", {})
                    online = sum(1 for p in peers.values() if p.get("Online"))
                    print(f"   {ok} {online} peer(s) connected via Tailscale")
                except Exception:
                    pass
    except Exception:
        pass

    if not tailscale_ok:
        print(f"\n\033[1mtailscale\033[0m")
        print(f"   {warn} not installed — nodes on different networks won't reach you")
        print(f"   install: curl -fsSL https://tailscale.com/install.sh | sh")
        print(f"   then:    sudo tailscale up")

    # 3. Detect LAN subnet
    lan_ip = ""
    lan_subnet = ""
    try:
        if system == "Linux":
            r = _run("hostname -I")
            if r.stdout.strip():
                lan_ip = r.stdout.strip().split()[0]
        elif system == "Darwin":
            r = _run("ipconfig getifaddr en0 2>/dev/null")
            if r.stdout.strip():
                lan_ip = r.stdout.strip()
        elif system == "Windows":
            r = _run('powershell -Command "(Get-NetIPAddress -AddressFamily IPv4 | Where-Object {$_.InterfaceAlias -notlike \'*Loopback*\' -and $_.IPAddress -ne \'127.0.0.1\'}).IPAddress | Select-Object -First 1"')
            if r.stdout.strip():
                lan_ip = r.stdout.strip().split("\n")[0].strip()
    except Exception:
        pass

    if lan_ip:
        parts = lan_ip.split(".")
        if len(parts) == 4:
            lan_subnet = f"{parts[0]}.{parts[1]}.{parts[2]}.0/24"
        print(f"\n\033[1mnetwork\033[0m")
        print(f"   {ok} LAN IP: {lan_ip}")
        print(f"   {ok} subnet: {lan_subnet}")

    # 4. Check current firewall status
    print(f"\n\033[1mfirewall status\033[0m")

    fw_tool = None
    if system == "Linux":
        r = _run("ufw status 2>/dev/null")
        if "Status: active" in r.stdout:
            print(f"   {ok} ufw active")
            fw_tool = "ufw"
        elif "Status: inactive" in r.stdout:
            print(f"   {warn} ufw installed but inactive")
            fw_tool = "ufw"
        else:
            r2 = _run("firewall-cmd --state 2>/dev/null")
            if "running" in r2.stdout:
                print(f"   {ok} firewalld active")
                fw_tool = "firewalld"
            else:
                r3 = _run("iptables -L INPUT -n 2>/dev/null")
                if r3.returncode == 0:
                    print(f"   {warn} iptables active (no ufw/firewalld)")
                    fw_tool = "iptables"
                else:
                    print(f"   {warn} no firewall detected — ports may be open to everyone")
    elif system == "Darwin":
        r = _run("pfctl -s info 2>/dev/null")
        if "Enabled" in r.stdout:
            print(f"   {ok} pf (macOS firewall) active")
            fw_tool = "pf"
        else:
            print(f"   {warn} pf not active")
            fw_tool = "pf"
    elif system == "Windows":
        r = _run('netsh advfirewall show allprofiles state 2>nul')
        if "ON" in r.stdout:
            print(f"   {ok} Windows Firewall active")
            fw_tool = "windows"
        else:
            print(f"   {warn} Windows Firewall inactive")
            fw_tool = "windows"

    # 5. Determine which ports need rules
    closed_ports = []
    if fw_tool == "ufw":
        r = _run("ufw status numbered 2>/dev/null")
        for port in ports:
            if f"{port}" not in r.stdout:
                closed_ports.append(port)
    elif fw_tool == "firewalld":
        for port in ports:
            r = _run(f"firewall-cmd --query-port={port}/tcp 2>/dev/null")
            if "no" in r.stdout:
                closed_ports.append(port)
    elif fw_tool == "pf":
        r = _run("pfctl -sr 2>/dev/null")
        for port in ports:
            if str(port) not in r.stdout:
                closed_ports.append(port)
    elif fw_tool == "windows":
        for port in ports:
            r = _run(f'netsh advfirewall firewall show rule name="hivv {port}" 2>nul')
            if "hivv" not in r.stdout.lower():
                closed_ports.append(port)

    if not closed_ports:
        print(f"\n{ok} All LLM ports already have firewall rules.")
    else:
        print(f"\n   ports needing rules: {', '.join(str(p) for p in closed_ports)}")

    # 6. Show security options
    do_apply = getattr(args, "apply", False)
    mode = getattr(args, "mode", "lan") or "lan"

    print(f"\n\033[1msecurity modes\033[0m")
    print(f"   \033[1mlan\033[0m      — only allow your LAN subnet ({lan_subnet or 'x.x.x.0/24'})")
    print(f"   \033[1mtailscale\033[0m — only allow Tailscale VPN peers (safest, no ports to internet)")
    print(f"   \033[1mopen\033[0m     — allow from anywhere (NOT recommended)")

    if not do_apply:
        print(f"\n   to apply, run:")
        print(f"   {APP} firewall --apply --mode lan")
        print(f"   {APP} firewall --apply --mode tailscale")
        print(f"\n   or configure manually:")
        for port in closed_ports:
            if fw_tool == "ufw" and lan_subnet:
                print(f"   sudo ufw allow from {lan_subnet} to any port {port} proto tcp")
            elif fw_tool == "ufw":
                print(f"   sudo ufw allow {port}/tcp")
        return

    # 7. Apply rules based on mode
    print(f"\n\033[1mapplying {mode} rules...\033[0m")

    # Build allow sources
    allow_from = []
    if mode == "lan" and lan_subnet:
        allow_from.append(("LAN", lan_subnet))
    if mode == "tailscale" and tailscale_ip:
        # Tailscale uses 100.x.x.x/32 per device, or 100.64.0.0/10 range
        allow_from.append(("Tailscale", "100.64.0.0/10"))
    if mode == "open":
        allow_from.append(("any", None))

    if not allow_from:
        print(f"   {fail} no valid source for mode '{mode}'")
        if mode == "tailscale" and not tailscale_ip:
            print(f"   install tailscale first: curl -fsSL https://tailscale.com/install.sh | sh && sudo tailscale up")
        return

    for port in closed_ports:
        for label, source in allow_from:
            if fw_tool == "ufw":
                if source:
                    r = _run(f"sudo ufw allow from {source} to any port {port} proto tcp")
                else:
                    r = _run(f"sudo ufw allow {port}/tcp")
                if r.returncode == 0:
                    print(f"   {ok} ufw: port {port} allowed from {label}")
                else:
                    print(f"   {fail} ufw: failed: {r.stderr.strip()}")

            elif fw_tool == "firewalld":
                if source:
                    r = _run(f"sudo firewall-cmd --add-rich-rule='rule family=ipv4 source address={source} port port={port} protocol=tcp accept' --permanent")
                else:
                    r = _run(f"sudo firewall-cmd --add-port={port}/tcp --permanent")
                _run("sudo firewall-cmd --reload")
                if r.returncode == 0:
                    print(f"   {ok} firewalld: port {port} allowed from {label}")
                else:
                    print(f"   {fail} firewalld: failed: {r.stderr.strip()}")

            elif fw_tool == "pf":
                rule = f"pass in proto tcp from {source or 'any'} to any port {port}"
                print(f"   {warn} pf: add to /etc/pf.conf: {rule}")
                print(f"   then: sudo pfctl -f /etc/pf.conf")

            elif fw_tool == "windows":
                if source:
                    r = _run(f'netsh advfirewall firewall add rule name="hivv {port} {label}" dir=in action=allow protocol=TCP localport={port} remoteip={source}')
                else:
                    r = _run(f'netsh advfirewall firewall add rule name="hivv {port}" dir=in action=allow protocol=TCP localport={port}')
                if r.returncode == 0:
                    print(f"   {ok} Windows: port {port} allowed from {label}")
                else:
                    print(f"   {fail} Windows: failed: {r.stderr.strip()}")

    # 8. Also handle gateway port 3011
    if fw_tool and "3011" not in str(closed_ports):
        pass  # already open or not needed
    elif fw_tool == "ufw" and do_apply:
        for label, source in allow_from:
            if source:
                _run(f"sudo ufw allow from {source} to any port 3011 proto tcp")
            else:
                _run(f"sudo ufw allow 3011/tcp")
        print(f"   {ok} gateway port 3011 configured")

    # THE OLD LINE PRINTED "firewall configured!" — untrue whenever ufw is
    # inactive, because `--apply` never runs `ufw enable` (verified: there is
    # no `ufw enable`, no `ufw default deny` and no `iptables -P INPUT`
    # anywhere in this repo). Rules staged against a DISABLED ufw are inert,
    # so the command reported success while `hivv security` kept flagging
    # "host firewall is not active" — the remedy did not remedy. Say what
    # actually happened, and hand over the sequence that really activates
    # protection, with `allow 22` FIRST: a host that SSHes in from the
    # internet locks itself out the instant default-deny lands without it.
    if fw_tool == "ufw" and _firewall_active() is False:
        print(f"\n   {warn} allow-rules written, but ufw is still INACTIVE — nothing is enforced yet.")
        print(f"   to actually turn protection on (allow 22 FIRST):")
        print(f"      sudo ufw allow 22/tcp")
        print(f"      sudo ufw default deny incoming")
        print(f"      sudo ufw enable")
    else:
        print(f"\n{ok} firewall configured!")
        if mode == "lan":
            print(f"   your LLMs are only reachable from your LAN ({lan_subnet})")
        elif mode == "tailscale":
            print(f"   your LLMs are only reachable via Tailscale VPN")
            print(f"   other hivv nodes need Tailscale installed to reach you")
    print(f"   restart llama.cpp for changes to take effect (if binding to specific IPs)")

def cmd_up(args) -> None:
    """Quick 3-line status check — the "you good?" command."""
    ok = "\033[32m●\033[0m"
    warn = "\033[33m●\033[0m"
    fail = "\033[31m●\033[0m"

    # service
    pid = read_pid()
    if pid and _pid_alive_fallback(pid):
        st = read_state() or {}
        hb = st.get("last_heartbeat") or 0
        age = int(time.time()) - hb if hb else -1
        hb_str = f"{age}s ago" if age >= 0 else "?"
        print(f"{ok} service  running (pid {pid}, hb {hb_str})")
    else:
        print(f"{warn} service  not running — {APP} start")

    # hub
    try:
        code, _ = http("GET", "/api/health", timeout=5)
        print(f"{ok} hub      {HUB} reachable")
    except Exception:
        print(f"{fail} hub      {HUB} unreachable")

    # version
    print(f"  version  {VERSION}")

    # pending MAYBE approvals pushed to this node's inbox (hivv OS §3)
    pending = _approvals_load()
    if pending:
        caps = ", ".join(sorted({(p.get("capability") or "?") for p in pending}))
        print(f"{warn} approvals {len(pending)} action(s) await a human — {caps}")
        print(f"           → {APP} approve --list   (or {APP} approve <G_xxx> / {APP} deny <G_xxx>)")

    # rank-up celebration (quiet unless something changed)
    _celebrate_rank_up()


def _argparse_command_index() -> dict:
    """Walk the REAL parser — every command, its flags, positionals, help.
    Introspection instead of a hand-written list → the index CANNOT drift
    from the code (the AI-facing map stays true by construction)."""
    p = build_parser()
    top_flags, cmds = [], []
    for act in p._actions:
        if not isinstance(act, argparse._SubParsersAction):
            if act.option_strings and "--help" not in act.option_strings:
                top_flags.append({"flag": "/".join(act.option_strings),
                                  "help": (act.help or "").strip()})
            continue
        helps = {}
        for ca in getattr(act, "_choices_actions", []):
            nm = getattr(ca, "dest", None) or getattr(ca, "name", "") or ""
            helps[nm] = (getattr(ca, "help", "") or "").strip()
        for name, sub in act.choices.items():
            if name.startswith("-"):
                continue
            flags, pos, subs = [], [], []
            for a2 in sub._actions:
                if isinstance(a2, argparse._SubParsersAction):
                    subs = sorted(k for k in a2.choices if not k.startswith("-"))
                    continue
                if a2.option_strings:
                    if set(a2.option_strings) <= {"-h", "-help", "--help"}:
                        continue
                    flags.append({"flag": "/".join(a2.option_strings),
                                  "help": (a2.help or "").strip()})
                elif a2.dest != "help":
                    pos.append({"name": a2.dest, "required": bool(a2.required),
                                "help": (a2.help or "").strip()})
            cmds.append({"command": name, "help": helps.get(name, ""),
                         "subcommands": subs, "flags": flags, "args": pos})
    cmds.sort(key=lambda c: c["command"])
    return {"app": APP, "version": VERSION, "top_flags": top_flags,
            "count": len(cmds), "commands": cmds}


def cmd_commands(args) -> None:
    """Self-describing index of EVERY hivv command — introspected from the
    live parser. `hivv commands --json` is the ONE call an agent should make
    first: full command/flag map, no parsing, no drift."""
    idx = _argparse_command_index()
    if getattr(args, "json_output", False):
        print(json.dumps(idx, indent=2))
        return
    tf = " ".join(f["flag"] for f in idx["top_flags"] if f.get("flag"))
    print(f"\n\033[1m{APP} commands\033[0m — {idx['count']} commands, "
          f"self-described from the live parser\n")
    if tf:
        print(f"  top flags: {tf}")
    print()
    for c in idx["commands"]:
        print(f"  {c['command']:<20} {c['help']}")
        if c["subcommands"]:
            print(f"      sub: {' · '.join(c['subcommands'])}")
    print(f"\n  \033[2mmachine form: {APP} commands --json   · HTTP spec: {HUB}/openapi.yaml"
          f"   · agent tools (no parsing): {HUB}/mcp\033[0m\n")


def cmd_speed(args) -> None:
    """Latency benchmark: DNS, TLS, hub ping, chat round-trip."""
    print(f"\033[1m{APP} speed\033[0m — latency benchmark")
    hub_host = HUB.replace("https://", "").replace("http://", "").split("/")[0]
    hub_scheme = "https" if HUB.startswith("https://") else "http"

    # 1. DNS
    t0 = time.time()
    try:
        ip = socket.gethostbyname(hub_host)
        dns_ms = int((time.time() - t0) * 1000)
        print(f"  dns   {hub_host:30s} → {ip:15s}   {dns_ms:4d}ms")
    except Exception as e:
        print(f"  dns   {hub_host:30s} → \033[31mFAIL\033[0m ({e})")
        return

    # 2. TCP connect
    t0 = time.time()
    try:
        s = socket.create_connection((hub_host, 443 if hub_scheme == "https" else 80), timeout=5)
        tcp_ms = int((time.time() - t0) * 1000)
        s.close()
        print(f"  tcp   {hub_host}:443                      {tcp_ms:4d}ms")
    except Exception as e:
        print(f"  tcp   {hub_host}:443                      \033[31mFAIL\033[0m ({e})")
        return

    # 3. hub ping x3
    pings = []
    for i in range(3):
        t0 = time.time()
        try:
            code, _ = http("GET", "/api/health", timeout=5)
            ms = int((time.time() - t0) * 1000)
            pings.append(ms)
            mark = _ok(f"{ms}ms") if code == 200 else _fail(f"{ms}ms HTTP {code}")
            print(f"  ping  GET /api/health       #{i+1}            {mark}")
        except Exception as e:
            print(f"  ping  GET /api/health       #{i+1}            \033[31mFAIL\033[0m ({e})")
    if pings:
        print(f"  ping  min/avg/max = {min(pings)}/{sum(pings)//len(pings)}/{max(pings)}ms")

    # 4. chat round-trip (time to first byte + total)
    print()
    print(f"  chat  POST /api/chat (short prompt)")
    try:
        # Stream one short chat and measure time-to-first-byte
        url = HUB.rstrip("/") + "/api/chat"
        req = urllib.request.Request(url, data=json.dumps({"message": "say hi in 3 words"}).encode(),
                                     method="POST",
                                     headers={"content-type": "application/json",
                                              "accept": "text/event-stream",
                                              "user-agent": f"{APP}/{VERSION}"})
        t0 = time.time()
        with urllib.request.urlopen(req, timeout=30) as r:
            ttfb = int((time.time() - t0) * 1000)
            buf = b""
            total_bytes = 0
            got_content = False
            while True:
                chunk = r.read(1)
                if not chunk: break
                buf += chunk
                total_bytes += 1
                if buf.endswith(b"\n"):
                    line = buf.decode("utf-8", errors="replace").strip()
                    buf = b""
                    if line.startswith("data:") and line[5:].strip() not in ("", "[DONE]"):
                        try:
                            evt = json.loads(line[5:].strip())
                            choices = evt.get("choices") or []
                            if choices and (choices[0].get("delta") or {}).get("content"):
                                got_content = True
                                total_ms = int((time.time() - t0) * 1000)
                                print(f"        time-to-first-byte: {ttfb}ms   total: {total_ms}ms   bytes: {total_bytes}")
                                # drain the rest so we close cleanly
                                while r.read(4096): pass
                                break
                        except json.JSONDecodeError:
                            pass
    except Exception as e:
        print(f"  chat  \033[31mFAIL\033[0m ({e})")
    else:
        if total_bytes == 0:
            print(f"        (stream ended with no bytes)")
        elif not got_content:
            print(f"        (stream ended without a content chunk — {total_bytes} bytes)")

    # 5. CPU/RAM/disk (delegate to llm bench)
    print()
    print(f"  bench CPU/RAM/disk:")
    try:
        cmd_llm_bench(args)  # reuse the existing llm bench routine
    except Exception as e:
        print(f"        \033[31mFAIL\033[0m ({e})")


def _load_testmap() -> dict:
    """The committed source→tests map, building it once if absent.

    A missing map must not brick the command — the first run generates it
    (static analysis, well under a second) and prints a note.
    """
    repo = _find_repo_root()
    if repo is None:
        return {}
    mp = repo / "tests" / "TESTMAP.json"
    if not mp.exists():
        print(f"  \033[2mbuilding the test map (first run)…\033[0m")
        subprocess.run([sys.executable, str(repo / "tests" / "gen_testmap.py")],
                       capture_output=True, timeout=120)
    try:
        return json.loads(mp.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}


def _tests_for_paths(paths: list[str]) -> tuple[dict, list[str]]:
    """(per-path test lists, unmapped paths) for repo-relative inputs.

    Exact match first. On a miss, walk UP the directory tree: some tests
    reference a DIRECTORY (`REPO / "public_html"` — they glob it), so a
    file inside that directory is covered by them even though it has no
    entry of its own. Marked `via <dir>` so the answer is never
    misleading about WHY those tests apply.
    """
    mapping = _load_testmap()
    srcs = mapping.get("sources") or {}
    per: dict[str, list[str]] = {}
    missing: list[str] = []
    for raw in paths:
        rel = _repo_relative(raw)
        if rel is None:
            missing.append(raw)
            continue
        hits = srcs.get(rel)
        if hits:
            per[rel] = list(hits)
            continue
        # ancestor-directory fallback
        parts = rel.split("/")
        found = None
        for i in range(len(parts) - 1, 0, -1):
            ancestor = "/".join(parts[:i])
            if ancestor in srcs:
                found = (ancestor, srcs[ancestor])
                break
        if found:
            per[rel] = sorted({f"{t} (via {found[0]}/)" for t in found[1]})
        else:
            missing.append(rel)
    return per, missing


def _repo_relative(raw: str) -> str | None:
    """Turn whatever the user typed into a repo-relative path (or None)."""
    repo = _find_repo_root()
    if repo is None:
        return None
    p = Path(str(raw)).expanduser()
    try:
        if not p.is_absolute():
            p = (Path.cwd() / p)
        p = p.resolve()
        rel = str(p.relative_to(repo.resolve()))
    except (ValueError, OSError):
        # not under the repo — maybe they typed the repo-relative form
        cand = str(raw).lstrip("./")
        if (repo / cand).exists():
            return cand
        return None
    return rel


def cmd_tests_for(args) -> None:
    """I edited <file> — which tests must I run?

    `hivv tests-for <file>...`  → the test files that exercise it + the
                                   exact command to run them
    `hivv tests-for --diff`     → same, for everything YOU changed
                                   (working tree vs HEAD)
    `hivv tests-for --refresh`  → rebuild the map first (after adding tests)

    The map lives in tests/TESTMAP.json (built by static analysis — no test
    is run to produce it) and is pinned fresh by tests/test_testmap.py, so
    it cannot silently rot: add a test file and the suite tells you to
    regenerate.

    Honest limits, stated out loud: the map UNDER-claims (a test reaching a
    file through a runtime-computed path is invisible to static analysis),
    so when a file has no entry the advice is always "run the full suite"
    — never "you're fine".
    """
    refresh = bool(getattr(args, "refresh", False))
    strict = bool(getattr(args, "strict", False))
    diff_ref = getattr(args, "diff", None)      # None | "" (HEAD) | <ref>
    paths = list(getattr(args, "paths", None) or [])

    repo = _find_repo_root()
    if repo is None:
        die("no repo found — `hivv tests-for` needs a clone of the project")

    if refresh:
        print("  rebuilding tests/TESTMAP.json …")
        r = subprocess.run([sys.executable, str(repo / "tests" / "gen_testmap.py")],
                           capture_output=True, text=True, timeout=120)
        if r.returncode != 0:
            die(f"map rebuild failed: {(r.stderr or r.stdout)[-400:]}")
        print(f"  {r.stdout.strip()}")

    if diff_ref is not None:
        ref = diff_ref or "HEAD"
        rc, out = _git("diff", "--name-only", ref, timeout=30)
        if rc != 0:
            die(f"git diff {ref} failed — pass a ref (e.g. --diff origin/main)")
        paths += [l.strip() for l in out.splitlines() if l.strip()]

    # de-dup, keep order
    seen, uniq = set(), []
    for pth in paths:
        if pth not in seen:
            seen.add(pth)
            uniq.append(pth)
    paths = uniq

    if not paths:
        die(f"nothing to look up\n"
            f"  usage: {APP} tests-for <file>...\n"
            f"         {APP} tests-for --diff            # everything you changed\n"
            f"         {APP} tests-for --diff origin/main # everything vs GitHub\n"
            f"  full suite: {APP} verify")

    per, missing = _tests_for_paths(paths)

    print(f"\n\033[1m{APP} tests-for\033[0m — {len(paths)} file(s)\n")
    py_tests: list[str] = []
    js_tests: list[str] = []
    for src, tsts in per.items():
        print(f"  \033[1m{src}\033[0m")
        for tst in tsts:
            print(f"    → {tst}")
        for tst in tsts:
            # strip the " (via <dir>/)" display annotation — it must never
            # reach the run command, or the pytest invocation is invalid
            clean = re.sub(r"\s*\(via [^)]+\)$", "", tst)
            (js_tests if clean.endswith(".test.js") else py_tests).append(clean)
        print()

    if missing:
        print("  \033[33m○ no dedicated test references\033[0m "
              + ", ".join(f"`{m}`" for m in missing))
        print("    (the map under-claims by design — the full suite is your gate)")
        print()

    if not py_tests and not js_tests:
        print(f"  run everything:  {APP} verify")
        print(f"                   python3 -m pytest tests/ -q   +   cd api && node --test\n")
        sys.exit(1 if strict else 0)

    if py_tests:
        uniq_py = sorted(set(py_tests))
        print(f"  \033[1mrun (python)\033[0m:")
        print(f"    python3 -m pytest {' '.join(uniq_py)} -q")
    if js_tests:
        uniq_js = sorted(set(js_tests))
        rel_js = [j.replace("api/", "", 1) for j in uniq_js]
        print(f"  \033[1mrun (node)\033[0m:")
        print(f"    cd api && node --test {' '.join(rel_js)}")
    print(f"\n  \033[2mfull suite (always safe): {APP} verify\033[0m\n")

    if strict and missing:
        sys.exit(1)


def cmd_verify(args) -> None:
    """Verify YOUR changes still work — run the shipped test suite.

    `hivv verify`            → run tests/ against this tree
    `hivv verify --diff`     → also show what you changed vs GitHub
    `hivv verify --review`   → ask the hive whether your diff looks safe

    WHY THIS EXISTS
    The test suite ships with the repo (tests/, 500+ checks, also run by
    CI on every push). It answers the question a fork must answer before
    it ships: "I modified the code — did I break anything?" Without it,
    every customisation is a leap of trust; with it, a change either
    passes the same gate the original passes, or it does not, and the
    failing test says exactly what broke.

    Run it from a CLONE of the repo (it needs tests/ beside the code). An
    installed CLI has no tree — that is the normal case for a bee, and
    this says so instead of failing mysteriously.
    """
    want_diff = bool(getattr(args, "diff", False))
    want_review = bool(getattr(args, "review", False))

    repo = _find_repo_root()
    if repo is None:
        die(f"no repo found near {Path(__file__).resolve()}\n"
            "  `hivv verify` runs the shipped test suite, which lives in a\n"
            "  CLONE of the repo — an installed CLI does not carry it.\n"
            f"    git clone https://github.com/{GITHUB_REPO}.git\n"
            "    cd hivv && hivv verify")

    tests_dir = repo / "tests"
    if not tests_dir.is_dir():
        die(f"{repo} has no tests/ directory — nothing to verify")

    print(f"\n\033[1m{APP} verify\033[0m — running the shipped test suite\n")
    print(f"  repo:    {repo}")

    # What changed here vs GitHub? (read-only, best-effort)
    if want_diff:
        loc = _local_git_state()
        if loc["is_repo"]:
            print(f"  local:   {loc['branch']} @ {loc['short']}"
                  + (f" · {loc['dirty']} uncommitted" if loc["dirty"] else "")
                  + (f" · {loc['ahead']} ahead" if loc["ahead"] else "")
                  + (f" · {loc['behind']} behind" if loc["behind"] else ""))
            diff = _collect_diff()
            if diff.strip():
                print(f"  diff:    {diff.count(chr(10))} lines of local changes")
                print()
                for line in diff.splitlines()[:60]:
                    print(f"  \033[2m{line}\033[0m")
                if diff.count(chr(10)) > 60:
                    print(f"  \033[2m… {diff.count(chr(10)) - 60} more lines\033[0m")
            else:
                print("  diff:    \033[32mnone — this tree matches GitHub\033[0m")
        print()

    # Run the suite. pytest first (it is what CI runs); fall back to unittest
    # discovery if pytest is not installed — a user must never need to
    # install a test runner just to check their own work.
    suite_ran = False
    try:
        import pytest  # noqa: F401
        has_pytest = True
    except ImportError:
        has_pytest = False

    # Mark the child run: a test that drives `hivv verify` would otherwise
    # spawn verify → pytest → that test → verify → … forever. The guard lets
    # the test skip itself when it is the CHILD, while still running when a
    # human or CI invokes it directly.
    child_env = dict(os.environ, HIVV_VERIFY_RUNNING="1")

    if has_pytest:
        print("  running: python3 -m pytest tests/ -q")
        print()
        r = subprocess.run([sys.executable, "-m", "pytest", "tests/", "-q"],
                           cwd=str(repo), capture_output=True, text=True,
                           timeout=900, env=child_env)
        print(r.stdout or "")
        if r.stderr.strip():
            print(r.stderr)
        passed = r.returncode == 0
        suite_ran = True
    else:
        print("  pytest not installed — falling back to unittest discovery")
        print()
        r = subprocess.run([sys.executable, "-m", "unittest", "discover",
                            "-s", "tests", "-p", "test_*.py", "-q"],
                           cwd=str(repo), capture_output=True, text=True,
                           timeout=900, env=child_env)
        print(r.stdout or "")
        if r.stderr.strip():
            print(r.stderr)
        passed = r.returncode == 0
        suite_ran = True

    print()
    if passed:
        print(f"  \033[32m✓\033[0m \033[1mVERIFIED\033[0m — your changes pass the suite "
              f"the original passes")
    else:
        print(f"  \033[31m✗\033[0m \033[1mFAILED\033[0m — the suite above says what broke")
        print("     a failing test is a gift: it names the exact thing your")
        print("     change broke, before a user finds it")

    # Ask the hive for a second opinion on the diff itself.
    if want_review and suite_ran:
        print()
        cmd_review_diff(argparse.Namespace(staged=False, file=None, votes=1))

    print()
    sys.exit(0 if passed else 1)


def _find_repo_root() -> Path | None:
    """The hivv repo this CLI belongs to — or None.

    Probes TWO starts, because there are two legitimate ways to ask:
      1. from THIS file — running the CLI inside a clone
         (`python3 public_html/hivv-cli.py tests-for …`);
      2. from the CWD — running the INSTALLED CLI while cd'd into the
         clone, which is the normal developer flow: edit in the clone,
         ask `hivv` from anywhere. Without this the installed copy
         walked up from ~/.local/lib/hivv, found no repo, and refused.

    The marker is hivv-specific on purpose (`.git` + `tests/` +
    `public_html/hivv-cli.py`): a random unrelated repo the user happens
    to be standing in must never be mistaken for ours — running the wrong
    suite would report a false verdict.
    """
    def _is_hivv_repo(cand: Path) -> bool:
        return ((cand / ".git").exists()
                and (cand / "tests").is_dir()
                and (cand / "public_html" / f"{APP}-cli.py").exists())

    start = Path(__file__).resolve().parent
    for cand in [start, *start.parents]:
        if _is_hivv_repo(cand):
            return cand
    cur = Path.cwd()
    for cand in [cur, *cur.parents]:
        if _is_hivv_repo(cand):
            return cand
    return None


def cmd_speeds(args) -> None:
    """The request speed ledger — every reply ever served, with full-reply
    duration, time-to-first-token and tokens/s, per user and per answering bee.

    Source: hivv_request_provenance (operator view — localhost or
    HIVV_CONTROL_TOKEN), the same rows /api/provenance/stats aggregates.
    `hivv speed` measures ONE request live; this reads them ALL."""
    days = max(1, min(365, int(getattr(args, "days", 1) or 1)))
    limit = max(1, min(1000, int(getattr(args, "limit", 300) or 300)))
    since = datetime.fromtimestamp(time.time() - days * 86400).astimezone().isoformat(timespec="seconds")

    def _fetch(view: str | None = None):
        path = (f"/api/provenance/requests?limit={limit}"
                f"&since={urllib.parse.quote(since)}")
        if view:
            path += f"&view={view}"
        return http("GET", path, timeout=20)

    # The provenance API DEFAULTS to view=operator (correctly — the ledger
    # holds who asked and from where), so any non-hub machine got a flat
    # 403 and the command was hub-only in practice (yalla, 2026-11-20).
    # Fix: operator first (full detail where we're allowed), then the API's
    # own hinted fallback — the `partner` projection carries EVERY timing
    # field these tables need (duration, ttfb, tok/s, model, node) and no
    # identity unless a row's privacy policy allows it. "How fast is my
    # AI" works from anywhere; only the per-user breakdown stays operator.
    restricted = False
    code, p = _fetch()
    if code in (401, 403):
        code, p = _fetch("partner")
        restricted = True
    if code in (401, 403):
        die("the speed ledger refused both views (operator AND partner) —\n"
            "    run it on the hub host, or export HIVV_CONTROL_TOKEN=<hub token>")
    if code != 200 or not isinstance(p, dict):
        die(f"failed to read the speed ledger: {p}")
    view_used = str(((p.get("data") or {}).get("view"))
                    or ("partner" if restricted else "operator"))
    rows = [r for r in ((p.get("data") or {}).get("rows") or []) if isinstance(r, dict)]

    def _f(v):
        try:
            return float(v)
        except (TypeError, ValueError):
            return None

    # Numeric columns sometimes arrive as STRINGS (pg numeric → JSON), and
    # `sum(['1', '2'])` raised TypeError — `hivv speeds` crashed on its own
    # data in three places (summary, by-user, by-bee rollups). Normalise
    # ONCE here so every consumer gets numbers; coercing at each read site
    # missed the rollup and the crash came back.
    for _r in rows:
        for _k in ("duration_ms", "ttfb_ms", "tokens_per_sec"):
            if _k in _r:
                _r[_k] = _f(_r[_k])

    durs = sorted(d for d in (r.get("duration_ms") for r in rows) if d is not None)
    # non-stream rows record ttfb == duration BY DEFINITION — excluding them
    # keeps the first-token average an honest streaming measurement.
    ttfbs = sorted(r.get("ttfb_ms") for r in rows
                   if r.get("ttfb_ms") is not None and r.get("duration_ms") is not None
                   and r.get("ttfb_ms") != r.get("duration_ms"))
    tps_l = sorted(t for t in (r.get("tokens_per_sec") for r in rows) if t)

    def _pct(vals, q):
        return vals[min(len(vals) - 1, int(q * len(vals)))] if vals else None

    def _ms(v):
        v = _f(v)
        if v is None:
            return "—"
        return f"{v / 1000:.1f}s" if v >= 1000 else f"{v:.0f}ms"

    def _avg(vals, nd=0):
        return round(sum(vals) / len(vals), nd) if vals else None

    summary = {
        "window_days": days,
        "requests": len(rows),
        "avg_duration_ms": _avg(durs),
        "p50_duration_ms": _pct(durs, 0.5),
        "p95_duration_ms": _pct(durs, 0.95),
        "avg_ttfb_ms": _avg(ttfbs),
        "p95_ttfb_ms": _pct(ttfbs, 0.95),
        "avg_tokens_per_sec": _avg(tps_l, 1),
        "streams_measured": len(ttfbs),
    }

    # Per-user and per-bee rollups + transport mix
    by_who: dict = {}
    by_node: dict = {}
    transports: dict = {}
    for r in rows:
        ident = (r.get("principal") or r.get("anonymous_visitor_id")
                 or r.get("user_id"))
        who = str(r.get("principal") or r.get("anonymous_visitor_id")
                  or (f"user:{r.get('user_id')}" if r.get("user_id") else "?"))
        node = str(r.get("answered_by_node") or r.get("transport") or "?")
        tr = str(r.get("transport") or "?")
        transports[tr] = transports.get(tr, 0) + 1
        # per-user ONLY for rows that carry identity — in the partner view
        # they don't, and a table of one "?" bucket would be a lie
        buckets = ((by_node, node),) if not ident else ((by_who, who), (by_node, node))
        for bucket, key in buckets:
            g = bucket.setdefault(key, {"n": 0, "d": [], "t": []})
            g["n"] += 1
            if r.get("duration_ms") is not None:
                g["d"].append(r["duration_ms"])
            t = _f(r.get("tokens_per_sec"))
            if t:
                g["t"].append(t)

    def _rollup(bucket, top=6):
        out = []
        for key, g in sorted(bucket.items(), key=lambda kv: -kv[1]["n"])[:top]:
            out.append({"key": key, "requests": g["n"],
                        "avg_duration_ms": _avg(g["d"]),
                        "avg_tokens_per_sec": _avg(g["t"], 1)})
        return out

    summary["by_user"] = _rollup(by_who)
    summary["by_node"] = _rollup(by_node)
    summary["by_transport"] = transports

    if getattr(args, "json_output", False):
        print(json.dumps({"summary": summary, "rows": rows,
                          "view": view_used, "restricted": restricted},
                         indent=2))
        return

    print(f"\n\033[1m{APP} speeds\033[0m — request speed log (last {days}d, {len(rows)} request(s))")
    if restricted:
        print(f"  \033[2mview: {view_used} (timings only — per-user detail is "
              f"operator-only: run on the hub or export HIVV_CONTROL_TOKEN)\033[0m")
    print()
    if not rows:
        print("  no requests recorded in this window")
        print(f"  chat something first, then re-run: {APP} speeds")
        return
    print(f"  full reply   avg {_ms(summary['avg_duration_ms'])} · p50 {_ms(summary['p50_duration_ms'])}"
          f" · p95 {_ms(summary['p95_duration_ms'])}")
    if summary["avg_ttfb_ms"] is not None:
        print(f"  first token  avg {_ms(summary['avg_ttfb_ms'])} · p95 {_ms(summary['p95_ttfb_ms'])}"
              f"   ({summary['streams_measured']} streaming request(s))")
    if summary["avg_tokens_per_sec"] is not None:
        print(f"  throughput   avg {summary['avg_tokens_per_sec']} tok/s")
    mix = " · ".join(f"{n} {k}" for k, n in sorted(transports.items(), key=lambda kv: -kv[1]))
    print(f"  transport    {mix}")

    def _group_table(title, items):
        print(f"\n  {title}")
        print(f"  {'':24} {'N':>4}  {'AVG REPLY':>9}  {'AVG TOK/S':>9}")
        for g in items:
            tps = "—" if g["avg_tokens_per_sec"] is None else str(g["avg_tokens_per_sec"])
            print(f"  {g['key'][:24]:<24} {g['requests']:>4}  {_ms(g['avg_duration_ms']):>9}  {tps:>9}")

    if summary["by_user"]:
        _group_table("per user", summary["by_user"])
    elif restricted:
        print(f"\n  per user")
        print(f"  \033[2m— operator-only in this view (timings above are complete)\033[0m")
    _group_table("per answering bee", summary["by_node"])

    print(f"\n  {'TIME':<9} {'WHO':<18} {'MODEL':<22} {'NODE':<14} {'TTFB':>7} {'REPLY':>8} {'TOK/S':>6}")
    for r in rows[:12]:
        created = str(r.get("created_at") or "")[11:19] or "?"
        who = str(r.get("principal") or r.get("anonymous_visitor_id")
                  or ("—" if restricted else "?"))[:18]
        mdl = str(r.get("model") or "?").split("/")[-1].replace(".gguf", "")[:22]
        node = str(r.get("answered_by_node") or "—")[:14]
        ttfb = r.get("ttfb_ms")
        if ttfb is not None and r.get("duration_ms") == ttfb:
            ttfb_s = "n/a"     # non-stream: first byte IS the whole reply
        else:
            ttfb_s = _ms(ttfb)
        t = _f(r.get("tokens_per_sec"))
        tps = "—" if not t else f"{t:.0f}"
        print(f"  {created:<9} {who:<18} {mdl:<22} {node:<14} {ttfb_s:>7} {_ms(r.get('duration_ms')):>8} {tps:>6}")
    print(f"\n  \033[2mledger: GET /api/provenance/requests · aggregates: /api/provenance/stats\033[0m\n")

def _test_llm_core(_chk) -> None:
    """`hivv test` section: the local LLM battery — listening, config, model
    file, REAL chat round-trip (catches 400s/garbage a green 'serving' hides),
    disk, agent liveness. Reuses the same run as `hivv selftest`."""
    rep = _selftest_run()          # also persists to state → heartbeat carries it
    for c in rep.get("checks") or []:
        _chk(f"llm/{c['id']}: {c['detail']}", bool(c["ok"]))


def _test_ai_contract(_chk) -> None:
    """`hivv test` section: the AI-consumption contract — every public JSON
    surface must PARSE (pure stdout) and the hive endpoints must answer.
    This is what lets agents skip us humans entirely."""
    import argparse as _ap
    import contextlib as _cl
    import io as _io

    def _pure_json(fn, *a, **kw) -> bool:
        buf = _io.StringIO()
        with _cl.redirect_stdout(buf):
            fn(*a, **kw)
        json.loads(buf.getvalue())
        return True

    probes = [
        ("commands --json", lambda: _pure_json(
            cmd_commands, _ap.Namespace(json_output=True))),
        ("security --json", lambda: _pure_json(
            cmd_security, _ap.Namespace(json_output=True, no_report=True))),
        ("llm config --json", lambda: _pure_json(
            cmd_llm_config, _ap.Namespace(json_output=True, set=[], unset=[]))),
    ]
    for name, fn in probes:
        try:
            fn()
            _chk(f"json/{name} parses on stdout", True)
        except SystemExit:
            _chk(f"json/{name} parses on stdout", False)
        except Exception as e:
            _chk(f"json/{name} parses on stdout ({str(e)[:60]})", False)

    # hive endpoints through the REAL entrance (works off-LAN via the hub)
    for path, key in (("/api/hive/iq", "brains"), ("/api/version", "version")):
        try:
            code, body = http("GET", path, timeout=8, sign=False)
            ok = code == 200 and isinstance(body, dict) and key in body
            _chk(f"hub {path} answers ({code})", ok)
        except Exception as e:
            _chk(f"hub {path} answers ({str(e)[:50]})", False)

    # operator-surface (history/speeds): auth may be absent off-hub → advisory
    try:
        buf = _io.StringIO()
        with _cl.redirect_stdout(buf):
            cmd_history(_ap.Namespace(json_output=True, limit=5))
        json.loads(buf.getvalue())
        _chk("history --json parses (operator)", True)
    except SystemExit:
        print(f"  \033[2m· history --json: operator auth not here "
              f"(export HIVV_CONTROL_TOKEN on admin boxes)\033[0m")
    except Exception:
        _chk("history --json parses (operator)", False)


def _test_toolkit() -> int:
    """`hivv tools test` — the toolkit end to end, on THIS box.

    Returns the number of failures (0 = everything works).

    WHY THIS EXISTS
    A user ran `hivv chat "whats the date today"` and got
    "I do not have access to real-time information". The hive had a clock
    tool; the model was never offered it, because the local tool server had
    failed to download (Permission denied in a root-owned install) and the
    CLI gated the tool SCHEMAS on that server being up. Three separate
    things had to be true and nothing checked them:

      1. the HUB catalog is reachable — that is where the schemas come from,
      2. the LOCAL tool server runs — that is where the cheap tools run,
      3. a tool actually EXECUTES end to end.

    This checks all three, then the policy posture and the SSRF guard, and
    finishes with the question a human would actually ask.
    """
    import urllib.request as _ur

    fails = 0
    # `from datetime import datetime` at the top of this file means `datetime`
    # is the CLASS, not the module — datetime.date does not exist on it.
    today = datetime.now().date()

    def _chk(label, ok, detail=""):
        nonlocal fails
        tail = "  \033[2m%s\033[0m" % detail if detail else ""
        if ok:
            print("  \033[32m✓\033[0m %s%s" % (label, tail))
        else:
            fails += 1
            print("  \033[31m✗\033[0m %s  %s" % (label, detail))

    def _hub(tool, body):
        try:
            code, resp = http("POST", "/api/tools/%s/invoke" % tool, body=body, timeout=45)
            return code, (resp if isinstance(resp, dict) else {})
        except Exception as e:
            return 0, {"error": str(e)}

    # ── 1. the catalog ────────────────────────────────────────────────────
    print("\033[1m%s tools test — catalog\033[0m\n" % APP)
    cat = {}
    try:
        code, resp = http("GET", "/api/tools/catalog", timeout=10, sign=False)
        cat = resp if code == 200 and isinstance(resp, dict) else {}
    except Exception as e:
        cat = {"error": str(e)}
    if cat.get("tools"):
        _chk("hub catalog reachable", True,
             "%d tools · %d advertised" % (len(cat["tools"]), len(cat.get("advertised", []))))
        names = {t.get("name") for t in cat["tools"]}
        for must in ("calculator", "current_time", "timezone_convert", "text_parser"):
            _chk("catalog has %s" % must, must in names)
        # The posture changed 2026-11-24: the flag is ON by default now
        # (responsibly: robots.txt + per-host floor ship with it), but the
        # INVARIANT is what matters — the schema is advertised if and only
        # if the flag is on, for either configuration.
        _web_ad = "web_search" in set(cat.get("advertised") or [])
        _web_on = bool(cat.get("web_search_enabled", False))
        _chk("web search advertisement matches its flag",
             _web_ad == _web_on,
             "HIVV_ENABLE_WEB_SEARCH=1 (advertised)" if _web_on
             else "HIVV_ENABLE_WEB_SEARCH=0 (not advertised)")
    else:
        _chk("hub catalog reachable", False, str(cat.get("error", "no response")))
    print()

    # ── 2. the local tool server ──────────────────────────────────────────
    print("\033[1m%s tools test — local tool server\033[0m\n" % APP)
    local_info = {}
    try:
        with _ur.urlopen("http://127.0.0.1:%d/tools" % TOOLS_PORT, timeout=4) as r:
            local_info = json.loads(r.read())
        local_ok = True
    except Exception as e:
        local_ok = False
        local_info = {"error": str(e)}
    _chk("reachable on 127.0.0.1:%d" % TOOLS_PORT, local_ok,
         ("%d local · %d via the hub" % (len(local_info.get("local_tools", [])),
                                         len(local_info.get("hub_tools", []))))
         if local_ok else "%s — run: %s tools on" % (local_info.get("error"), APP))
    if local_ok:
        _chk("the server advertises the whole catalog",
             len(local_info.get("tools", [])) >= 12,
             "%d tools" % len(local_info.get("tools", [])))
    print()

    # ── 3. tool calls through the HUB ─────────────────────────────────────
    print("\033[1m%s tools test — tool calls (hub)\033[0m\n" % APP)
    code, resp = _hub("calculator", {"expression": "(12+8)*3/7"})
    _chk("calculator", code == 200 and resp.get("ok") and
         abs(float(resp.get("data", {}).get("result", 0)) - 60 / 7) < 1e-6,
         str(resp.get("data", {}).get("result") or resp.get("error", "")))

    code, resp = _hub("current_time", {"timezone": "Asia/Karachi"})
    d = resp.get("data") or {}
    _chk("current_time", code == 200 and resp.get("ok") and d.get("human"),
         ("%s %s %s" % (d.get("human", ""), d.get("timezone", ""), d.get("utc_offset", ""))).strip()
         or str(resp.get("error", "")))

    code, resp = _hub("timezone_convert",
                      {"timezone": "Europe/Paris", "from_timezone": "Asia/Karachi"})
    d = resp.get("data") or {}
    _chk("timezone_convert", code == 200 and resp.get("ok") and d.get("difference"),
         "%s vs %s = %s" % (d.get("local", ""), d.get("from_local", ""), d.get("difference", ""))
         if code == 200 else str(resp.get("error", "")))

    code, resp = _hub("text_parser", {"input": "name,age\nada,36"})
    d = resp.get("data") or {}
    _chk("text_parser (csv)", code == 200 and resp.get("ok") and d.get("detected_format") == "csv",
         "%s -> %s" % (d.get("detected_format"), d.get("parsed"))
         if code == 200 else str(resp.get("error", "")))
    print()

    # ── 4. tool calls on THIS box ─────────────────────────────────────────
    print("\033[1m%s tools test — tool calls (local server)\033[0m\n" % APP)
    if not local_ok:
        _chk("local tool calls", False, "the local tool server is not reachable")
    else:
        checks = [("calculator", {"expression": "6*7"}, lambda x: x.get("result") == 42),
                  ("current_time", {}, lambda x: bool(x.get("human") or x.get("iso"))),
                  ("text_parser", {"input": '{"a":1}'}, lambda x: x.get("detected_format") == "json")]
        for tool, body, pick in checks:
            try:
                req = _ur.Request("http://127.0.0.1:%d/tool/%s" % (TOOLS_PORT, tool),
                                  data=json.dumps(body).encode(), method="POST",
                                  headers={"Content-Type": "application/json"})
                with _ur.urlopen(req, timeout=30) as r:
                    out = json.loads(r.read())
                ok = out.get("ok") is True and pick(out.get("data") or {})
                detail = json.dumps(out.get("data") or out.get("error") or "")[:90]
            except Exception as e:
                ok, detail = False, str(e)
            _chk(tool, ok, detail)
    print()

    # ── 5. policy posture + the SSRF guard ────────────────────────────────
    print("\033[1m%s tools test — policy\033[0m\n" % APP)
    code, resp = _hub("web_fetch", {"url": "https://example.com"})
    if code == 202:
        _chk("web.fetch asks before it runs", True, "MAYBE grant %s" % resp.get("grant_id"))
    elif code == 200:
        rule = resp.get("policy", {}).get("rule", "?")
        _chk("web.fetch asks before it runs", True, "already approved (%s)" % rule)
    else:
        _chk("web.fetch asks before it runs", False, "HTTP %s %s" % (code, resp.get("error", "")))

    code, resp = _hub("web_fetch", {"url": "http://127.0.0.1:3011/api/health"})
    if code == 200 and not resp.get("ok"):
        _chk("SSRF guard refuses an internal address", "private" in str(resp.get("error", "")),
             str(resp.get("error", ""))[:70])
    elif code == 202:
        _chk("SSRF guard refuses an internal address", True, "gated first (MAYBE)")
    else:
        _chk("SSRF guard refuses an internal address", False, "HTTP %s" % code)
    print()

    # ── 6. the question a human would actually ask ────────────────────────
    print("\033[1m%s tools test — does a MODEL use them?\033[0m\n" % APP)
    schemas = [s for s in _tool_schemas()
               if s.get("function", {}).get("name") == "current_time"]
    if not schemas:
        _chk("the current_time schema is offerable", False, "not in the catalog?")
    else:
        try:
            code, resp = http("POST", "/api/chat", body={
                "message": "What is today's date? Use the current_time tool.",
                "stream": False,
                "tools": schemas,
            }, timeout=180)
            answer = ""
            if code == 200 and isinstance(resp, dict):
                answer = ((resp.get("choices") or [{}])[0]
                          .get("message", {}).get("content") or "")
            _chk("a model called the tool and answered with a real date",
                 bool(answer) and str(today.year) in answer,
                 (answer.strip().replace("\n", " ")[:80] or "HTTP %s" % code))
        except Exception as e:
            _chk("a model called the tool and answered with a real date", False, str(e))
    print()

    if fails:
        print("  \033[31m%d failed\033[0m" % fails)
        print("  → local server: %s tools on   ·   catalog: %s tools list" % (APP, APP))
        print('  → the model itself: %s chat "whats the date today"' % APP)
    else:
        print("  \033[32mall green — every tool answered\033[0m")
    return fails


def cmd_test(args) -> None:
    """End-to-end smoke test: doctor + speed + LLM core (real round-trip) +
    AI/JSON contract + network + chat with all nodes + the toolkit.

    Scope (hivv test [all|everything|tools]):
      all / everything -> the whole suite - the default, and what "hivv test"
                          has always meant
      tools            -> JUST the toolkit: the hub catalog, the local tool
                          server, real tool calls both ways, the policy
                          posture, the SSRF guard - and finally a MODEL
                          actually using one

    Exit code = THIS box's core health (llm + json contract + hub endpoints);
    per-node reach stays advisory (a bee off your LAN is not your failure)."""
    scope = str(getattr(args, "scope", None) or "all").strip().lower()
    if scope in ("everything", "all"):
        scope = "all"

    if scope == "tools":
        print(f"\033[1m{APP} test tools\033[0m — the toolkit end to end\n")
        sys.exit(1 if _test_toolkit() else 0)

    print(f"\033[1m{APP} test\033[0m — full end-to-end smoke test\n")
    fails: list = []

    def _chk(label: str, ok: bool) -> None:
        if ok:
            print(f"  \033[32m✓\033[0m {label}")
        else:
            fails.append(label)
            print(f"  \033[31m✗\033[0m {label}")

    cmd_doctor(args)
    print()
    cmd_speed(args)
    print()

    # Local LLM battery — config/slots/REAL round-trip/disk/agent
    print(f"\033[1m{APP} test — llm core\033[0m\n")
    _test_llm_core(_chk)
    print()

    # AI contract: pure-JSON outputs + hub endpoints (agents need these)
    print(f"\033[1m{APP} test — AI contract\033[0m\n")
    _test_ai_contract(_chk)
    print()

    # Network-wide test
    print(f"\033[1m{APP} test — network\033[0m\n")
    import subprocess as _sp
    _r = lambda c: _sp.run(c, shell=True, capture_output=True, text=True, timeout=10)

    # Get all nodes
    code, p = http("GET", "/api/control/nodes")
    if code != 200 or not isinstance(p, dict):
        print(f"  could not fetch nodes")
    else:
        nodes = p.get("nodes", [])
        if not nodes:
            print(f"  no nodes registered — start agents with: {APP} start")
        else:
            # Off-LAN? All private-IP peers unreachable → we're on a different
            # network (NOT a firewall issue). Direct probes can never work from
            # here: skip them honestly and test the AI through the HUB path —
            # exactly how remote users get their chat (you → hub → bee LAN-side).
            _priv = [n for n in nodes
                     if n.get("lan_ip") and re.match(
                         r"^(192\.168\.|10\.|172\.(1[6-9]|2[0-9]|3[01])\.)", n["lan_ip"])]
            off_lan = False
            if _priv:
                _pi = _priv[0].get("lan_ip")
                _pp = 8080
                for m in (_priv[0].get("local_models") or []):
                    _pp = m.get("port", 8080)
                    break
                _pr = _r(f"curl -s --connect-timeout 2 --max-time 3 http://{_pi}:{_pp}/v1/models 2>/dev/null")
                if not (_pr.stdout and "model" in _pr.stdout.lower()):
                    off_lan = True
            if off_lan:
                print(f"  \033[2m· scanned from OFF-LAN — private-IP peers are unreachable from here by")
                print(f"     design (not a firewall problem). Direct probes are skipped; the AI is")
                print(f"     tested through the HUB path — how every remote user gets chat.")
                print(f"     Same-LAN direct reach for everyone: one tailnet, then")
                print(f"     `{APP} firewall --apply --mode tailscale` on every bee + this box.\033[0m\n")

            # ── SELF detection ───────────────────────────────────────────
            # Probing OURSELVES via our own LAN IP measures the BIND, not
            # the service: a localhost-bound LLM is perfectly up here but
            # refuses our own LAN address, so the old code printed
            # "yalla: ✗ chat failed" while run ON yalla — seconds after
            # llm-core proved 8080 answers 'OK'. Self-probes use loopback;
            # the LAN probe for self is kept separately because it answers
            # the REAL question: "can the others borrow my model?"
            _self_id = (read_state() or {}).get("node_id") or ""

            def _is_self(n: dict) -> bool:
                return bool(_self_id) and n.get("id") == _self_id

            # Test each node
            for n in nodes:
                name = n.get("name", n.get("id", "?"))
                ip = n.get("lan_ip") or n.get("ip", "")
                status = n.get("status", "?")
                models = n.get("local_models", [])

                if status != "online":
                    print(f"  {name}: \033[31m{status}\033[0m — skipping")
                    continue

                self_node = _is_self(n)
                probe_ip = "127.0.0.1" if self_node else ip

                # Test connectivity to each LLM port
                ports_ok = 0
                ports_total = 0
                lan_ok = 0
                for m in models:
                    if off_lan:
                        break
                    port = m.get("port", 8080)
                    ports_total += 1
                    try:
                        r = _r(f"curl -s --connect-timeout 2 --max-time 3 http://{probe_ip}:{port}/v1/models 2>/dev/null")
                        if r.stdout and "model" in r.stdout.lower():
                            ports_ok += 1
                    except:
                        pass
                    # self: also ask the LAN address — that is the "shared?" bit
                    if self_node and ip and ip not in ("127.0.0.1", probe_ip):
                        try:
                            r2 = _r(f"curl -s --connect-timeout 2 --max-time 3 http://{ip}:{port}/v1/models 2>/dev/null")
                            if r2.stdout and "model" in r2.stdout.lower():
                                lan_ok += 1
                        except:
                            pass

                if off_lan:
                    print(f"  {name}: \033[2m⊘ direct probe skipped (off-LAN — private {ip})\033[0m")
                elif ports_total == 0:
                    print(f"  {name}: \033[33mno models\033[0m")
                elif self_node:
                    if ports_ok == ports_total and lan_ok == ports_total:
                        print(f"  {name}: \033[32m✓ {ports_ok}/{ports_total} ports reachable\033[0m ({ip})")
                    elif ports_ok:
                        print(f"  {name}: \033[33m{ports_ok}/{ports_total} up on localhost — NOT shared "
                              f"(binds 127.0.0.1)\033[0m ({ip})")
                        print(f"     \033[2mpeers can't borrow your model — fix: {APP} doctor --fix\033[0m")
                    else:
                        print(f"  {name}: \033[31m✗ no answer on localhost either (:{ports_total and models[0].get('port', 8080) or 8080})\033[0m")
                elif ports_ok == ports_total:
                    print(f"  {name}: \033[32m✓ {ports_ok}/{ports_total} ports reachable\033[0m ({ip})")
                else:
                    print(f"  {name}: \033[33m{ports_ok}/{ports_total} ports reachable\033[0m ({ip})")
                    if models:
                        print(f"     \033[2mnot directly reachable — its LLM likely binds localhost "
                              f"(or a firewall blocks); on THAT bee: {APP} doctor --fix\033[0m")

            # Test chat with each online node
            print(f"\n\033[1mchat test\033[0m")
            if off_lan:
                print(f"  \033[2m(via hub — the remote-user path)\033[0m")
                try:
                    _c2, _b2 = http("POST", "/api/chat",
                                    body={"message": "say hi in two words"}, timeout=30)
                    _t2 = _b2 if isinstance(_b2, str) else json.dumps(_b2)
                    _ok2 = _c2 == 200 and ('"choices"' in _t2 or '"content"' in _t2)
                    print(f"  hub-mediated chat: " +
                          ("\033[32m✓ answered — remote users get AI this way\033[0m" if _ok2
                           else f"\033[31m✗ HTTP {_c2}\033[0m"))
                except Exception as _e2:
                    print(f"  hub-mediated chat: \033[31m✗ {str(_e2)[:70]}\033[0m")
                print(f"  \033[2m· per-node direct chat skipped (off-LAN)\033[0m")
            for n in nodes:
                if off_lan:
                    continue
                if n.get("status") != "online":
                    continue
                name = n.get("name", n.get("id", "?"))
                ip = n.get("lan_ip") or n.get("ip", "")
                models = n.get("local_models", [])
                if not models or (not ip and not _is_self(n)):
                    continue
                self_node = _is_self(n)
                direct_host = "127.0.0.1" if self_node else ip

                # 1. DIRECT — what the router's borrowing path uses.
                answered = False
                for m in models:
                    port = m.get("port", 8080)
                    try:
                        url = f"http://{direct_host}:{port}/v1/chat/completions"
                        payload = json.dumps({"model": _real_model(url), "messages": [{"role": "user", "content": "say hi"}], "max_tokens": 20})
                        import urllib.request
                        req = urllib.request.Request(url, data=payload.encode(), headers={"Content-Type": "application/json"})
                        with urllib.request.urlopen(req, timeout=10) as resp:
                            data = resp.read().decode()
                            if "content" in data:
                                where = " via localhost" if self_node else ""
                                print(f"  {name}: \033[32m✓ chat works\033[0m (:{port}{where})")
                                answered = True
                                break
                            else:
                                print(f"  {name}: \033[33m!\033[0m responded but no content (:{port})")
                                answered = True
                                break
                    except Exception:
                        continue
                if answered:
                    continue

                # 2. SELF, direct failed → nothing else to try: the relay's
                #    target IS this box's loopback, so it would fail the same
                #    way. Report the real problem instead.
                if self_node:
                    print(f"  {name}: \033[31m✗ chat failed\033[0m (even on localhost — "
                          f"is the LLM up? {APP} llm status)")
                    continue

                # 3. RELAY — reaches a bee whose model binds localhost only:
                #    hub → bee's inbox → its own agent → 127.0.0.1. This is
                #    the same path `hivv ask` uses, so "chat failed" here used
                #    to be a lie for exactly the bees the direct path can
                #    never reach (ashy:8090, yalla:8080).
                status_r, text_r = _relay_chat_to_bee(n.get("id", ""),
                                                       "say hi in two words",
                                                       timeout=80)
                if status_r == "ok":
                    print(f"  {name}: \033[32m✓ chat works\033[0m \033[2m(via relay — its model "
                          f"binds localhost, so peers can't BORROW it directly)\033[0m")
                else:
                    print(f"  {name}: \033[31m✗ chat failed\033[0m \033[2m(direct + relay: "
                          f"{str(text_r)[:60]})\033[0m")

    # The toolkit — the thing a model reaches for. Its own section: a failing
    # tool is the most common "the AI said it can't do that" report.
    print()
    _tool_fails = _test_toolkit()
    if _tool_fails:
        fails.append("toolkit (%d check(s))" % _tool_fails)
    print()
    if fails:
        print(f"\n  \033[31m{len(fails)} core check(s) FAILED:\033[0m")
        for f_ in fails:
            print(f"    ✗ {f_}")
        print(f"\n\033[1m{APP} test\033[0m — \033[31mFAILED here\033[0m "
              f"\033[2m(network lines above stay advisory)\033[0m")
        sys.exit(1)
    print(f"\n\033[1m{APP} test\033[0m — \033[32mcomplete — all core checks green\033[0m")


# ── friendly / fun commands ────────────────────────────────────────────
_VOLUNTEER_FILE = CONFIG_DIR / "contribute.json"

def _volunteer_default() -> dict:
    # DEFAULT ON (operator decision, 2026-11-18): the cross-NAT relay path is
    # dead out of the box while every bee defaults to OFF. Consent stays real:
    # `hivv volunteer off` writes an explicit False that this loader honors,
    # and status shows "(default)" until someone runs `volunteer on`.
    return {"share_cpu": True, "max_cpu_pct": 25, "pause_on_battery": True,
            "sandbox": "subprocess", "opted_in_at": None, "tags": []}

def _volunteer_load() -> dict:
    if not _VOLUNTEER_FILE.exists():
        return _volunteer_default()
    try:
        d = json.loads(_VOLUNTEER_FILE.read_text())
        # backfill any new keys
        base = _volunteer_default()
        base.update({k: v for k, v in d.items() if k in base})
        return base
    except (OSError, json.JSONDecodeError):
        return _volunteer_default()

def cmd_drone(args) -> None:
    """Show volunteer (drone) status — alias for 'volunteer status'."""
    class _FakeArgs:
        pass
    fake = _FakeArgs()
    fake.action = "status"
    cmd_volunteer(fake)


def cmd_volunteer(args) -> None:
    """Opt in/out of contributing compute to the network.
    Sets ~/.config/hivv/contribute.json. The agent reads this on next start."""
    action = getattr(args, "action", None) or "status"
    # THE CENTRAL NORMALIZER REWRITES "on"/"off" → "yes"/"no" (it exists so
    # every command can accept on/off/yes/no). That made `hivv volunteer on`
    # and `hivv volunteer off` DEAD — they always fell through to "status",
    # so the toggle never actually toggled. Accept both vocabularies.
    action = {"yes": "on", "no": "off", "true": "on", "false": "off",
              "enable": "on", "disable": "off"}.get(str(action).lower(), action)
    ensure_dirs()
    cfg = _volunteer_load()

    if action == "on":
        cfg["share_cpu"] = True
        cfg["opted_in_at"] = int(time.time())
        _VOLUNTEER_FILE.write_text(json.dumps(cfg, indent=2))
        print(f"\033[1;32m{APP} volunteer\033[0m — \033[32m✓ you're now a volunteer bee!\033[0m\n")
        print(f"When {HUB_NAME} has a chat request that fits your box, your bee will help.")
        print(f"You can leave the volunteer corps anytime with \033[1m{APP} volunteer off\033[0m.\n")
        print("\033[1m⚡ what you just gained\033[0m")
        print("  a volunteering bee gives the network a share of your machine and gets")
        print("  a share back — you are paid in honey points and kept warm:")
        print()
        print("    \033[1mCPU\033[0m        half your cores stay reserved for the network (yours stay yours)")
        print("    \033[1mMemory\033[0m    half your RAM stays available to peers")
        print("    \033[1mDisk\033[0m      half your storage stays available for models and jobs")
        print("    \033[1mNetwork\033[0m   half your bandwidth is shared with the hive")
        print("    \033[1mHoney\033[0m     you earn double the honey points of a non-volunteer")
        print()
        print("    \033[1mHive access\033[0m \033[1;32mFULL\033[0m — your box is reachable by the whole network:")
        print("                     anyone on hivv.org can send it work, and it can answer them.")
        print("                     (A non-volunteer is firewalled off from the hive's job pool.)")
        print()
        print("  \033[1;33m→\033[0m opting out later gives all of that back to you — it is not a trap.")
        print()
        print(f"settings (in {_VOLUNTEER_FILE}):")
        for k, v in cfg.items():
            if k == "opted_in_at" and v: v = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(v))
            print(f"  {k:18s} {v}")
        # poke the user to (re)start the agent so it picks up the new flag
        pid = read_pid()
        if pid and pid_alive(pid):
            print(f"\n\033[1;33m!\033[0m agent is already running (pid {pid}); restart it to pick up the new setting:")
            print(f"  {APP} restart")
        else:
            print(f"\n\033[1;34m>\033[0m start your bee to begin contributing:")
            print(f"  {APP} start")
        return

    if action == "off":
        cfg["share_cpu"] = False
        cfg["opted_in_at"] = None
        _VOLUNTEER_FILE.write_text(json.dumps(cfg, indent=2))
        print(f"\033[1;32m{APP} volunteer\033[0m — \033[33m✓ thanks for the help — you've left the volunteer corps.\033[0m")
        print(f"Your bee will no longer accept work from {HUB_NAME}.")
        print(f"Run \033[1m{APP} volunteer on\033[0m to rejoin anytime.")
        # ── What opting out actually costs ─────────────────────────────
        # Leaving is allowed, but it is NOT free. Say what is lost BEFORE
        # the user notices the difference — a bee that has opted out gets
        # half the CPU, half the memory, half the disk and half the network
        # bandwidth reserved for the network, and earns half the honey.
        # Saying this only AFTER they opted out is how people end up
        # wondering why their box got slower.
        print()
        print("\033[1m⚡ what you just gave up\033[0m")
        print("  a volunteering bee gives the network a share of your machine and")
        print("  gets a share back. Opting out means you keep more for yourself:")
        print()
        print("    \033[1mCPU\033[0m        half of your cores stay reserved for the network → yours")
        print("    \033[1mMemory\033[0m    half your RAM stays available to peers → yours")
        print("    \033[1mDisk\033[0m      half your storage stays available for models/jobs → yours")
        print("    \033[1mNetwork\033[0m   half your bandwidth stays shared with the hive → yours")
        print("    \033[1mHoney\033[0m     you earn half the honey points of an active volunteer")
        print("    \033[1mHive access\033[0m \033[1;31mREDUCED\033[0m — the network can no longer send you work:")
        print("                     your bee steps out of the hive's job pool and stops")
        print("                     answering requests from other bees.")
        print()
        print(f"  \033[1;33m→\033[0m your machine will be faster and quieter, and the network gets less of it.")
        print(f"  \033[1;33m→\033[0m \033[1m{APP} volunteer on\033[0m reverses this in one command, any time.")
        print("  \033[1;33m→\033[0m the hive is stronger with you in it. Nothing is lost forever.")
        print()
        pid = read_pid()
        if pid and pid_alive(pid):
            print(f"\n\033[1;33m!\033[0m restart the agent to stop accepting work immediately:")
            print(f"  {APP} restart")
        return

    # status (default)
    print(f"\033[1m{APP} volunteer\033[0m — status")
    if cfg.get("share_cpu"):
        since = cfg.get("opted_in_at")
        since_str = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(since)) if since else "default (not yet explicit)"
        print(f"  state:    \033[1;32m✓ volunteering\033[0m  (since {since_str})")
        print(f"  hive:     \033[1;32mfull access\033[0m  \033[2m— the network can send this box work\033[0m")
    else:
        print(f"  state:    \033[2mnot volunteering\033[0m  (explicitly off)")
        print(f"  hive:     \033[1;31mreduced\033[0m      \033[2m— this box is out of the hive's job pool\033[0m")
    print(f"  config:   {_VOLUNTEER_FILE}")
    for k, v in cfg.items():
        if k == "opted_in_at":
            v = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(v)) if v else "(never)"
        print(f"    {k:18s} {v}")
    if not cfg.get("share_cpu"):
        print(f"\n  to join:   \033[1m{APP} volunteer on\033[0m")
        print(f"  \033[2m(you keep half your CPU, RAM, disk and bandwidth to yourself;\033[0m")
        print(f"  \033[2m a volunteer shares half of each, earns double the honey, and gets\033[0m")
        print(f"  \033[2m FULL access to the hivv.org network — the hive can send this box work)\033[0m")
    else:
        print(f"\n  to leave:  \033[1m{APP} volunteer off\033[0m  (relay jobs are ON by default)")
        print(f"  \033[2m(half your CPU, RAM, disk and bandwidth are shared with the hive;\033[0m")
        print(f"  you earn double the honey and have full hive access while you do)\033[0m")


def cmd_share(args) -> None:
    """Broadcast what you're working on to the hivv network.
    Usage: hivv share "working on climate models" [--problem=abc123] [--card]
    """
    st = read_state()
    node_id = st.get("node_id")
    if not node_id:
        print(f"\033[1;33m!\033[0m your bee isn't registered yet — start it first:")
        print(f"  \033[1m{APP} start\033[0m  then try \033[1m{APP} share\033[0m again")
        return

    # ── --card: generate a shareable bee card (#6) ───────────────────
    if getattr(args, "card", False):
        import urllib.request as _ur
        url = f"{HUB.rstrip('/')}/api/hive/share-card/{node_id}.svg"
        out = Path.cwd() / f"hivv-bee-card-{node_id}.svg"
        try:
            req = _ur.Request(url, headers={"user-agent": f"{APP}/{VERSION}"})
            with _ur.urlopen(req, timeout=15) as r:
                out.write_bytes(r.read())
            print(f"\033[1;32m✓\033[0m bee card saved → \033[1m{out}\033[0m")
            print(f"\n  copy-paste-ready post:")
            print(f"  \033[36m🐝 I gave my idle computer to hivv.org — the people's distributed AI")
            print(f"  network. 5 minutes to join: curl -sSL https://hivv.org/install-hivv.sh | bash\033[0m\n")
            print(f"  \033[2m(view the card: open the .svg in any browser; PNG export: screenshot or rsvg-convert)\033[0m")
        except Exception as e:
            die(f"couldn't fetch share card: {e}")
        return

    msg = getattr(args, "message", None) or ""
    problem_id = getattr(args, "problem", None)

    if not msg:
        print(f"\033[1m{APP} share\033[0m — broadcast what you're working on to the hive\n")
        print(f"  \033[1m{APP} share \"<message>\"\033[0m           tell the hive what you're doing")
        print(f"  \033[1m{APP} share \"fixing bug\" --problem=123\033[0m  link to a problem ID")
        print(f"  \033[1m{APP} share --clear\033[0m                  clear your work status")
        print(f"  \033[1m{APP} feed\033[0m                       see what others are working on\n")
        return

    if getattr(args, "clear", False):
        msg = ""
        problem_id = None

    if msg and len(msg) > 280:
        print(f"\033[1;31m!\033[0m message too long (max 280 chars, got {len(msg)})")
        return

    body = {"work_status": msg}
    if problem_id:
        body["problem_id"] = problem_id

    code, payload = http("POST", f"/api/nodes/{node_id}/work-status", body=body, timeout=10)
    if code == 200:
        print(f"\033[1;32m✓\033[0m work status updated — the hive now knows what you're doing 🐝")
        if msg:
            print(f"  \033[2m\"{msg[:80]}{'...' if len(msg) > 80 else ''}\"\033[0m")
    else:
        print(f"\033[1;31m!\033[0m failed (HTTP {code}): {payload}")


# ── bee identity: honey, ranks, streaks (HIVV_PLAN #1) ────────────────
_RANKS = [
    (0,       "larva",      "just hatched — say hi: hivv hi"),
    (500,     "worker",     "warming up — you're officially part of the hive"),
    (5_000,   "forager",    "out gathering knowledge"),
    (25_000,  "scout",      "a trusted pathfinder"),
    (100_000, "royal-jelly","rare and precious to the hive"),
    (500_000, "queen-bee",  "sovereign of the swarm 👑"),
]

def _rank_progress(honey: int):
    cur, nxt = _RANKS[0], None
    for threshold, name, _ in _RANKS:
        if honey >= threshold:
            cur = (threshold, name, _)
        else:
            nxt = (threshold, name, _)
            break
    return cur, nxt

def _rank_idx(name: str) -> int:
    order = [n for _, n, _ in _RANKS]
    try:
        return order.index(name)
    except ValueError:
        return 0

def _celebrate_rank_up() -> None:
    """HIVV_PLAN #1.4: notice rank changes and celebrate them once.
    Best-effort — silently skips when the hub or state is unavailable."""
    try:
        st = read_state() or {}
        nid = st.get("node_id")
        if not nid:
            return
        code, p = http("GET", f"/api/hive/honey/{nid}", timeout=4)
        if code != 200 or not isinstance(p, dict):
            return
        rank = p.get("rank") or "larva"
        last = st.get("_last_rank")
        st["_last_rank"] = rank
        write_state(st)
        if last and _rank_idx(rank) > _rank_idx(last):
            motto = next((m for _, n, m in _RANKS if n == rank), "")
            print(f"\n\033[33m⬆⬆⬆  \033[1mRANK UP!  {last} → {rank}\033[0m\033[33m  ⬆⬆⬆\033[0m")
            print(f"   🍯 {int(p.get('honey', 0)):,} honey · \033[2m{motto}\033[0m")
            print(f"   \033[2mthe hive noticed you — celebrate: {APP} share --card\033[0m\n")
    except Exception:
        pass

def cmd_honey(args) -> None:
    """Your bee card: honey, rank, streak, leaderboard. (hivv honey [--board])"""
    if getattr(args, "board", False) or getattr(args, "node", None) == "board":
        window = getattr(args, "window", None) or "week"
        code, p = http("GET", f"/api/hive/leaderboard?window={window}&limit=12", timeout=10)
        if code != 200:
            die(f"couldn't fetch leaderboard: {p}")
        bees = p.get("bees", []) if isinstance(p, dict) else []
        print(f"\n\033[1m🏆 hive leaderboard\033[0m — window: {window}\n")
        if not bees:
            print(f"  \033[2mno honey minted yet — be the first bee: hivv start\033[0m\n")
            return
        print(f"  {'#':<3}{'BEE':<22}{'HONEY':>10}  {'RANK':<14}{'STREAK':>7}")
        print(f"  {'─'*3}{'─'*22}{'─'*10}  {'─'*14}{'─'*7}")
        my_node = (read_state() or {}).get("node_id")
        for i, b in enumerate(bees, 1):
            mark = " \033[32m← you\033[0m" if b.get("node_id") == my_node else ""
            print(f"  {i:<3}{str(b.get('node_id','?'))[:22]:<22}{int(b.get('honey',0)):>10}  "
                  f"{str(b.get('bee_rank') or b.get('rank') or '-'):<14}{int(b.get('streak_days') or 0):>5}d{mark}")
        print()
        return

    node = getattr(args, "node", None) or (read_state() or {}).get("node_id")
    if not node:
        print(f"\033[1;33m!\033[0m no node yet — run \033[1m{APP} start\033[0m first, then \033[1m{APP} honey\033[0m")
        return
    code, p = http("GET", f"/api/hive/honey/{node}", timeout=10)
    if code == 404:
        print(f"\n  🐝 \033[1m{node}\033[0m — the hive just met you. honey starts flowing within a minute.\n")
        return
    if code != 200:
        die(f"couldn't fetch your honey: {p}")
    honey = int(p.get("honey", 0))
    rank = p.get("rank", "larva")
    cur, nxt = _rank_progress(honey)
    bar = ""
    if nxt:
        lo, hi = cur[0], nxt[0]
        pct = min(100, max(0, int((honey - lo) / max(1, hi - lo) * 100)))
        filled = pct // 4
        bar = f"\n  \033[33m{'⬣' * filled}{'○' * (25 - filled)}\033[0m {pct}% → \033[1m{nxt[1]}\033[0m at {hi:,} honey"
    else:
        bar = "\n  \033[33m⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣⬣\033[0m max rank — the hive salutes you 👑"
    motto = next((m for _, n, m in _RANKS if n == rank), "")
    print(f"""
\033[1m  🐝 bee card — {node}\033[0m
  rank:    \033[33m{rank}\033[0m  (\033[2m{motto}\033[0m)
  honey:   \033[1m{honey:,}\033[0m total · {int(p.get('week_honey', 0)):,} this week · {int(p.get('month_honey', 0)):,} this month{bar}
  streak:  \033[1m{int(p.get('streak_days', 0))}\033[0m days online (\033[2mbest: {int(p.get('best_streak_days', 0))}\033[0m)
  service: {int(p.get('jobs_completed', 0)):,} jobs · {int(p.get('tokens_served', 0) or 0):,} tokens · {int(p.get('minutes_online', 0)) // 60:,}h online
  position: \033[1m#{p.get('position', '?')}\033[0m of the hive
\033[2m  hivv honey --board          see the leaderboard
   hivv share --card           generate a shareable bee card\033[0m
""")

def cmd_tips(args) -> None:
    """Show tip analytics — which tips are shown most and which drive action."""
    code, p = http("GET", "/api/tips", timeout=10)
    if code != 200:
        die(f"couldn't fetch tips: {p}")
    tips = p.get("tips", []) if isinstance(p, dict) else []
    tot = p.get("totals", {}) if isinstance(p, dict) else {}
    print(f"\033[1m  Tip Analytics\033[0m  (total shown: {tot.get('shown',0)} · clicked: {tot.get('click',0)})")
    print()
    if not tips:
        print("  \033[2m(no tip data yet — tips are shown when errors occur)\033[0m")
        return
    # Sort by shown_count desc
    tips.sort(key=lambda t: t.get("shown_count", 0), reverse=True)
    for t in tips:
        shown = int(t.get("shown_count") or 0)
        clicked = int(t.get("click_count") or 0)
        ctr = t.get("ctr") or 0
        ctr_str = f"\033[2m ({ctr}% CTR)\033[0m" if shown > 0 and clicked > 0 else ""
        bar_len = min(int(shown / max(1, tips[0].get("shown_count") or 1) * 20), 20) if shown > 0 else 0
        bar = "\033[33m" + "\u2588" * bar_len + "\033[0m" + "\u2591" * (20 - bar_len)
        last = t.get("last_shown", "")
        age = ""
        if last:
            try:
                from datetime import datetime
                ts = datetime.fromisoformat(last.replace("Z", "+00:00"))
                age = f" \033[2m(last: {ts.strftime('%m-%d')})\033[0m"
            except Exception:
                pass
        print(f"  {bar}  shown={shown}  clicked={clicked}{ctr_str}{age}")
        text = (t.get("tip_text") or "")[:70]
        print(f"    \033[36m{text}\033[0m")
    print()


# ── hive-mind: one question, many brains (HIVV_PLAN #2) ───────────────
def _model_family(model: str) -> str:
    m = (model or "").lower()
    for fam in ("llama", "gemma", "qwen", "mistral", "mixtral", "phi", "command",
                "yi", "deepseek", "gpt", "claude", "gemini", "moonshot", "ernie"):
        if fam in m:
            return fam
    return m.split("-")[0].split(":")[0][:10] or "other"

def _short_model(m: str) -> str:
    m = str(m or "local")
    if "/" in m:
        m = m.rstrip("/").split("/")[-1]
    return m.replace(".gguf", "").replace(".GGUF", "")[-40:]

def cmd_hive_mind(args) -> None:
    """Ask several different bees at once and compare their minds.
    Usage: hivv hive-mind "why is the sky red sometimes?" [--max 4] [--json] [--quiet]
    """
    import threading
    do_json = bool(getattr(args, "json", False))
    do_quiet = bool(getattr(args, "quiet", False))

    question = " ".join(args.question) if isinstance(args.question, list) else (args.question or "")
    if not question:
        question = input("  ask the hive-mind: ").strip()
    if not question:
        die("nothing asked — try: hivv hive-mind \"what should we solve together?\"")
    n_max = max(2, min(int(getattr(args, "max", 4) or 4), 6))

    code, payload = http("GET", "/api/control/nodes", timeout=8)
    if code != 200:
        die(f"can't reach the hub: {payload}")
    nodes = payload.get("nodes", []) if isinstance(payload, dict) else []
    online = [n for n in nodes if n.get("status") == "online" and (n.get("lan_ip") or n.get("ip"))]
    picked, families = [], set()
    for n in online:
        for m in (n.get("local_models") or []):
            fam = _model_family(m.get("name") or m.get("model") or "")
            if fam in families:
                continue
            ip = n.get("lan_ip") or n.get("ip")
            port = m.get("port", 8080)
            picked.append({"node": n.get("name") or n.get("id"), "model": m.get("name") or m.get("model") or "local",
                           "url": f"http://{ip}:{port}/v1/chat/completions", "family": fam})
            families.add(fam)
            break
        if len(picked) >= n_max:
            break
    if len(picked) < 2:
        print(f"\033[1;33m!\033[0m only {len(picked)} distinct brain(s) reachable — hive-mind needs 2+.")
        print(f"  \033[2mask a friend to join: curl -sSL https://hivv.org/install-hivv.sh | bash\033[0m")
        if picked:
            print(f"  \033[1mrunning it solo:\033[0m")
            args.question = question
            return _do_chat(question, stream=True)
        return

    if not do_json and not do_quiet:
        print(f"\n\033[1m🧠 hive-mind\033[0m — asking {len(picked)} different brains…\n")
    results = [None] * len(picked)

    def _ask(i, t):
        t0 = time.time()
        try:
            body = json.dumps({"model": _real_model(t["url"]), "messages": [{"role": "user", "content": question}],
                               "max_tokens": 300, "stream": False}).encode()
            req = urllib.request.Request(t["url"], data=body,
                                         headers={"Content-Type": "application/json"})
            with urllib.request.urlopen(req, timeout=40) as r:
                data = json.loads(r.read().decode("utf-8", errors="replace"))
            content = (data.get("choices") or [{}])[0].get("message", {}).get("content", "").strip()
            ms = int((time.time() - t0) * 1000)
            results[i] = {**t, "answer": content, "ms": ms,
                          "tok": max(1, len(content) // 4), "err": None}
        except Exception as e:
            results[i] = {**t, "answer": "", "ms": int((time.time() - t0) * 1000), "tok": 0, "err": str(e)[:60]}

    threads = [threading.Thread(target=_ask, args=(i, t)) for i, t in enumerate(picked)]
    for t in threads: t.start()
    for t in threads: t.join(timeout=45)

    fastest, answers, json_answers = None, [], []
    total_tokens = 0
    total_latency_ms = 0
    for i, t in enumerate(picked):
        r = results[i]
        status_str = "error"
        if r is None:
            if not do_json: print(f"  \033[2m✗ {t['node']} ({t['model']}) — timed out\033[0m")
            json_answers.append({"node": t["node"], "model": t["model"], "answer": "", "ms": 0, "tok": 0, "status": "timeout"})
            continue
        if r["err"]:
            if not do_json: print(f"  \033[31m✗ {t['node']} ({t['model']})\033[0m — {r['err']}")
            json_answers.append({"node": t["node"], "model": t["model"], "answer": "", "ms": r["ms"], "tok": 0, "status": "error", "error": r["err"]})
            continue
        status_str = "ok"
        total_tokens += r["tok"]
        total_latency_ms += r["ms"]
        if fastest is None or r["ms"] < fastest["ms"]:
            fastest = r
        if not do_quiet:
            if not do_json:
                print(f"  \033[32m● {t['node']}\033[0m \033[2m· {_short_model(t['model'])} · {r['ms']}ms · ~{max(1, r['tok']*1000//max(1,r['ms']))} t/s\033[0m")
                for line in r["answer"].splitlines()[:12]:
                    print(f"    {line}")
                if len(r["answer"].splitlines()) > 12:
                    print("    \033[2m…\033[0m")
        answers.append(f"[{t['node']} / {t['model']}]: {r['answer'][:400]}")
        json_answers.append({"node": t["node"], "model": t["model"], "answer": r["answer"], "ms": r["ms"], "tok": r["tok"], "status": "ok"})

    verdict = None
    if len(answers) >= 2:
        judge = (f"Question: {question}\n\n"
                 f"Different AI models answered:\n\n" + "\n\n".join(answers) +
                 "\n\nIn 2 short lines: where do they AGREE, and what is the single best merged answer?")
        if not do_json and not do_quiet:
            print(f"\n  \033[33m🐝 bee judge synthesis\033[0m \033[2m(fastest node: {fastest['node']})\033[0m")
        try:
            body = json.dumps({"model": _real_model(fastest["url"]),
                               "messages": [{"role": "user", "content": judge}],
                               "max_tokens": 150, "stream": False}).encode()
            req = urllib.request.Request(fastest["url"], data=body,
                                         headers={"Content-Type": "application/json"})
            with urllib.request.urlopen(req, timeout=40) as r:
                data = json.loads(r.read().decode("utf-8", errors="replace"))
            verdict = (data.get("choices") or [{}])[0].get("message", {}).get("content", "").strip()
            total_latency_ms += 0  # judge latency not counted in tok estimate
            if not do_json:
                for line in verdict.splitlines():
                    print(f"    \033[1m{line}\033[0m")
        except Exception as e:
            if not do_json: print(f"    \033[2mjudge unavailable: {e}\033[0m")
            if do_json: verdict = f"(judge unavailable: {e})"

    # Report usage to hub (fire-and-forget)
    try:
        body = json.dumps({
            "feature": "hive-mind",
            "model": ",".join(sorted(set(a["model"] for a in json_answers))) or "unknown",
            "total_tokens": total_tokens,
            "latency_ms": total_latency_ms,
            "status": "error" if all(a["status"] == "error" for a in json_answers) else "success"
        }).encode()
        req = urllib.request.Request(f"{HUB}/api/hive/log-feature", data=body,
                                     headers={"Content-Type": "application/json"})
        urllib.request.urlopen(req, timeout=5)
    except Exception:
        pass  # best-effort

    if do_json:
        out = {"question": question, "brains": len(picked), "answers": json_answers}
        if verdict is not None:
            out["verdict"] = verdict
        print(json.dumps(out, indent=2))
    else:
        print()


