def main(argv: list[str]) -> None:
    global HUB
    # Internal: invoked by `hivv start` to fork the agent
    if argv and argv[0] == "_agent":
        from threading import Event
        cmd_agent(Event())
        return

    # Healthcheck: must run BEFORE the smart-default chat fallback (otherwise
    # "healthcheck" would be sent to the LLM as a chat message).
    if argv and argv[0] == "--healthcheck":
        payload = {"ok": True, "version": VERSION, "hub": HUB, "ts": int(time.time())}
        try:
            st = read_state() or {}
            if isinstance(st, dict) and st.get("node_id"):
                payload["node_id"] = st["node_id"]
        except Exception:
            pass
        print(json.dumps(payload))
        sys.exit(0)

    if argv and argv[0] == "--version":
        print(VERSION)
        sys.exit(0)

    # Heal a stale output-capturing launcher (one small file read when healthy;
    # only a stale wrapper triggers a fetch+swap). Must run before command
    # dispatch so `upgrade` and friends can rely on the operator seeing output.
    _refresh_wrapper_if_stale()

    if not argv or argv[0] in ("-h", "--help"):
        _print_root_help()
        return
    # `hivv help …`: bare/-h → root help; `list|submit` → the feedback
    # command (this shortcut used to shadow it — `hivv help submit` printed
    # root help and its parser was unreachable); anything else → FUZZY
    # SEARCH over every command and flag (`hivv help ollama`).
    if argv[0] == "help":
        if len(argv) == 1 or argv[1] in ("-h", "--help"):
            _print_root_help()
            return
        if argv[1] not in ("list", "submit"):
            _help_search(" ".join(argv[1:]))
            return
        # else fall through: cmd_name = "help" reaches COMMANDS["help"]

    cmd_name = argv[0]

    # Resolve dotted subcommand names (e.g. `llm detect` -> `llm detect`).
    # Skip when the next arg is a flag so `hivv llm --help` still resolves to "llm".
    # `llm help` is a special case — it's the parent group's own help, not a subcommand.
    if cmd_name == "llm" and len(argv) > 1 and not argv[1].startswith("-") and argv[1] != "help":
        cmd_name = "llm " + argv[1]

    # `hivv llm restart` (natural inversion of `hivv restart llm`) — without
    # this it fell into the smart-default CHAT trap and just TALKED to the
    # dying server instead of restarting it (Stuarts-iMac, 2026-11-18).
    if cmd_name in ("llm start", "llm stop", "llm restart"):
        _verb, _scope = cmd_name.split()
        argv = [_verb, _scope] + list(argv[2:])
        cmd_name = _verb

    # `sala` is the common alternate spelling of `salah` — same trap family
    # as upgrade/capability: without this it would fall through to CHAT.
    if cmd_name in ("sala", "salat"):
        cmd_name = "salah"
        argv[0] = "salah"

    # `upgrade` is a friendlier alias for `update`. Without this, `hivv upgrade`
    # would fall through to the smart-default chat and send the literal word
    # "upgrade" to the LLM.
    if cmd_name == "upgrade":
        cmd_name = "update"
        argv[0] = "update"
    # `capability` is a documented alias for `cap` but had no parser, so
    # `hivv capability` died in parse_args. Map it like `upgrade` does.
    if cmd_name == "capability":
        cmd_name = "cap"
        argv[0] = "cap"
    # `install llm` used to fall through to the smart-default and get SENT TO
    # THE MODEL as a chat message ("install llm"). Route it to the one-shot
    # installer instead — same trap family as `upgrade`/`capability` above.
    if cmd_name == "install":
        if len(argv) > 1 and argv[1] in ("llm", "model", "models", "ai"):
            argv = ["llm", "setup"] + argv[2:]
            cmd_name = "llm setup"
        elif len(argv) > 1 and argv[1] == "ollama":
            # 2-STEP ollama path (2026-11-25):
            #   step 1  hivv install ollama        → install only (verify, then decide)
            #   step 2  hivv install ollama qwen   → install if needed + pull
            # a bare FAMILY name (qwen/gemma/llama/mistral/phi) resolves to the
            # best SMALL+FAST tag for THIS box; a positional model becomes
            # --model. --help must stay at index 2 (the per-cmd help check) and
            # must NOT come with --auto: argparse's SystemExit(0) then fell
            # through to the self-heal footer ("its own command parser failed")
            # on a perfectly healthy CLI.
            rest = list(argv[2:])
            wants_help = any(a in ("-h", "--help") for a in rest)
            if "--model" not in rest:
                pos = [a for a in rest if not a.startswith("-")]
                if pos:
                    rest = [a for a in rest if a.startswith("-")] + ["--model", pos[0]] + pos[1:]
            argv = ["llm", "install"] + ([] if wants_help else ["--auto"]) + rest
            cmd_name = "llm install"
        else:
            print(f"\033[1m{APP} install\033[0m — what do you want to install?")
            print()
            print(f"  {APP} install llm        one-shot: build llama.cpp + download gemma + serve")
            print(f"  {APP} install ollama     step 1: install ollama only (then verify: ollama --version)")
            print(f"  {APP} install ollama qwen  step 2: install + pull — family picks small & fast for this box")
            print(f"  {APP} llm setup --help   every option (--model, --port, --yes, --fg)")
            print(f"  {APP} itself:            curl -sSL {HUB}/install-hivv.sh | bash")
            return

    # `hivv eval …` is the study bench — never let it fall through to the
    # smart-default and get SENT TO THE MODEL as a chat message ("eval").
    if cmd_name == "eval":
        if len(argv) > 1 and argv[1] == "help":
            _print_sub_help("eval")
            return
        if len(argv) > 1 and not argv[1].startswith("-"):
            if argv[1] in ("run", "cases"):
                cmd_name = "eval " + argv[1]
            else:
                die(f"unknown eval action {argv[1]!r} — try: {APP} eval run · {APP} eval cases")

    # Feedback aliases — an AI studying the hive must be able to REPORT/SUGGEST
    # without falling into the chat smart-default (bare `hivv report ...` used
    # to become the PROMPT "report ..."). No-arg forms print a chooser instead.
    if cmd_name == "report":
        if len(argv) == 1:
            print(f"  {APP} report \"<what's wrong>\"   send a problem report to the hub (humans read these)")
            print(f"  {APP} submit \"<bug>\"          same queue · flag abuse: {APP} flag <bee> \"<what>\"")
            print(f"  {APP} panic                      urgent: diagnostics + how to escalate")
            return
        cmd_name = "submit"
        argv[0] = "submit"
    elif cmd_name == "suggest":
        if len(argv) == 1:
            print(f"  {APP} suggest \"<idea>\"        send a suggestion to the hub (humans read these)")
            print(f"  {APP} llm suggest             which model fits THIS hardware")
            print(f"  {APP} request \"<feature>\"    same queue: request a feature")
            return
        cmd_name = "request"
        argv[0] = "request"

    # Smart default: if argv[0] doesn't match a known subcommand and isn't a flag,
    # treat the whole argv as a chat message to hivv.org. So:
    #   hivv whats the meaning of life
    # becomes a streaming chat call.
    if cmd_name not in COMMANDS or COMMANDS[cmd_name] is None:
        if cmd_name.startswith("-"):
            # an unknown FLAG is usually a typo of a real one — search first
            if _help_search(cmd_name):
                return
            die(f"unknown flag: {cmd_name} — try `{APP} --help`")
        # `hivv ollama help` / `hivv frobnicate --help` → search, don't chat
        if len(argv) == 2 and argv[1] in ("help", "-h", "--help"):
            _help_search(cmd_name)
            return
        # LOUD, not silent (2026-11-23): `hivv if` / `hivv when` looked like
        # they were "taking commands" — they were silently chatting, and one
        # even spent a call that hit a context overflow. An exceptional path
        # that does something clever in silence is worse than a crash.
        #   · single stray word (no ?, not a greeting) → fail loud, no LLM call
        #   · greetings and real questions still go to the hive — visibly
        _CHAT_WORDS = {"hello", "hi", "hey", "yo", "sup", "thanks", "thank"}
        if len(argv) == 1 and "?" not in cmd_name and cmd_name.lower() not in _CHAT_WORDS:
            import difflib
            _close = difflib.get_close_matches(cmd_name, list(COMMANDS), n=1, cutoff=0.7)
            _hint = f" — did you mean `{APP} {_close[0]}`?" if _close else ""
            print(f"  ✗ '{cmd_name}' isn't an {APP} command.{_hint}")
            print(f"    ask the hive:   {APP} chat \"<your question>\"")
            print(f"    ask one bee:    {APP} ask <bee> \"<question>\"")
            print(f"    all commands:   {APP} --help")
            sys.exit(2)
        print(f"  · '{' '.join(argv)}' isn't a command — asking the hive instead "
              f"(use {APP} chat \"…\" to skip this note)")
        _do_chat(" ".join(argv), stream=True)
        return

    # per-cmd --help (use argv[1] for top-level, argv[2] for dotted like `llm detect`)
    help_idx = 2 if cmd_name != argv[0] else 1
    if help_idx < len(argv) and argv[help_idx] in ("-h", "--help"):
        _print_sub_help(cmd_name)
        return

    # `llm help` (and `llm` with no subcommand) should show the parent group's
    # own help — not be parsed as a subcommand choice.
    if cmd_name == "llm" and (len(argv) == 1 or argv[1] == "help"):
        cmd_llm_help(None)
        return

    # ── parse args, with a SELF-HEAL path ──────────────────────────────
    # A bug in the parser (a duplicate subparser, a bad default) makes the
    # CLI unable to run ANY command — including `hivv update`, which is how
    # it would normally fix itself. So a parser failure must offer to
    # re-download the CLI rather than just dying with a traceback.
    try:
        args = build_parser().parse_args(argv)
    except (SystemExit, Exception) as parse_err:
        _self_heal_from_parse_error(parse_err, cmd_name)
        return

    # Global flags
    global PLAIN_OUTPUT, NO_THINK
    PLAIN_OUTPUT = bool(getattr(args, "plain", False))
    NO_THINK = bool(getattr(args, "no_think", False))
    # apply --hub override
    if getattr(args, "hub", None):
        HUB = args.hub
    _normalize_bool_args(args)
    COMMANDS[cmd_name](args)


def _normalize_bool_args(args) -> None:
    """Accept on/off/true/false/1/0 wherever a yes/no word is expected.

    The user asked for `on` and `off` to mean the same as `yes` and `no`
    "for all hivv commands". Doing it ONCE, centrally, means every command
    that takes a yes/no-like word gets it — including the ones added later,
    which nobody has to remember to update.

    Only a STRING attribute is touched: a real `bool` (a `--yes` flag) is
    already a decision, and a list/dict is not a word. The attribute is
    replaced with the canonical "yes"/"no" so existing `== "yes"` checks
    keep working.
    """
    for name, value in list(vars(args).items()):
        if not isinstance(value, str):
            continue
        b = _bool_arg(value)
        if b is None:
            continue
        # Only rewrite a word that MEANT to be a yes/no. A free-text field
        # (a chat message, a node name) must never be rewritten — "on" as a
        # node name would become "yes".
        if name in _BOOL_ARG_NAMES or _looks_like_bool_slot(name):
            setattr(args, name, "yes" if b else "no")


# Attribute names that hold a yes/no-like word. Anything named like a
# boolean decision is included, so `hivv volunteer on`, `hivv boot off` and
# a future `hivv foo yes` all behave the same.
_BOOL_ARG_NAMES = {
    "state", "action", "mode", "opt", "choice", "answer", "value",
    "yes_no", "confirm", "toggle", "switch", "enable", "disable",
    "on", "off", "flag",
}


def _looks_like_bool_slot(name: str) -> bool:
    """True when an attribute NAME suggests it holds a yes/no word."""
    n = name.lower()
    return (n.startswith(("enable", "disable", "auto", "confirm"))
            or n.endswith(("_yes", "_no", "_on", "_off", "_enable", "_disable"))
            or n in ("yes", "no", "on", "off"))


def _self_heal_from_parse_error(parse_err, cmd_name: str) -> None:
    """Offer to repair a CLI whose own parser is broken.

    The installed file is the thing that is broken, so the only real fix is
    to replace it with the copy the hub is serving. This function:
      1. prints the actual error (so the operator can report it),
      2. re-downloads hivv-cli.py from the hub into THIS file's location,
      3. verifies the download is not an HTML error page,
      4. tells the operator to re-run their command.

    It deliberately does NOT auto-restart — the operator should see what
    happened and confirm.
    """
    msg = str(parse_err)
    # USAGE errors are USER mistakes, not a broken CLI — never scare people
    # into overwriting their own file over `missing required model` (the raw
    # "installed CLI is broken" report hit real users, 2026-11-18).
    # NOTE: argparse exits with SystemExit(2) and str() is just "2" — the real
    # text already went to stderr — so exit-code 2 itself is the usage signal.
    _usage_error = (isinstance(parse_err, SystemExit)
                    and getattr(parse_err, "code", None) == 2) or any(
        s in msg for s in ("required:", "unrecognized arguments", "unrecognized option",
                           "invalid choice", "expected one argument",
                           "too many arguments", "the following arguments are"))
    if _usage_error:
        _m = "" if str(msg).strip() == "2" else f": {msg}"
        print(f"\n\033[31m✗\033[0m bad arguments for `{APP} {cmd_name}`{_m}")
        print(f"  see every flag: {APP} {cmd_name} --help")
        return
    B, R = "\033[1m", "\033[0m"
    G, Y, X = "\033[32m", "\033[33m", "\033[31m"

    here = Path(__file__).resolve()
    print(f"\n{X}✗ {APP} could not start — its own command parser failed{R}")
    print(f"  {B}error{R}: {parse_err}")
    print(f"  {B}file{R}:  {here}")
    print(f"  {B}command{R}: {APP} {cmd_name}")
    print()
    print(f"  {Y}this means the installed CLI is broken, including "
          f"`{APP} update`.{R}")
    print(f"  {Y}the fix is to replace it with the copy the hub serves.{R}")
    print()

    # `--healthcheck` and `--version` return before build_parser(), so they
    # still work — prove it so the operator has a working foothold.
    print(f"  {B}still working{R}: {APP} --healthcheck · {APP} --version")
    print()

    # Offer the repair.
    print(f"  {B}to repair now{R}:")
    print(f"    {G}curl -fsSL {HUB}/{APP}-cli.py -o {here}{R}")
    print(f"    {G}python3 {here} --healthcheck{R}   # verify it works")
    print(f"    {G}{APP} {cmd_name}{R}            # re-run what you wanted")
    print()

    # Or from source, if the hub is unreachable.
    print(f"  {B}or from source{R}:")
    print(f"    {G}git clone https://github.com/htmlfarmer/hivv.git{R}")
    print(f"    {G}cp hivv/public_html/{APP}-cli.py {here}{R}")
    print()

    # An explicit repair flag, so the operator can do it in one shot.
    if "--yes" in sys.argv or "-y" in sys.argv:
        print(f"  {Y}--yes given — attempting repair…{R}")
        try:
            import urllib.request
            url = f"{HUB}/{APP}-cli.py"
            with urllib.request.urlopen(url, timeout=30) as r:
                body = r.read()
            head = body[:200].lower()
            if b"<!doctype" in head or b"<html" in head:
                print(f"  {X}✗ the hub returned HTML, not a script — "
                      f"not overwriting{R}")
                return
            # Atomic-ish: write a temp file next to the target, then swap.
            tmp = here.with_name(here.name + ".new")
            tmp.write_bytes(body)
            tmp.chmod(here.stat().st_mode)
            tmp.replace(here)
            print(f"  {G}✓ repaired {here} ({len(body)} bytes){R}")
            print(f"  now run: {APP} {cmd_name}")
        except Exception as e:
            print(f"  {X}✗ repair failed: {e}{R}")
            print(f"  the hub may be down — try the git clone path above")
        return

    print(f"  {Y}add --yes to repair automatically:{R}")
    print(f"    {APP} {cmd_name} --yes")
    print()


def _print_root_help() -> None:
    print(f"""\033[1m{APP}\033[0m — HIVV.org client CLI / local agent
hub = {HUB}   version = {VERSION}

\033[1mOperator / local subcommands:\033[0m
  start              start the local hivv agent (background, heartbeats to hub)
  stop               stop the local hivv agent
  restart            stop + start
  status             pid, uptime, last heartbeat, last error
  logs [N] [-f]      tail ~/.local/share/hivv/agent.log (last N lines; -f to follow)
  free               host memory + swap + disk + per-process RSS
  pct [--watch=N]    live CPU%/MEM% line (refreshes every N seconds)
  info               hub URL, version, install paths, hub_health
  update             pull the latest hivv-cli.py + run health checks
  upgrade            alias for `update`
  uninstall          stop + remove install (keep ~/.config/hivv/ + logs)
  remove             delete one part (llm|models|agent|config|logs|state|everything) — asks first
  salah              prayer times for your region + attendance + moon (alias: sala)
  --help, help       list every subcommand

\033[1mNetwork / cluster:\033[0m
  nodes / bees       table view of all registered bees in the hive
  node / bee <name>  inspect a specific bee (hardware, models, location)
  ask / talk <n> MSG  chat with ONE bee (pins it); node-chat = alias
  chat MSG            ask the HIVE — any bee answers
  reach / waggle <n> test connectivity to another bee on the network
  stats              show per-node stats and cluster totals
  debug              full debug info: hub, agent, local AI, network

\033[1mSecurity:\033[0m
  firewall           check firewall + binding + tailscale status
  doctor --fix     auto-fix bindings + create system services
  firewall --apply   apply firewall rules (--mode lan|tailscale|open)
  identity [rotate]  this bee's Ed25519 key + hub binding (cryptographic identity)

\033[1mOne-shot subcommands (talk to {HUB_NAME}):\033[0m
   health             GET /api/health
   metrics            GET /api/control/metrics/global
   chat MSG...        POST /api/chat  (single message)  --mode=cheap|fast|private|smart
   completions MSG... POST /v1/chat/completions (OpenAI-compatible)
   whoami             GET /api/control/health (cheap liveness check)
   doctor             full health report (install + hub + agent + network + security)
   setup              configure OpenCode + VS Code + local LLM with hivv
   code TASK --repo U ask a coder bee to do a task in a git repo (--wait to watch)

\033[1mBuilding on HIVV (partner API):\033[0m
   partner [manifest|health|network|models|capabilities]  the public partner surface
   fast-scan FILE     deterministic, AI-free source screen (free · instant · no AI)
   local [status|start|stop|info]  a LOCAL self-hosted gateway (no database)
   capabilities       what this instance offers (capability discovery)

\033[1mDebugging & support:\033[0m
   problems           what is breaking globally? (live error log + incidents)
   bug [query]        research a specific problem  --client opencode|vscode|…
   submit "<text>"    file a bug report to the hub
   request "<text>"   request a feature
   flag <tgt> "<text>"  flag another node/user  --severity high
   support "<question>"  ask the AI for help (attaches your diagnostics)
   debug              full local snapshot: hub, agent, local AI, network

\033[1mhivv OS — capabilities · policy · routing · approvals 🐝:\033[0m
   cap [list|can|node]  the capability layer — what the hive can do
   policy [sub]         YES/MAYBE/NO rules (show|explain|history|verify|grants)
   approve [--list|--all|ID]  answer a MAYBE · deny ID ... refuse it
   route [q] --mode=X   dry-run routing planner — who answers and why

\033[1mLocal LLM helper (talks to your own box, not the hub):\033[0m
  llm                show llm subcommands
  llm detect         find ollama, llama.cpp, lm-studio, vllm on this box
  llm suggest        recommend a model for this hardware (CPU/RAM/GPU)
  llm bench          quick CPU / RAM / disk benchmark
  llm status         detect + bench + suggest in one shot
  llm install [--docker]   print install commands for the detected OS
  llm pull <model>         ollama pull <model>
  llm serve [model] [--port]   ollama serve in the foreground

\033[1mExamples:\033[0m
  hivv bees                      see all bees in the hive
  hivv bee yalla                  inspect a specific bee
  hivv ask yalla "hello"         chat with ONE bee (pins it)
  hivv chat 'what is the weather?'  ask the whole hive
  hivv waggle masjid              test if a bee is reachable
  hivv swarm "what is kubernetes?" swarm the question to multiple models
  hivv drone                      am I contributing compute?
  hivv stats                      see cluster performance
  hivv doctor --fix            auto-fix LLM bindings
  hivv doctor                    full health check
  hivv start
  hivv update

Tip: every subcommand accepts --help (e.g. `hivv logs --help`).
""")
    _nag_if_update_available()

def _help_search(query: str) -> bool:
    """FUZZY help — `hivv help ollama`, `hivv ollama help`, `hivv --model`.

    Searches command NAMES, their help text, flags and subcommands from the
    introspected parser index (so it cannot drift from the real commands).
    Returns True when something matched (caller may fall through), False on
    zero hits — then we say so and suggest the real entry points."""
    import difflib
    q = (query or "").strip()
    if not q:
        return False
    ql = q.lower().lstrip("-")
    idx = _argparse_command_index()
    # (name, help, flags, extra-haystack, subcommands) — top level from the
    # index, PLUS nested commands (llm install, eval run …): their flags live
    # on the nested parser, so `hivv help --model` would never reach
    # `llm install` without this walk.
    entries = [(c["command"], c.get("help") or "", c.get("flags") or [],
                " ".join(c.get("subcommands") or []), c.get("subcommands") or [])
               for c in idx["commands"]]
    try:
        p = build_parser()
        for act in p._actions:
            if not isinstance(act, argparse._SubParsersAction):
                continue
            for pname, psub in act.choices.items():
                if pname.startswith("-"):
                    continue
                for a2 in psub._actions:
                    if not isinstance(a2, argparse._SubParsersAction):
                        continue
                    helps = {getattr(ca, "dest", ""): (getattr(ca, "help", "") or "")
                             for ca in getattr(a2, "_choices_actions", [])}
                    for sname, ssub in a2.choices.items():
                        if sname.startswith("-"):
                            continue
                        flags, pos = [], []
                        for a3 in ssub._actions:
                            if isinstance(a3, argparse._SubParsersAction):
                                continue
                            if a3.option_strings:
                                if set(a3.option_strings) <= {"-h", "-help", "--help"}:
                                    continue
                                flags.append({"flag": "/".join(a3.option_strings),
                                              "help": (a3.help or "").strip()})
                            elif a3.dest != "help":
                                pos.append(f"{a3.dest} {a3.help or ''}".strip())
                        entries.append((f"{pname} {sname}", helps.get(sname, ""),
                                        flags, " ".join(pos), []))
    except Exception:
        pass  # introspection is best-effort — help must never crash
    rows = []
    for name, htext, flags, extra, subs in entries:
        hay = " ".join([name, htext,
                        " ".join(f["flag"] + " " + (f.get("help") or "") for f in flags),
                        extra]).lower()
        # score: exact > prefix > substring-in-name > substring-in-haystack
        if name.lower() == ql:
            score = 0
        elif name.lower().startswith(ql):
            score = 1
        elif ql in name.lower():
            score = 2
        elif ql in hay:
            score = 3
        else:
            close = difflib.SequenceMatcher(None, ql, name.lower()).ratio()
            if close < 0.55:
                continue
            score = 4
        rows.append((score, name, htext, flags, subs))
    if not rows:
        # last-ditch: did they mean a known command?
        close = difflib.get_close_matches(ql, [c["command"] for c in idx["commands"]],
                                          n=3, cutoff=0.5)
        print(f"  \033[31m✗\033[0m no help matches '{q}'"
              + (f" — did you mean: {', '.join(close)}?" if close else ""))
        print(f"    every command: {APP} --help  ·  machine-readable: {APP} commands --json")
        return False
    rows.sort(key=lambda r: (r[0], r[1]))
    print(f"\033[1m{APP} help — '{q}'\033[0m  ({len(rows)} match{'es' if len(rows) != 1 else ''})")
    for score, name, htext, flags, subs in rows[:8]:
        mark = "\033[32m" if score <= 1 else ("\033[36m" if score == 2 else "\033[2m")
        print(f"  {mark}{APP} {name}\033[0m")
        h = (htext or "").strip().splitlines()
        if h:
            print(f"      {h[0][:96]}")
        for f in flags[:4]:
            if f.get("flag"):
                print(f"        {f['flag']}  {(f.get('help') or '')[:72]}")
        if subs:
            print(f"        sub: {', '.join(subs[:8])}")
    if len(rows) > 8:
        print(f"  \033[2m… {len(rows) - 8} more — narrow your query\033[0m")
    print(f"  details: {APP} <command> --help")
    return True


