if __name__ == "__main__":
    # Ctrl-C anywhere (mid-stream chat, download, bench) exits CLEANLY — a raw
    # KeyboardInterrupt traceback at the prompt is a bug report, not UX.
    try:
        main(sys.argv[1:])
    except KeyboardInterrupt:
        print()
        sys.exit(130)
